// Goi du lieu 007 - Khoa Hoc lop 5 TRON NAM (v1.24: 11 mua cum 1-11; khong can bo sung cau - goi nguon nen-004-v1 du cho ca nam hoc, cac tap On tap dung co che BE CHU DE qua truong be)
window.__GOI007 = window.__GOI007 || {};
window.__GOI007["khoa-hoc-5"] = {"cacMua": [{"anhBia": "phong-thi-nghiem-dat-me", "anhCanTao": [{"khoa": "phong-thi-nghiem-dat-me", "moTa": "Phòng thí nghiệm đất trong Trạm Khám Phá Xanh: bàn kính dài bày các chậu đất nhiều lớp màu khác nhau, cây non xanh mọc trong chậu, Biệt đội Ánh Sao áo trắng khăn quàng đỏ cầm kính lúp soi mẫu đất, Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) cầm xẻng nhỏ đứng cạnh khay đất; cửa sổ lớn nhìn ra vườn trường, góc phải có vệt sương xám mỏng. Phong cách 3D Pixar, không chữ."}], "cacBai": ["1", "2", "3"], "cacChuDe": ["1"], "id": "kh5-c1", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; dẫn đường cho Biệt đội Ánh Sao trong thế giới Khoa học và là người đưa ra câu cứu viện mang tên mình.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa, hay ghi chép sổ tay.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận nguyên nhân – kết quả trước khi hành động."}, "tap": [{"bai": "1", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Biệt đội Ánh Sao trở lại Trạm Khám Phá Xanh với vai trò trang trọng nhất: lứa nhà khoa học nhí kỳ cựu nhất của Trạm. Robot Hạt Đậu trao cho đội cuốn Sổ Tay Thí Nghiệm bị sương phủ mờ, chờ khôi phục trọn năm học.", "nv": "Người kể"}, {"loi": "Chào mừng trở lại, các nhà khoa học nhí! Phòng đầu tiên là Phòng Đất. Muốn ghi lại trang đầu của Sổ Tay, ta phải nhớ: đất gồm chất khoáng, mùn, nước và không khí đấy!", "nv": "Robot Hạt Đậu"}, {"loi": "Thí nghiệm kinh điển nè: thả một mẫu đất khô vào cốc nước, bọt khí nổi lên — chứng tỏ trong đất có không khí. Còn đun đất trong ống nghiệm sẽ thấy hơi nước thoát ra.", "nv": "Thảo Nguyên"}, {"loi": "Đất không chỉ nuôi cây bằng chất dinh dưỡng, nước và không khí, mà còn giúp cây đứng vững. Mình khôi phục trang đầu của Sổ Tay nhé!", "nv": "Minh Anh"}, {"loi": "Nhà khoa học luôn quan sát kỹ rồi mới kết luận. Bắt đầu từ các mẫu đất trên bàn thí nghiệm nào!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Mẫu đất khô sẵn sàng rồi. Thả nhẹ vào cốc nước và quan sát thật kỹ xem có gì nổi lên nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Mẫu đất vừa chìm xuống cốc nước trong, từng bọt khí nhỏ thi nhau nổi lên mặt nước. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "1", "mucDo": [1], "soCau": 1}}], "nhan": "Thả mẫu đất vào cốc nước"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Chậu kính này trồng cây đậu, nhìn xuyên qua kính thấy rễ đâm sâu xuống đất. Xem rễ đang lấy gì từ đất nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Trong chậu kính, bộ rễ trắng của cây đậu vươn dài giữa các lớp đất, hút lấy từng giọt nước. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "1", "mucDo": [1], "soCau": 1}}], "nhan": "Soi rễ cây trong chậu kính"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ối, sương tràn xuống, bảng ghi thành phần đất nhòe hết chữ rồi!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng là sương tan, số liệu hiện rõ ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "1", "mucDo": [1], "soCau": 1}}, "danChuyen": "Đi sâu vào Phòng Đất, bảng ghi thành phần của đất treo trên tường hiện ra, vài dòng đã bị sương làm nhòe. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "1", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối Phòng Đất là khay cây con xanh mướt. Muốn cây lớn khỏe, phải hiểu đất giúp cây những gì. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "1", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Trang đầu Sổ Tay sáng chữ rồi! Đất có đủ chất khoáng, mùn, nước và không khí — cây trồng được đất ôm ấp đủ bề!", "nv": "Thảo Nguyên"}, {"loi": "Hạt Đậu trao biệt đội Hộp Mẫu Đất Của Trạm. Nhưng kìa — khoảnh đất sau Trạm đang nứt nẻ, rác thải vương vãi... đất quanh Trạm hình như đang ốm!", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình đi khám bệnh cho đất nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Đất có những gì?", "tomTatTapTruoc": "Năm học cuối cấp bắt đầu. Thủ thư Số mở cuốn sách Khoa học lớp 5: Trạm Khám Phá Xanh hiện ra với sáu phòng ban, nhưng Sương Mù Quên Lãng đã phủ mờ các hiện tượng và làm nhòe Sổ Tay Thí Nghiệm của Trạm...", "tuan": "1", "vatPham": "Hộp Mẫu Đất Của Trạm"}, {"bai": "2", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Khoảnh đất sau Trạm ngả màu xám xịt: rác thải, túi ni lông và nước thải làm đất bị ô nhiễm. Phía sườn đồi, trận mưa lớn hôm qua vừa cuốn trôi một lớp đất mặt — đó là xói mòn đất.", "nv": "Người kể"}, {"loi": "Số liệu báo động! Nguyên nhân ô nhiễm đất do con người gây ra gồm rác thải, hóa chất và nước thải nhà máy. Còn xói mòn thường xảy ra ở sườn dốc, nơi nước mưa chảy mạnh cuốn đất đi.", "nv": "Robot Hạt Đậu"}, {"loi": "Muốn cứu đất phải tìm đúng nguyên nhân trước: chỗ nào ô nhiễm thì làm sạch và ngừng xả thải; chỗ nào xói mòn thì trồng cây giữ đất.", "nv": "Đức Trí"}, {"loi": "Hôm nay Biệt đội làm bác sĩ cho đất. Khảo sát quanh Trạm rồi ghi phác đồ cứu đất vào Sổ Tay nhé!", "nv": "Minh Anh"}, {"loi": "Nhớ nhé: phá rừng trên sườn đồi làm đất mất cây che phủ, mưa xuống là xói mòn càng nặng đấy!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "cau-suong", "dong": [{"loi": "Sườn đồi sau Trạm trơ cả gốc cây sau trận mưa. Nhìn dòng nước đục cuốn theo đất kìa!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Đứng trên sườn đồi nhìn xuống, vệt đất bị nước mưa cuốn trôi hiện rõ thành rãnh sâu. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "2", "mucDo": [1], "soCau": 1}}], "nhan": "Khảo sát sườn đồi sau cơn mưa"}, {"canh": [{"anh": "canh-chu", "dong": [{"loi": "Gần bãi rác sau Trạm, đất đổi màu và có mùi lạ. Mình lấy mẫu về soi để tìm nguyên nhân nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Mẫu đất lấy gần bãi rác được đưa lên bàn soi, màu đất sẫm bất thường. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "2", "mucDo": [1], "soCau": 1}}], "nhan": "Soi mẫu đất gần bãi rác"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ơ, sương phủ xuống, bảng biện pháp bảo vệ đất mờ đi rồi!", "nv": "Thảo Nguyên"}, {"loi": "Bình tĩnh nào! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng, chữ trên bảng sẽ hiện rõ lại ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "2", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa sân Trạm là tấm bảng lớn ghi các biện pháp bảo vệ môi trường đất, vài dòng đã mờ vì sương. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "2", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi, Hạt Đậu mở trang vận động cộng đồng trong Sổ Tay: cứu đất xong còn phải rủ mọi người cùng giữ đất. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "2", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Phác đồ cứu đất hoàn chỉnh rồi! Đất sạch, sườn đồi có cây che phủ thì mưa lớn cũng khó cuốn trôi.", "nv": "Đức Trí"}, {"loi": "Hạt Đậu trao biệt đội Chiếc Xẻng Trồng Cây Xanh. Nhưng nghe nói ngăn pha chế của Phòng Đất đang lộn xộn — muối, tiêu, đường trộn lẫn cả vào nhau...", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình sang ngăn pha chế, phân biệt hỗn hợp và dung dịch nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Cứu lấy đất đang ốm", "tomTatTapTruoc": "Tập trước: Biệt đội khôi phục trang đầu Sổ Tay Thí Nghiệm về thành phần của đất và nhận Hộp Mẫu Đất Của Trạm. Cuối tập, khoảnh đất sau Trạm nứt nẻ, rác vương vãi — đất đang ốm...", "tuan": "2–3", "vatPham": "Chiếc Xẻng Trồng Cây Xanh"}, {"bai": "3", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Ngăn pha chế của Phòng Đất bày la liệt cốc, lọ: muối trộn hạt tiêu, đường cát, nước lọc. Sương Mù đã làm mờ hết nhãn dán, chẳng ai phân biệt nổi đâu là hỗn hợp, đâu là dung dịch.", "nv": "Người kể"}, {"loi": "Nhớ nguyên tắc nhé: hỗn hợp gồm hai hay nhiều chất trộn lẫn mà vẫn nhìn thấy từng chất. Còn dung dịch là hỗn hợp mà một chất tan đều vào chất kia, trong suốt, không còn nhìn thấy chất tan nữa!", "nv": "Robot Hạt Đậu"}, {"loi": "Ví dụ dễ nhớ: muối trộn hạt tiêu vẫn thấy từng hạt — là hỗn hợp. Muối khuấy vào nước đến khi tan hết, không thấy muối nữa — là dung dịch!", "nv": "Thảo Nguyên"}, {"loi": "Phân loại đúng từng cốc là nhãn dán sáng lại. Mình bắt đầu pha chế và quan sát nhé!", "nv": "Minh Anh"}, {"loi": "Và nhớ: muốn tách muối ra khỏi dung dịch nước muối, ta đun hoặc phơi nắng cho nước bay hơi, muối sẽ ở lại.", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Đĩa muối và đĩa hạt tiêu đây. Trộn hai thứ vào nhau rồi nhìn kỹ xem còn thấy từng hạt không nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Trong chiếc đĩa sứ, muối trắng và hạt tiêu đen trộn lẫn mà vẫn phân biệt rõ từng hạt. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "3", "mucDo": [1], "soCau": 1}}], "nhan": "Trộn muối với hạt tiêu"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Cốc nước trong sẵn sàng. Cho muối vào và khuấy đều, xem muối biến đi đâu nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Thìa khuấy xoay tròn trong cốc nước, hạt muối tan dần cho đến khi không còn nhìn thấy nữa. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "3", "mucDo": [1], "soCau": 1}}], "nhan": "Khuấy muối vào cốc nước"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Sương kéo tới làm mờ nhãn các cốc thí nghiệm rồi!", "nv": "Minh Anh"}, {"loi": "Có Hạt Đậu đây! Câu cứu viện của Robot Hạt Đậu sẽ làm sương tan ngay — trả lời đúng nhé!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "3", "mucDo": [1], "soCau": 1}}, "danChuyen": "Đi sâu vào ngăn pha chế, dãy cốc thí nghiệm của Trạm xếp thành hàng, nhãn cốc nào cũng mờ một nửa. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "3", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối ngăn pha chế là chiếc chảo muối lớn của Trạm. Muốn thu lại muối từ nước muối, phải nhờ nắng và lửa giúp sức. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "3", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Nhãn các cốc sáng rõ rồi! Hỗn hợp nhìn thấy từng chất, dung dịch tan đều trong suốt — mình phân biệt ngon ơ!", "nv": "Thảo Nguyên"}, {"loi": "Hạt Đậu trao biệt đội Chiếc Cốc Đong Dung Dịch. Nhìn kìa — sương đang tụ thành khiên dày trước Cổng Phòng Đất ở cuối phòng!", "nv": "Robot Hạt Đậu"}, {"loi": "Đó là cổng đầu tiên của năm học cuối cấp. Cả lớp ơi, tập đặc biệt — cùng phá Cổng Phòng Đất nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t3", "ten": "Tập 3 — Hỗn hợp hay dung dịch?", "tomTatTapTruoc": "Tập trước: Biệt đội khám bệnh cho đất, ghi phác đồ chống ô nhiễm và xói mòn, nhận Chiếc Xẻng Trồng Cây Xanh. Cuối tập, ngăn pha chế của Phòng Đất lộn xộn muối, tiêu, đường...", "tuan": "3–4", "vatPham": "Chiếc Cốc Đong Dung Dịch"}, {"bai": "1+2+3", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Mấy nhà khoa học nhí mà đòi mở Cổng Phòng Đất của ta sao? Hiện tượng ở đây đã bị ta làm mờ hết rồi!", "nv": "Sương Mù"}, {"loi": "Đừng sợ! Đây là Máy Quang Hợp — cỗ máy trung tâm của Trạm. Trả lời đúng, từng bánh răng của máy sẽ sáng lên; đủ bốn bánh răng sáng, khiên sương trước Cổng Phòng Đất sẽ vỡ tan!", "nv": "Robot Hạt Đậu"}, {"loi": "Biệt đội Ánh Sao sẵn sàng! Cả lớp bình tĩnh quan sát, suy luận rồi chọn đáp án đúng nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Bánh răng thứ nhất của Máy Quang Hợp chờ khởi động: hãy nhớ lại thành phần và vai trò của đất đối với cây trồng. Chọn đáp án đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "1", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Khiên sương rung lên! Bánh răng thứ hai cần kiến thức bảo vệ môi trường đất. Cả lớp chọn đáp án đúng nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "2", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù dồn sức vào màn hỗn hợp và dung dịch. Chọn đáp án đúng để bánh răng thứ ba sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "3", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối cùng! Máy Quang Hợp cần một câu hỏi khó về đất và cây trồng. Chọn đáp án đúng để phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "1", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Bốn bánh răng sáng bừng! Cổng Phòng Đất mở rồi! Sổ Tay Thí Nghiệm ghi trọn kiến thức Chủ đề Chất phần đầu: đất, bảo vệ đất, hỗn hợp và dung dịch.", "nv": "Robot Hạt Đậu"}, {"loi": "Nhận Chìa Cổng Phòng Đất nào. Phía trước là Xưởng Ba Thể Kỳ Diệu — nơi khối băng biết tan thành nước, nước biết hóa thành hơi đấy!", "nv": "Minh Anh"}, {"loi": "Khà... qua được cổng đất thì sao? Xưởng Ba Thể của ta còn mờ hơn nhiều...", "nv": "Sương Mù"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Phòng Đất", "tomTatTapTruoc": "Biệt đội đã khôi phục kiến thức về thành phần của đất, cách cứu đất khỏi ô nhiễm và xói mòn, cùng bí quyết phân biệt hỗn hợp và dung dịch. Giờ đây, Sương Mù Quên Lãng dựng khiên sương trước Cổng Phòng Đất...", "tuan": "3–4", "vatPham": "Chìa Cổng Phòng Đất"}], "tenMua": "Mùa 1 — Phòng Thí Nghiệm Đất Mẹ", "tomTatMua": "Trạm Khám Phá Xanh là thế giới Khoa học trong Thư viện Ánh Sao — một trạm nghiên cứu xanh tươi với phòng thí nghiệm, vườn ươm và bể quan sát. Năm cuối cấp, Biệt đội Ánh Sao trở lại Trạm với vai trò nhà khoa học nhí kỳ cựu nhất, cùng Robot Hạt Đậu khôi phục cuốn Sổ Tay Thí Nghiệm bị Sương Mù Quên Lãng làm nhòe. Mùa đầu tiên ở Phòng Đất, đội tìm hiểu thành phần và vai trò của đất, khám bệnh cho đất bị ô nhiễm và xói mòn, rồi phân biệt hỗn hợp và dung dịch — để tiến tới Cổng Phòng Đất. Sương Mù không xóa chữ ở thế giới này; nó làm mờ hiện tượng và nhòe sổ tay, chờ cơ hội ở từng phòng ban của Trạm."}, {"anhBia": "xuong-ba-the-ky-dieu", "anhCanTao": [{"khoa": "xuong-ba-the-ky-dieu", "moTa": "Xưởng trạng thái kỳ diệu trong Trạm Khám Phá Xanh: khối băng lớn đang tan thành vũng nước, ấm nước bốc hơi nghi ngút, bình nước trong suốt đặt cạnh nhau thành bộ ba băng – nước – hơi; Biệt đội Ánh Sao áo trắng khăn quàng đỏ quan sát sau tấm kính an toàn, Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) chỉ vào cột hơi nước; sương xám lẩn ở góc xa. Phong cách 3D Pixar, không chữ."}], "beCum": {"cacBai": ["1", "2", "3", "4", "5", "6"], "moTa": "Cơ chế BỂ CHỦ ĐỀ (Khoa học lớp 5): tập Ôn tập chủ đề Chất (Bài 6) rút câu từ bể chung gồm toàn bộ câu trắc nghiệm có phương án của các bài 1–6 thuộc Chủ đề 1. Chất, lọc theo mucDo đã khai trong rutCau, không lặp trong cùng một tập. Trường rutCau.bai là bài Ôn tập; trường rutCau.be là danh sách bài của chủ đề."}, "cacBai": ["4", "5", "6"], "cacChuDe": ["1"], "id": "kh5-c2", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; dẫn đường cho Biệt đội Ánh Sao trong thế giới Khoa học và là người đưa ra câu cứu viện mang tên mình.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa, hay ghi chép sổ tay.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận nguyên nhân – kết quả trước khi hành động."}, "tap": [{"bai": "4", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Xưởng Ba Thể Kỳ Diệu sáng lấp lánh: một khối băng lớn trong tủ kính, bình nước trong suốt và ấm nước đang bốc hơi. Nhưng sương đã làm mờ các bảng ghi đặc điểm của từng trạng thái.", "nv": "Người kể"}, {"loi": "Ôn lại nguyên tắc ba thể nhé: chất rắn có hình dạng và thể tích xác định; chất lỏng có thể tích xác định nhưng hình dạng theo vật chứa và biết chảy; chất khí không có hình dạng, thể tích xác định, lan tỏa khắp nơi và có thể nén lại!", "nv": "Robot Hạt Đậu"}, {"loi": "Thí nghiệm hay nè: bơm tiêm bịt kín, ấn ruột bơm vào được một đoạn — chứng tỏ chất khí nén được. Còn cát đổ vào cốc lấy hình cốc nhưng từng hạt vẫn rắn chắc.", "nv": "Tuấn Kiệt"}, {"loi": "Mình khôi phục bảng đặc điểm ba trạng thái của Xưởng nhé!", "nv": "Minh Anh"}, {"loi": "Nhớ phân biệt rõ: biến đổi trạng thái chỉ thay hình thái, chất vẫn là chất đó — như nến chảy ra rồi đông lại vẫn là nến.", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Khối băng trong tủ kính giữ nguyên hình khối sắc cạnh. Sờ thử qua kính và quan sát kỹ nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Khối băng trong tủ kính trong suốt giữ nguyên hình dạng, bề mặt lạnh buốt đọng hơi sương. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "4", "mucDo": [1], "soCau": 1}}], "nhan": "Quan sát khối băng trong tủ kính"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Bình nước này đổ sang chai cao, rồi sang bát rộng — xem nước đổi hình thế nào nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Dòng nước trong bình chảy sang chiếc bát rộng, mặt nước đổi hình theo đúng lòng bát. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "4", "mucDo": [1], "soCau": 1}}], "nhan": "Đổ nước qua các chai khác nhau"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ơ, sương phủ xuống, bảng ghi hiện tượng biến đổi trạng thái mờ hết rồi!", "nv": "Thảo Nguyên"}, {"loi": "Bình tĩnh nào! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng, chữ trên bảng sẽ hiện rõ lại ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "4", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa Xưởng là bàn thí nghiệm nến và sô-cô-la, bảng ghi các hiện tượng biến đổi trạng thái đã mờ đi vì sương. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "4", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối Xưởng, ấm nước sôi bốc hơi gặp nắp lạnh thành giọt, cạnh đó là ngăn đá đang kết băng. Chuỗi biến đổi trạng thái hiện ra trọn vẹn. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "4", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bảng ba thể sáng rõ rồi! Rắn xác định, lỏng chảy theo vật chứa, khí lan tỏa và nén được — nhớ vanh vách!", "nv": "Đức Trí"}, {"loi": "Hạt Đậu trao biệt đội Chiếc Nhiệt Kế Ba Thể. Nhưng kìa — góc xưởng có chiếc đinh sắt vừa đổi màu nâu đỏ, tờ giấy cháy dở thành tro đen... có hiện tượng lạ hơn biến đổi trạng thái đang xảy ra!", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình điều tra hiện tượng chất biến thành chất khác nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Ba trạng thái của chất", "tomTatTapTruoc": "Mùa trước: Biệt đội phá Cổng Phòng Đất, nhận Chìa Cổng Phòng Đất. Phía trước là Xưởng Ba Thể Kỳ Diệu, nơi băng, nước và hơi nước thay nhau biến hình...", "tuan": "4–5", "vatPham": "Chiếc Nhiệt Kế Ba Thể"}, {"bai": "5", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Góc điều tra của Xưởng Ba Thể bày những mẫu vật kỳ lạ: chiếc đinh gỉ sét, mẩu giấy cháy đen, thìa đường đun đến vàng nâu. Sương Mù đã làm nhòe hết phiếu điều tra của Trạm.", "nv": "Người kể"}, {"loi": "Đây là biến đổi hoá học: chất này biến thành chất khác hẳn — giấy cháy thành tro và khói, sắt gỉ thành lớp nâu đỏ xốp, đường đun nóng đổi cả màu lẫn vị!", "nv": "Robot Hạt Đậu"}, {"loi": "Phải thật tỉnh táo: xé nhỏ tờ giấy, đun chảy bơ, pha loãng cồn với nước — các chất vẫn là chính chúng, đó KHÔNG phải biến đổi hoá học đâu.", "nv": "Đức Trí"}, {"loi": "Hôm nay Biệt đội làm thám tử hiện tượng: phân loại đúng từng mẫu vật là phiếu điều tra sáng lại!", "nv": "Minh Anh"}, {"loi": "Và nhớ bài học an toàn: đốt bếp than trong phòng kín sinh khí độc vô hình — tuyệt đối không sưởi ấm như vậy nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "cau-suong", "dong": [{"loi": "Hàng rào sắt ngoài sân để lâu ngoài trời, lớp sơn bong ra, vệt nâu đỏ lan dần. Xem kỹ hiện tượng này nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Vệt gỉ nâu đỏ bám trên thanh hàng rào sắt, lớp kim loại bên dưới bị ăn mòn xốp đi. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "5", "mucDo": [1], "soCau": 1}}], "nhan": "Ngắm vệt gỉ trên hàng rào sắt"}, {"canh": [{"anh": "canh-chu", "dong": [{"loi": "Mẩu giấy cháy dở trong khay sứ: phần đen thành tro, phần trắng còn nguyên. Soi và so sánh hai phần nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Dưới kính soi, phần giấy cháy đen giòn tan thành tro, khác hẳn phần giấy trắng mềm còn lại. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "5", "mucDo": [1], "soCau": 1}}], "nhan": "Soi mẫu giấy cháy thành tro"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ối, sương tràn xuống, bảng phân loại hiện tượng mờ hết các ô rồi!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng là sương tan, các ô phân loại hiện rõ ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "5", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa phòng điều tra là bảng phân loại hiện tượng của Trạm, các ô phân loại đã bị sương che mờ. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "5", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi điều tra, Hạt Đậu mở trang tình huống đời sống: ở nhà, hiện tượng nào quanh em là biến đổi hoá học? Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "5", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Phiếu điều tra hoàn chỉnh rồi! Chất biến thành chất khác mới là biến đổi hoá học — phân loại chuẩn không cần chỉnh!", "nv": "Thảo Nguyên"}, {"loi": "Hạt Đậu trao biệt đội Mẫu Đường Vàng Biết Kể Chuyện. Chủ đề Chất sắp khép lại — tấm Sơ đồ Chủ đề trên tường Phòng Đất đang chờ được tổng ôn đấy!", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình về Phòng Đất, làm trạm tổng ôn Chủ đề Chất nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Khi chất biến thành chất khác", "tomTatTapTruoc": "Tập trước: Biệt đội khôi phục bảng đặc điểm ba trạng thái và nhận Chiếc Nhiệt Kế Ba Thể. Cuối tập, chiếc đinh sắt đổi màu nâu đỏ, tờ giấy cháy thành tro — một hiện tượng lạ hơn đang chờ điều tra...", "tuan": "5–6", "vatPham": "Mẫu Đường Vàng Biết Kể Chuyện"}, {"bai": "6", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Biệt đội quay lại Phòng Đất. Trên tường là tấm Sơ đồ Chủ đề Chất khổ lớn tóm tắt cả chủ đề — nhưng sương đã làm mờ gần hết các ô kiến thức, từ đất, hỗn hợp đến ba trạng thái và biến đổi hoá học.", "nv": "Người kể"}, {"loi": "Hôm nay là buổi tổng ôn: câu hỏi sẽ rút từ BỂ CHỦ ĐỀ — toàn bộ kiến thức Chủ đề Chất gộp lại. Ôn đều cả năm bài: đất và cây trồng, bảo vệ đất, hỗn hợp và dung dịch, ba trạng thái, biến đổi hoá học nhé!", "nv": "Robot Hạt Đậu"}, {"loi": "Tổng ôn hay nhất là nối các kiến thức lại: đất tốt nhờ thành phần đầy đủ; chất quanh ta lúc thì đổi trạng thái, lúc thì biến thành chất mới.", "nv": "Đức Trí"}, {"loi": "Khôi phục đủ các ô của sơ đồ là Chủ đề Chất khép lại trọn vẹn. Bắt đầu tổng ôn nào!", "nv": "Minh Anh"}, {"loi": "Mình ôn theo vòng: đất trước, hỗn hợp sau, rồi ba thể và biến đổi hoá học — không sót mảng nào!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Góc sơ đồ về đất đây: thành phần của đất và cách bảo vệ đất. Ôn lại từ đầu nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Ô sơ đồ về đất trên tường hiện mờ hai mảng: thành phần đất và biện pháp bảo vệ môi trường đất. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "6", "be": ["1", "2", "3", "4", "5", "6"], "mucDo": [1], "soCau": 1}}], "nhan": "Ôn lại đất và cây trồng"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Góc sơ đồ về hỗn hợp và dung dịch đây. Nhớ lại muối – tiêu và cốc nước muối nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Ô sơ đồ về hỗn hợp và dung dịch hiện hai chiếc cốc mờ: một cốc thấy rõ từng hạt, một cốc trong suốt. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "6", "be": ["1", "2", "3", "4", "5", "6"], "mucDo": [1], "soCau": 1}}], "nhan": "Ôn lại hỗn hợp và dung dịch"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Sương dồn xuống ô trung tâm của sơ đồ rồi!", "nv": "Minh Anh"}, {"loi": "Có Hạt Đậu đây! Câu cứu viện của Robot Hạt Đậu sẽ làm sương tan ngay — trả lời đúng nhé!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "6", "be": ["1", "2", "3", "4", "5", "6"], "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa tấm sơ đồ là ô trung tâm nối các mảng kiến thức của cả chủ đề, sương phủ dày nhất ở ô này. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "6", "be": ["1", "2", "3", "4", "5", "6"], "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi tổng ôn, chỉ còn ô vận dụng đời sống của sơ đồ: dùng kiến thức cả chủ đề để xử lý tình huống thật. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "6", "be": ["1", "2", "3", "4", "5", "6"], "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Tấm Sơ đồ Chủ đề Chất sáng đủ mọi ô rồi! Cả chủ đề gói gọn trong một tấm sơ đồ — tổng ôn thế này nhớ lâu thật!", "nv": "Đức Trí"}, {"loi": "Hạt Đậu trao biệt đội Tấm Sơ Đồ Chủ Đề Chất. Nhìn kìa — sương đang tụ thành khiên dày trước Cổng Xưởng Ba Thể ở cuối xưởng!", "nv": "Robot Hạt Đậu"}, {"loi": "Cổng thứ hai của năm đang chờ. Cả lớp ơi, tập đặc biệt — cùng phá Cổng Xưởng Ba Thể nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t3", "ten": "Tập 3 — Trạm tổng ôn: Sơ đồ Chủ đề Chất", "tomTatTapTruoc": "Tập trước: Biệt đội điều tra biến đổi hoá học, phân loại đúng đinh gỉ, giấy cháy, đường đun và nhận Mẫu Đường Vàng Biết Kể Chuyện. Chủ đề Chất sắp khép lại, tấm Sơ đồ Chủ đề trên tường Phòng Đất chờ được tổng ôn...", "tuan": "6", "vatPham": "Tấm Sơ Đồ Chủ Đề Chất"}, {"bai": "4+5+6", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Mấy nhà khoa học nhí mà đòi mở Cổng Xưởng Ba Thể của ta sao? Hiện tượng ở đây đã bị ta làm mờ hết rồi!", "nv": "Sương Mù"}, {"loi": "Đừng sợ! Đây là Máy Quang Hợp — cỗ máy trung tâm của Trạm. Trả lời đúng, từng bánh răng của máy sẽ sáng lên; đủ bốn bánh răng sáng, khiên sương trước Cổng Xưởng Ba Thể sẽ vỡ tan!", "nv": "Robot Hạt Đậu"}, {"loi": "Biệt đội Ánh Sao sẵn sàng! Cả lớp bình tĩnh quan sát, suy luận rồi chọn đáp án đúng nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Bánh răng thứ nhất của Máy Quang Hợp chờ khởi động: hãy nhớ lại đặc điểm ba trạng thái của chất. Chọn đáp án đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "4", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Khiên sương rung lên! Bánh răng thứ hai cần kiến thức biến đổi hoá học. Cả lớp chọn đáp án đúng nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "5", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù dồn sức vào màn tổng ôn cả Chủ đề Chất. Chọn đáp án đúng để bánh răng thứ ba sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "6", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối cùng! Máy Quang Hợp cần một câu hỏi khó về biến đổi hoá học trong đời sống. Chọn đáp án đúng để phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "5", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Bốn bánh răng sáng bừng! Cổng Xưởng Ba Thể mở rồi! Chủ đề Chất chính thức khép lại trong Sổ Tay Thí Nghiệm — trọn vẹn từ đất đến biến đổi hoá học.", "nv": "Robot Hạt Đậu"}, {"loi": "Nhận Chìa Cổng Xưởng Ba Thể nào. Phía trước là Đài Năng Lượng — nơi bóng đèn, chong chóng và dòng nước cùng kể chuyện năng lượng!", "nv": "Minh Anh"}, {"loi": "Khà... Chất xong thì sao? Năng lượng là sân của ta mờ nhất đấy...", "nv": "Sương Mù"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Xưởng Ba Thể", "tomTatTapTruoc": "Biệt đội đã nắm vững ba trạng thái của chất, nhận diện biến đổi hoá học và tổng ôn trọn Chủ đề Chất qua tấm sơ đồ. Giờ đây, Sương Mù Quên Lãng dựng khiên sương trước Cổng Xưởng Ba Thể...", "tuan": "6", "vatPham": "Chìa Cổng Xưởng Ba Thể"}], "tenMua": "Mùa 2 — Xưởng Ba Thể Kỳ Diệu", "tomTatMua": "Chủ đề Chất đi vào chặng cuối ở Xưởng Ba Thể Kỳ Diệu — xưởng thí nghiệm nơi băng tan thành nước, nước hóa thành hơi ngay trước mắt. Biệt đội khôi phục bảng đặc điểm ba trạng thái rắn, lỏng, khí, làm thám tử điều tra biến đổi hoá học qua đinh gỉ, giấy cháy và đường đun, rồi trở về Phòng Đất tổng ôn cả chủ đề qua tấm Sơ đồ Chủ đề Chất — để tiến tới Cổng Xưởng Ba Thể. Sương Mù Quên Lãng vẫn rình rập, làm mờ từng hiện tượng vừa được ghi chép."}, {"anhBia": "tram-dien-sang-bung", "anhCanTao": [{"khoa": "tram-dien-sang-bung", "moTa": "Trạm điện rực sáng trong Trạm Khám Phá Xanh: bảng mạch điện khổng lồ với bóng đèn vàng sáng bừng, viên pin lớn và dây điện nhiều màu nối thành mạch kín; Biệt đội Ánh Sao áo trắng khăn quàng đỏ cùng lắp mạch, Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) cầm bóng đèn dự phòng; tia sáng ấm áp, một góc ảnh còn một bóng đèn bị sương xám phủ mờ. Phong cách 3D Pixar, không chữ."}], "cacBai": ["7", "8", "9"], "cacChuDe": ["2"], "id": "kh5-c3", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; dẫn đường cho Biệt đội Ánh Sao trong thế giới Khoa học và là người đưa ra câu cứu viện mang tên mình.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa, hay ghi chép sổ tay.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận nguyên nhân – kết quả trước khi hành động."}, "tap": [{"bai": "7", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Đài Năng Lượng là trái tim của Trạm Khám Phá Xanh: đèn, quạt, guồng nước, chong chóng đều cần năng lượng mới hoạt động. Sương Mù đã làm mờ tấm bảng lớn ghi các nguồn năng lượng của Trạm.", "nv": "Người kể"}, {"loi": "Nhớ nguyên tắc mở đầu chủ đề nhé: con người dùng năng lượng cho mọi hoạt động sống, học tập, lao động. Năng lượng của chính chúng ta lấy từ thức ăn đấy!", "nv": "Robot Hạt Đậu"}, {"loi": "Các nguồn năng lượng thông dụng quanh ta: Mặt Trời sưởi ấm và phơi khô, gió quay chong chóng và đẩy thuyền buồm, nước chảy quay guồng, chất đốt đun nấu, điện thắp sáng.", "nv": "Thảo Nguyên"}, {"loi": "Mình khôi phục bảng nguồn năng lượng để Đài sáng lên nhé!", "nv": "Minh Anh"}, {"loi": "Quan sát kỹ từng hoạt động rồi mới kết luận nó dùng nguồn năng lượng nào — đó là cách của nhà khoa học.", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Hàng chong chóng giấy trên bệ cửa đứng im phăng phắc. Phải tìm nguồn năng lượng cho chúng quay lại thôi!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Hàng chong chóng giấy nhiều màu đứng im trên bệ, chờ một luồng gió thổi qua. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "7", "mucDo": [1], "soCau": 1}}], "nhan": "Tìm nguồn cho chong chóng quay"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Chiếc khăn thí nghiệm ướt sũng cần phơi khô. Ngoài vườn nắng đang lên đẹp lắm!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Chiếc khăn ướt được vắt lên dây phơi giữa vườn, nắng vàng rải đều trên mặt vải. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "7", "mucDo": [1], "soCau": 1}}], "nhan": "Ra vườn phơi khô chiếc khăn ướt"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ối, sương tràn xuống, bảng nguồn năng lượng nhòe hết chữ rồi!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng là sương tan, bảng sáng rõ ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "7", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa Đài là tấm bảng nguồn năng lượng khổ lớn, các ô ghi hoạt động và nguồn năng lượng đã bị sương làm nhòe. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "7", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối Đài, chiếc xe đạp tập của Trạm đứng chờ: ai đó phải đạp xe để phát điện thắp bóng đèn nhỏ trên bàn. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "7", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bảng nguồn năng lượng sáng rõ rồi! Mặt Trời, gió, nước chảy, chất đốt, điện và cả thức ăn cho cơ thể — năng lượng ở khắp nơi!", "nv": "Thảo Nguyên"}, {"loi": "Hạt Đậu trao biệt đội Chiếc Chong Chóng Năng Lượng. Nhưng cẩn thận — phòng điện của Đài vừa báo có đoạn dây điện bị hở, nguy hiểm lắm!", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình học dùng điện an toàn và tiết kiệm nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Năng lượng ở khắp nơi", "tomTatTapTruoc": "Mùa trước: Biệt đội phá Cổng Xưởng Ba Thể, khép trọn Chủ đề Chất. Phía trước là Đài Năng Lượng của Trạm — nhưng cả đài đang tối om vì sương che mờ bảng nguồn năng lượng...", "tuan": "7", "vatPham": "Chiếc Chong Chóng Năng Lượng"}, {"bai": "8", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Phòng điện của Đài Năng Lượng treo đầy biển cảnh báo. Một đoạn dây điện bị hở lõi đồng, ổ cắm nứt vỏ — Sương Mù còn làm mờ các quy tắc an toàn điện dán trên tường.", "nv": "Người kể"}, {"loi": "Ghi nhớ quy tắc vàng nhé: rút phích cắm phải cầm vào thân phích, không giật dây; không sấy tóc khi đứng trên sàn nhà tắm ướt; thấy dây điện hở phải tránh xa và báo ngay cho người lớn!", "nv": "Robot Hạt Đậu"}, {"loi": "Trước khi thay bóng đèn hay sửa thiết bị điện, việc đầu tiên là ngắt nguồn điện. An toàn luôn đi trước, nhanh sau.", "nv": "Đức Trí"}, {"loi": "Hôm nay Biệt đội kiểm tra an toàn khắp phòng điện, rồi học thêm cách tiết kiệm điện cho Trạm nhé!", "nv": "Minh Anh"}, {"loi": "Tiết kiệm điện dễ lắm: tắt đèn, quạt khi ra khỏi phòng; mở tủ lạnh lâu là hơi lạnh thoát hết, tốn điện vô ích đấy!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "cau-suong", "dong": [{"loi": "Đoạn dây điện ngoài sân bị trầy vỏ sau cơn bão. Mình đứng từ xa quan sát và xử lý đúng quy tắc nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Đoạn dây điện treo thấp ngoài sân Trạm, một chỗ vỏ bị trầy lộ lõi đồng bên trong. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "8", "mucDo": [1], "soCau": 1}}], "nhan": "Kiểm tra dây điện ngoài sân Trạm"}, {"canh": [{"anh": "canh-chu", "dong": [{"loi": "Ổ cắm và phích cắm mẫu của Trạm đây. Soi kỹ để phân biệt phích tốt và phích nguy hiểm nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Dưới kính soi, chiếc phích cắm nguyên vẹn nằm cạnh chiếc phích nứt vỏ, dây sờn. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "8", "mucDo": [1], "soCau": 1}}], "nhan": "Soi ổ cắm và phích cắm dưới kính"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ơ, sương phủ xuống, bảng quy tắc an toàn điện mờ đi rồi!", "nv": "Thảo Nguyên"}, {"loi": "Bình tĩnh nào! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng, chữ trên bảng sẽ hiện rõ lại ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "8", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa phòng điện là bảng quy tắc sử dụng điện của Trạm, vài dòng quan trọng đã mờ vì sương. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "8", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi kiểm tra, Hạt Đậu mở trang vận động gia đình: dùng điện sao cho vừa an toàn vừa tiết kiệm mỗi ngày. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "8", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bảng quy tắc sáng rõ rồi! Cầm thân phích khi rút, tránh xa dây hở, tắt điện khi không dùng — an toàn và tiết kiệm song hành!", "nv": "Đức Trí"}, {"loi": "Hạt Đậu trao biệt đội Tấm Biển Vàng An Toàn Điện. Sẵn đà này, tập sau mình tự tay lắp một mạch điện thắp sáng hoàn chỉnh nhé!", "nv": "Robot Hạt Đậu"}, {"loi": "Hay quá! Mình sang bàn lắp mạch của Đài nào!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Dùng điện an toàn, tiết kiệm", "tomTatTapTruoc": "Tập trước: Biệt đội khôi phục bảng nguồn năng lượng và nhận Chiếc Chong Chóng Năng Lượng. Cuối tập, phòng điện của Đài báo có đoạn dây điện bị hở — nguy hiểm đang chờ...", "tuan": "8", "vatPham": "Tấm Biển Vàng An Toàn Điện"}, {"bai": "9", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Bàn lắp mạch của Đài Năng Lượng bày sẵn pin, bóng đèn, dây dẫn và công tắc. Nhưng sơ đồ mạch trên tường bị sương làm mờ, chẳng ai nhớ nổi thứ tự lắp.", "nv": "Người kể"}, {"loi": "Mạch điện thắp sáng đơn giản gồm: nguồn điện (pin), dây dẫn, công tắc và bóng đèn. Khi công tắc đóng, mạch kín, dòng điện chạy qua nên đèn sáng; công tắc mở, mạch hở, đèn tắt!", "nv": "Robot Hạt Đậu"}, {"loi": "Bí mật của dây điện nè: lõi đồng dẫn điện tốt, vỏ nhựa cách điện để ta cầm an toàn. Kim loại dẫn điện; nhựa, gỗ khô, cao su thì cách điện.", "nv": "Tuấn Kiệt"}, {"loi": "Mình lắp mạch thật và thử các vật liệu để khôi phục sơ đồ nhé!", "nv": "Minh Anh"}, {"loi": "Muốn biết một vật dẫn điện hay cách điện, cứ lắp vật đó vào mạch thử: đèn sáng thì vật dẫn điện, đèn không sáng thì vật cách điện.", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Khay vật mẫu có thìa inox, đũa gỗ, dây đồng, thước nhựa. Lần lượt lắp từng vật vào mạch thử nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Bên bể thử mạch, hai kẹp kim loại chờ sẵn; các vật mẫu xếp thành hàng trên khay kính. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "9", "mucDo": [1], "soCau": 1}}], "nhan": "Nhúng các vật mẫu vào bể thử mạch"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Đèn pin là mạch điện thu nhỏ mang theo người. Mở nắp đèn pin ra xem bên trong có gì nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Chiếc đèn pin của Trạm được tháo nắp, lộ pin, bóng đèn nhỏ và lò xo kim loại bên trong. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "9", "mucDo": [1], "soCau": 1}}], "nhan": "Ngắm chiếc đèn pin của Trạm"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Sương kéo tới che mờ sơ đồ mạch rồi!", "nv": "Minh Anh"}, {"loi": "Có Hạt Đậu đây! Câu cứu viện của Robot Hạt Đậu sẽ làm sương tan ngay — trả lời đúng nhé!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "9", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa bàn lắp mạch là tấm sơ đồ mạch thắp sáng, các ký hiệu bộ phận đã bị sương che mờ. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "9", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi, bàn thử thách lớn mở ra: chọn đúng vật liệu để lắp vào mạch thử trước mặt cả Trạm. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "9", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Sơ đồ mạch sáng rõ rồi! Nguồn, dây dẫn, công tắc, bóng đèn — mạch kín là đèn sáng, mạch hở là đèn tắt!", "nv": "Tuấn Kiệt"}, {"loi": "Hạt Đậu trao biệt đội Bộ Mạch Điện Đầu Tay. Nhìn kìa — sương đang tụ thành khiên dày trước Cổng Trạm Điện ở cuối Đài!", "nv": "Robot Hạt Đậu"}, {"loi": "Cổng thứ ba của năm đang chờ. Cả lớp ơi, tập đặc biệt — cùng phá Cổng Trạm Điện nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t3", "ten": "Tập 3 — Mạch điện thắp sáng", "tomTatTapTruoc": "Tập trước: Biệt đội khôi phục bảng quy tắc an toàn điện và nhận Tấm Biển Vàng An Toàn Điện. Cuối tập, Hạt Đậu rủ cả đội tự tay lắp một mạch điện thắp sáng hoàn chỉnh...", "tuan": "9", "vatPham": "Bộ Mạch Điện Đầu Tay"}, {"bai": "7+8+9", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Mấy nhà khoa học nhí mà đòi mở Cổng Trạm Điện của ta sao? Hiện tượng ở đây đã bị ta làm mờ hết rồi!", "nv": "Sương Mù"}, {"loi": "Đừng sợ! Đây là Máy Quang Hợp — cỗ máy trung tâm của Trạm. Trả lời đúng, từng bánh răng của máy sẽ sáng lên; đủ bốn bánh răng sáng, khiên sương trước Cổng Trạm Điện sẽ vỡ tan!", "nv": "Robot Hạt Đậu"}, {"loi": "Biệt đội Ánh Sao sẵn sàng! Cả lớp bình tĩnh quan sát, suy luận rồi chọn đáp án đúng nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Bánh răng thứ nhất của Máy Quang Hợp chờ khởi động: hãy nhớ lại vai trò và các nguồn năng lượng quanh ta. Chọn đáp án đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "7", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Khiên sương rung lên! Bánh răng thứ hai cần kiến thức dùng điện an toàn và tiết kiệm. Cả lớp chọn đáp án đúng nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "8", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù dồn sức vào màn mạch điện thắp sáng. Chọn đáp án đúng để bánh răng thứ ba sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "9", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối cùng! Máy Quang Hợp cần một câu hỏi khó về an toàn điện trong đời sống. Chọn đáp án đúng để phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "8", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Bốn bánh răng sáng bừng! Cổng Trạm Điện mở rồi! Đài Năng Lượng của Trạm sáng đèn trở lại, Sổ Tay ghi trọn mạch điện và quy tắc an toàn.", "nv": "Robot Hạt Đậu"}, {"loi": "Nhận Chìa Cổng Trạm Điện nào. Phía trước, ngoài cánh đồng của Trạm, tuabin gió đang quay và tấm pin mặt trời đang đón nắng đấy!", "nv": "Minh Anh"}, {"loi": "Khà... điện sáng thì sao? Ra cánh đồng gió nắng, ta chờ sẵn rồi...", "nv": "Sương Mù"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Trạm Điện", "tomTatTapTruoc": "Biệt đội đã khôi phục bảng nguồn năng lượng, thuộc nằm lòng quy tắc an toàn điện và tự tay lắp mạch điện thắp sáng. Giờ đây, Sương Mù Quên Lãng dựng khiên sương trước Cổng Trạm Điện...", "tuan": "9", "vatPham": "Chìa Cổng Trạm Điện"}], "tenMua": "Mùa 3 — Trạm Điện Sáng Bừng", "tomTatMua": "Chủ đề Năng lượng mở ra ở Đài Năng Lượng của Trạm Khám Phá Xanh. Biệt đội khôi phục bảng nguồn năng lượng quanh ta — từ Mặt Trời, gió, nước chảy đến thức ăn nuôi cơ thể — rồi học thuộc quy tắc dùng điện an toàn và tiết kiệm, và tự tay lắp mạch điện thắp sáng với pin, dây dẫn, công tắc, bóng đèn — để tiến tới Cổng Trạm Điện. Sương Mù Quên Lãng lảng vảng quanh từng bóng đèn leo lét của Đài."}, {"anhBia": "canh-dong-gio-nang", "anhCanTao": [{"khoa": "canh-dong-gio-nang", "moTa": "Cánh đồng năng lượng xanh ngoài Trạm Khám Phá Xanh: tuabin gió trắng quay trên đồi cỏ, hàng tấm pin mặt trời nghiêng đón nắng, dòng suối nhỏ với guồng nước gỗ; Biệt đội Ánh Sao áo trắng khăn quàng đỏ chạy trên lối mòn, Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) giơ tay đón gió; nắng vàng rực, sương xám mỏng ở chân trời. Phong cách 3D Pixar, không chữ."}], "beCum": {"cacBai": ["7", "8", "9", "10", "11", "12"], "moTa": "Cơ chế BỂ CHỦ ĐỀ (Khoa học lớp 5): tập Ôn tập chủ đề Năng lượng (Bài 12) rút câu từ bể chung gồm toàn bộ câu trắc nghiệm có phương án của các bài 7–12 thuộc Chủ đề 2. Năng lượng, lọc theo mucDo đã khai trong rutCau, không lặp trong cùng một tập. Trường rutCau.bai là bài Ôn tập; trường rutCau.be là danh sách bài của chủ đề."}, "cacBai": ["10", "11", "12"], "cacChuDe": ["2"], "id": "kh5-c4", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; dẫn đường cho Biệt đội Ánh Sao trong thế giới Khoa học và là người đưa ra câu cứu viện mang tên mình.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa, hay ghi chép sổ tay.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận nguyên nhân – kết quả trước khi hành động."}, "tap": [{"bai": "10", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Sau Đài Năng Lượng là khu kho chất đốt của Trạm: than đá, củi khô, bình khí đốt xếp ngay ngắn. Cạnh vườn là hầm khí sinh học ủ phân và rác hữu cơ, nối ống dẫn lên bếp của Trạm.", "nv": "Người kể"}, {"loi": "Số liệu chủ đề ghi rõ: chất đốt có sẵn trong tự nhiên gồm than, dầu mỏ, khí tự nhiên và củi; con người còn tạo ra khí sinh học từ chất thải ủ kín. Chất đốt cho ta nhiệt đun nấu, chạy máy móc và phát điện!", "nv": "Robot Hạt Đậu"}, {"loi": "Nhưng chất đốt cháy là sinh khói và khí thải; than, dầu mỏ lại có hạn. Dùng chất đốt phải an toàn, phòng cháy nổ và tiết kiệm.", "nv": "Đức Trí"}, {"loi": "Hôm nay mình khảo sát kho chất đốt và hầm khí sinh học, ghi vào Sổ Tay cách dùng chất đốt an toàn nhé!", "nv": "Minh Anh"}, {"loi": "Nhớ nhé: đun bếp than trong nhà kín gió vừa ô nhiễm vừa nguy hiểm — phải để nơi thoáng và không rời mắt khỏi bếp đang cháy!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Khay kính bày mẫu than đá đen bóng, than củi nhẹ xốp và khúc củi khô. Soi kỹ từng mẫu nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Trong khay kính, các mẫu chất đốt xếp thành hàng: than đá, than củi và củi khô. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "10", "mucDo": [1], "soCau": 1}}], "nhan": "Soi các mẫu than, củi trong khay kính"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Hầm ủ sau vườn đang sủi bọt khí. Khí từ hầm theo ống dẫn lên bếp Trạm để đun nước đấy!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Nắp hầm khí sinh học hé mở, bọt khí nổi lên trong lớp chất ủ; ống dẫn chạy thẳng về phía bếp. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "10", "mucDo": [1], "soCau": 1}}], "nhan": "Xem hầm khí sinh học ở vườn sau"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ối, sương tràn xuống, bảng quy tắc phòng cháy mờ hết chữ rồi!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng là sương tan, chữ hiện rõ ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "10", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa khu kho là bảng quy tắc phòng chống cháy, nổ khi dùng chất đốt, vài dòng đã mờ vì sương. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "10", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi khảo sát, Hạt Đậu mở trang khuyên nhủ gia đình: đun nấu sao cho vừa an toàn, vừa tiết kiệm, vừa ít khói bụi. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "10", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bảng quy tắc sáng rõ rồi! Chất đốt quý và có hạn — dùng đúng, dùng đủ, an toàn là trên hết!", "nv": "Thảo Nguyên"}, {"loi": "Hạt Đậu trao biệt đội Ngọn Lửa An Toàn. Nhìn ra cánh đồng kìa — tuabin gió đang quay tít, hàng pin mặt trời nghiêng mình đón nắng!", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình ra cánh đồng, tìm hiểu năng lượng sạch từ nắng, gió và nước nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Ngọn lửa từ chất đốt", "tomTatTapTruoc": "Mùa trước: Biệt đội phá Cổng Trạm Điện, Đài Năng Lượng sáng đèn trở lại. Ngoài cánh đồng của Trạm, kho chất đốt và hầm khí sinh học đang chờ khám phá...", "tuan": "10", "vatPham": "Ngọn Lửa An Toàn"}, {"bai": "11", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Cánh đồng năng lượng xanh ngoài Trạm rực nắng: tuabin gió trắng quay đều trên đồi cỏ, hàng tấm pin mặt trời nghiêng đón nắng, dòng suối nhỏ quay guồng nước gỗ kêu cọt kẹt.", "nv": "Người kể"}, {"loi": "Đây là ba nguồn năng lượng sạch của tương lai: pin mặt trời biến nắng thành điện; gió quay tuabin phát điện và đẩy thuyền buồm; nước chảy quay guồng và làm thủy điện!", "nv": "Robot Hạt Đậu"}, {"loi": "Điểm quý nhất: nắng, gió và nước chảy không bao giờ cạn, lại không thải khói bụi như chất đốt. Đun nước ngày nắng bằng năng lượng mặt trời vừa an toàn vừa tiết kiệm.", "nv": "Đức Trí"}, {"loi": "Mình ghi chép cách Trạm khai thác ba nguồn năng lượng này vào Sổ Tay nhé!", "nv": "Minh Anh"}, {"loi": "Thuyền buồm và nhà máy điện gió tuy khác nhau mà giống nhau: cùng nhờ sức gió đấy!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "cau-suong", "dong": [{"loi": "Tuabin gió trên đồi quay vù vù. Đứng dưới chân cột, nghe tiếng gió rít qua cánh quạt nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Cột tuabin gió trắng cao vút trên đồi cỏ, ba cánh quạt quay đều trong gió. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "11", "mucDo": [1], "soCau": 1}}], "nhan": "Đứng dưới tuabin gió trên đồi"}, {"canh": [{"anh": "canh-chu", "dong": [{"loi": "Tấm pin mặt trời này gồm nhiều ô nhỏ ghép lại. Soi kỹ xem nắng biến thành điện thế nào nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Dưới kính lúp, bề mặt tấm pin mặt trời hiện rõ từng ô vuông xanh thẫm xếp khít nhau. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "11", "mucDo": [1], "soCau": 1}}], "nhan": "Soi tấm pin mặt trời dưới kính lúp"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ơ, sương phủ xuống, bảng so sánh năng lượng sạch mờ đi rồi!", "nv": "Thảo Nguyên"}, {"loi": "Bình tĩnh nào! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng, chữ trên bảng sẽ hiện rõ lại ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "11", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa cánh đồng là trạm ghi chép của Trạm, bảng so sánh các nguồn năng lượng sạch đã bị sương làm mờ. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "11", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi, bên dòng suối nhỏ, guồng nước gỗ quay đều đưa nước lên máng tưới cho vườn của Trạm. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "11", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bảng so sánh sáng rõ rồi! Nắng, gió, nước chảy — ba nguồn sạch, bền, không khói bụi cho tương lai!", "nv": "Đức Trí"}, {"loi": "Hạt Đậu trao biệt đội Chiếc Tuabin Gió Mini. Chủ đề Năng lượng sắp khép lại — tấm Sơ đồ Chủ đề trên tường Đài đang chờ buổi tổng ôn đấy!", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình về Đài Năng Lượng, làm trạm tổng ôn Chủ đề Năng lượng nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Nắng, gió và nước chảy", "tomTatTapTruoc": "Tập trước: Biệt đội khảo sát kho chất đốt và hầm khí sinh học, nhận Ngọn Lửa An Toàn. Cuối tập, tuabin gió quay tít trên đồi và hàng pin mặt trời nghiêng mình đón nắng ngoài cánh đồng...", "tuan": "11–12", "vatPham": "Chiếc Tuabin Gió Mini"}, {"bai": "12", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Biệt đội quay lại Đài Năng Lượng. Tấm Sơ đồ Chủ đề Năng lượng khổ lớn trên tường bị sương làm mờ các ô: nguồn năng lượng, an toàn điện, mạch điện, chất đốt và năng lượng sạch.", "nv": "Người kể"}, {"loi": "Buổi tổng ôn hôm nay rút câu từ BỂ CHỦ ĐỀ — toàn bộ kiến thức Chủ đề Năng lượng gộp lại. Ôn đều cả năm bài: vai trò của năng lượng, dùng điện, mạch điện, chất đốt, nắng – gió – nước nhé!", "nv": "Robot Hạt Đậu"}, {"loi": "Tổng ôn là dịp nối các mảng lại: nguồn nào sạch, nguồn nào có hạn; dùng điện thế nào cho an toàn; mạch kín thì đèn sáng.", "nv": "Đức Trí"}, {"loi": "Khôi phục đủ các ô sơ đồ là Chủ đề Năng lượng khép lại trọn vẹn. Bắt đầu nào!", "nv": "Minh Anh"}, {"loi": "Mình ôn theo vòng quanh Đài: từ bảng nguồn năng lượng đến bàn lắp mạch, không sót mảng nào!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Góc sơ đồ về các nguồn năng lượng đây: Mặt Trời, gió, nước chảy, chất đốt và điện. Ôn lại từ đầu nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Ô sơ đồ về nguồn năng lượng hiện mờ hình chong chóng, bếp than và tấm pin mặt trời. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "12", "be": ["7", "8", "9", "10", "11", "12"], "mucDo": [1], "soCau": 1}}], "nhan": "Ôn lại nguồn năng lượng quanh ta"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Góc sơ đồ về mạch điện và quy tắc an toàn đây. Nhớ mạch kín – mạch hở và quy tắc cầm phích cắm nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Ô sơ đồ về mạch điện hiện mờ hình viên pin, công tắc và bóng đèn nối thành vòng. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "12", "be": ["7", "8", "9", "10", "11", "12"], "mucDo": [1], "soCau": 1}}], "nhan": "Ôn lại mạch điện và an toàn điện"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Sương dồn xuống ô trung tâm của sơ đồ rồi!", "nv": "Minh Anh"}, {"loi": "Có Hạt Đậu đây! Câu cứu viện của Robot Hạt Đậu sẽ làm sương tan ngay — trả lời đúng nhé!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "12", "be": ["7", "8", "9", "10", "11", "12"], "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa tấm sơ đồ là ô trung tâm nối các mảng kiến thức của cả chủ đề, sương phủ dày nhất ở ô này. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "12", "be": ["7", "8", "9", "10", "11", "12"], "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi tổng ôn, chỉ còn ô vận dụng đời sống của sơ đồ: chọn nguồn năng lượng và cách dùng điện đúng cho tình huống thật. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "12", "be": ["7", "8", "9", "10", "11", "12"], "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Tấm Sơ đồ Chủ đề Năng lượng sáng đủ mọi ô rồi! Năng lượng quanh ta, dùng sao cho an toàn và tiết kiệm — nhớ trọn trong một tấm sơ đồ!", "nv": "Đức Trí"}, {"loi": "Hạt Đậu trao biệt đội Tấm Sơ Đồ Chủ Đề Năng Lượng. Nhìn kìa — sương đang tụ thành khiên dày trước Cổng Cánh Đồng Gió Nắng ở rìa cánh đồng!", "nv": "Robot Hạt Đậu"}, {"loi": "Cổng thứ tư của năm đang chờ. Cả lớp ơi, tập đặc biệt — cùng phá Cổng Cánh Đồng Gió Nắng nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t3", "ten": "Tập 3 — Trạm tổng ôn: Sơ đồ Chủ đề Năng lượng", "tomTatTapTruoc": "Tập trước: Biệt đội khám phá nắng, gió và nước chảy trên cánh đồng năng lượng xanh, nhận Chiếc Tuabin Gió Mini. Chủ đề Năng lượng sắp khép lại, tấm Sơ đồ Chủ đề trên tường Đài Năng Lượng chờ được tổng ôn...", "tuan": "12", "vatPham": "Tấm Sơ Đồ Chủ Đề Năng Lượng"}, {"bai": "10+11+12", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Mấy nhà khoa học nhí mà đòi mở Cổng Cánh Đồng Gió Nắng của ta sao? Hiện tượng ở đây đã bị ta làm mờ hết rồi!", "nv": "Sương Mù"}, {"loi": "Đừng sợ! Đây là Máy Quang Hợp — cỗ máy trung tâm của Trạm. Trả lời đúng, từng bánh răng của máy sẽ sáng lên; đủ bốn bánh răng sáng, khiên sương trước Cổng Cánh Đồng Gió Nắng sẽ vỡ tan!", "nv": "Robot Hạt Đậu"}, {"loi": "Biệt đội Ánh Sao sẵn sàng! Cả lớp bình tĩnh quan sát, suy luận rồi chọn đáp án đúng nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Bánh răng thứ nhất của Máy Quang Hợp chờ khởi động: hãy nhớ lại năng lượng chất đốt và cách dùng an toàn. Chọn đáp án đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "10", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Khiên sương rung lên! Bánh răng thứ hai cần kiến thức năng lượng mặt trời, gió và nước chảy. Cả lớp chọn đáp án đúng nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "11", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù dồn sức vào màn tổng ôn cả Chủ đề Năng lượng. Chọn đáp án đúng để bánh răng thứ ba sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "12", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối cùng! Máy Quang Hợp cần một câu hỏi khó về khai thác năng lượng sạch. Chọn đáp án đúng để phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "11", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Bốn bánh răng sáng bừng! Cổng Cánh Đồng Gió Nắng mở rồi! Chủ đề Năng lượng khép lại trong Sổ Tay — từ ngọn lửa chất đốt đến cánh đồng năng lượng sạch.", "nv": "Robot Hạt Đậu"}, {"loi": "Nhận Chìa Cổng Cánh Đồng Gió Nắng nào. Phía trước là Vườn Ươm của Trạm — hoa đang nở rộ và hạt đang nứt vỏ đấy!", "nv": "Minh Anh"}, {"loi": "Khà... năng lượng xong thì sao? Vườn ươm kia, sương của ta đã chờ từ lâu...", "nv": "Sương Mù"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Cánh Đồng Gió Nắng", "tomTatTapTruoc": "Biệt đội đã nắm vững năng lượng chất đốt, khám phá nắng, gió, nước chảy và tổng ôn trọn Chủ đề Năng lượng qua tấm sơ đồ. Giờ đây, Sương Mù Quên Lãng dựng khiên sương trước Cổng Cánh Đồng Gió Nắng...", "tuan": "12", "vatPham": "Chìa Cổng Cánh Đồng Gió Nắng"}], "tenMua": "Mùa 4 — Cánh Đồng Gió Nắng", "tomTatMua": "Chủ đề Năng lượng đi vào chặng cuối ngoài cánh đồng của Trạm Khám Phá Xanh. Biệt đội khảo sát kho chất đốt và hầm khí sinh học, học cách phòng chống cháy nổ và tiết kiệm nhiên liệu có hạn; rồi bước ra cánh đồng năng lượng sạch với tuabin gió, pin mặt trời và guồng nước; cuối cùng trở về Đài tổng ôn cả chủ đề qua tấm Sơ đồ Chủ đề Năng lượng — để tiến tới Cổng Cánh Đồng Gió Nắng. Sương Mù Quên Lãng vẫn lẩn khuất ở chân trời, chờ gió đổi chiều."}, {"anhBia": "vuon-uom-hoa-trai", "anhCanTao": [{"khoa": "vuon-uom-hoa-trai", "moTa": "Vườn ươm hoa trái trong Trạm Khám Phá Xanh: luống cây con xanh mướt, chậu hoa nở rực, cây ăn trái nhỏ trĩu quả trong nhà kính sáng; Biệt đội Ánh Sao áo trắng khăn quàng đỏ tưới cây và nâng chậu ươm, Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) ôm bình tưới nhỏ; sương xám mỏng sau hàng rào kính. Phong cách 3D Pixar, không chữ."}], "cacBai": ["13", "14"], "cacChuDe": ["3"], "id": "kh5-c5", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; dẫn đường cho Biệt đội Ánh Sao trong thế giới Khoa học và là người đưa ra câu cứu viện mang tên mình.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa, hay ghi chép sổ tay.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận nguyên nhân – kết quả trước khi hành động."}, "tap": [{"bai": "13", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Vườn Ươm của Trạm Khám Phá Xanh thơm ngát hương hoa: luống hoa bưởi trắng, giàn bí ngô vàng rực, ong bướm bay lượn không ngớt. Nhưng sổ ghi chép về sự sinh sản của hoa đã bị sương làm nhòe.", "nv": "Người kể"}, {"loi": "Nhớ kiến thức cốt lõi nhé: hoa là cơ quan sinh sản của thực vật có hoa. Nhị hoa gồm bao phấn và chỉ nhị, tạo phấn hoa; nhuỵ hoa gồm đầu nhuỵ, vòi nhuỵ và bầu nhuỵ!", "nv": "Robot Hạt Đậu"}, {"loi": "Hoa có cả nhị và nhuỵ là hoa lưỡng tính, như hoa bưởi; hoa chỉ có nhị hoặc chỉ có nhuỵ là hoa đơn tính, như hoa bí ngô đấy.", "nv": "Thảo Nguyên"}, {"loi": "Mình theo dõi ong bướm thụ phấn và khôi phục sổ ghi chép của Vườn nhé!", "nv": "Minh Anh"}, {"loi": "Chuỗi sự kiện phải thuộc nằm lòng: thụ phấn rồi thụ tinh, sau đó mới tạo hạt và quả. Hoa không được thụ phấn, thụ tinh thì không tạo hạt, quả được.", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Bông hoa mẫu đã tách cánh sẵn trên khay. Đưa lên kính hiển vi, tìm nhị và nhuỵ nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Dưới kính hiển vi, bông hoa hiện rõ: những nhị mảnh vươn cao quanh nhuỵ ở giữa bông. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "13", "mucDo": [1], "soCau": 1}}], "nhan": "Soi nhị và nhuỵ dưới kính hiển vi"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Giàn bí ngô có hai loại hoa khác nhau trên cùng một cây. Ngắm kỹ và phân biệt nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Trên giàn bí ngô, bông hoa vàng to chỉ có nhị nằm cạnh bông hoa có bầu nhỏ phình ở cuống. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "13", "mucDo": [1], "soCau": 1}}], "nhan": "Ngắm hoa bí ngô trong luống vườn"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ối, sương tràn xuống, bảng ghi quá trình thụ phấn mờ hết chữ rồi!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng là sương tan, chữ hiện rõ ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "13", "mucDo": [1], "soCau": 1}}, "danChuyen": "Bên luống hoa, đàn ong đang chuyển phấn từ bông này sang bông khác; bảng ghi quá trình thụ phấn của Trạm bị sương che mờ. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "13", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi, Hạt Đậu mở trang bí mật của hoa: vì sao nhiều hoa có màu sắc sặc sỡ, mật ngọt và mùi hương thơm? Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "13", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Sổ ghi chép sáng rõ rồi! Nhị tạo phấn, nhuỵ nhận phấn — thụ phấn, thụ tinh rồi kết hạt, thành quả!", "nv": "Thảo Nguyên"}, {"loi": "Hạt Đậu trao biệt đội Chiếc Kính Soi Hoa. Nhìn xuống luống ươm kìa — những hạt đậu vừa gieo tuần trước đang nứt vỏ, nhú mầm xanh!", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình theo dõi cây con lớn lên từ hạt nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Hoa và bí mật sinh sản", "tomTatTapTruoc": "Mùa trước: Biệt đội phá Cổng Cánh Đồng Gió Nắng, khép trọn Chủ đề Năng lượng. Phía trước là Vườn Ươm của Trạm — hoa nở rộ khắp luống, ong bướm bay lượn, mà bảng ghi chép về hoa đang bị sương làm mờ...", "tuan": "13", "vatPham": "Chiếc Kính Soi Hoa"}, {"bai": "14", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Luống ươm của Vườn xanh mơn mởn: hạt đậu nứt vỏ nhú rễ mầm, rau muống giâm cành đã bén rễ, chậu sống đời nảy cây con từ mép lá. Bảng ghi các giai đoạn phát triển của cây con bị sương làm mờ.", "nv": "Người kể"}, {"loi": "Giải phẫu hạt nhé: hạt gồm vỏ hạt, phôi và chất dinh dưỡng dự trữ. Gặp điều kiện thuận lợi — đủ nước, không khí và nhiệt độ thích hợp — hạt sẽ nảy mầm, phôi lớn thành cây con!", "nv": "Robot Hạt Đậu"}, {"loi": "Lúc mới nảy mầm, cây con sống nhờ chất dinh dưỡng dự trữ trong hạt; đến khi có lá xanh, cây mới tự tạo được chất dinh dưỡng nhờ ánh sáng.", "nv": "Đức Trí"}, {"loi": "Mình ghi chép sự lớn lên của cây con vào Sổ Tay, cả cách trồng cây không cần hạt nữa nhé!", "nv": "Minh Anh"}, {"loi": "Đúng rồi: cây con còn mọc từ thân như rau muống, sắn; từ lá như cây sống đời, lưỡi hổ; từ rễ của một số cây nữa đấy!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "cau-suong", "dong": [{"loi": "Chậu hạt đậu mới gieo cần nắng ấm và đất ẩm. Đặt chậu bên khung cửa sáng nhất của Vườn nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Chậu ươm hạt đậu được đặt ngay khung cửa ngập nắng, đất trong chậu ẩm đều. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "14", "mucDo": [1], "soCau": 1}}], "nhan": "Đặt chậu ươm bên cửa sổ đón nắng"}, {"canh": [{"anh": "canh-chu", "dong": [{"loi": "Hạt đậu ngâm nước qua đêm đã trương và nứt vỏ. Đưa lên kính soi xem mầm nhú thế nào nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Dưới kính soi, hạt đậu nứt vỏ để lộ mầm trắng nhỏ và rễ mầm đang vươn ra. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "14", "mucDo": [1], "soCau": 1}}], "nhan": "Soi hạt đậu vừa nứt vỏ dưới kính"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ơ, sương phủ xuống, bảng giai đoạn phát triển của cây con mờ đi rồi!", "nv": "Thảo Nguyên"}, {"loi": "Bình tĩnh nào! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng, chữ trên bảng sẽ hiện rõ lại ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "14", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa Vườn là bảng ghi các giai đoạn phát triển của cây con, thứ tự các giai đoạn đã bị sương làm mờ. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "14", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi, gian trưng bày các cách trồng cây của Trạm mở ra: hạt, thân, lá, rễ — cách nào cho cây nào? Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "14", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bảng giai đoạn sáng rõ rồi! Vỏ hạt, phôi, chất dinh dưỡng dự trữ — đủ nước, không khí và nhiệt độ là mầm xanh bật dậy!", "nv": "Đức Trí"}, {"loi": "Hạt Đậu trao biệt đội Chậu Cây Con Đầu Tiên. Nhìn kìa — sương đang tụ thành khiên trước Cổng Luống Hoa ở cuối vườn!", "nv": "Robot Hạt Đậu"}, {"loi": "Cổng của Vườn Ươm đang chờ. Cả lớp ơi, tập đặc biệt — cùng phá Cổng Luống Hoa nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Cây con lớn lên từ đâu?", "tomTatTapTruoc": "Tập trước: Biệt đội khám phá bí mật sinh sản của hoa, nhận Chiếc Kính Soi Hoa. Cuối tập, những hạt đậu trong luống ươm đang nứt vỏ, nhú mầm xanh non...", "tuan": "14–15", "vatPham": "Chậu Cây Con Đầu Tiên"}, {"bai": "13+14", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Mấy nhà khoa học nhí mà đòi mở Cổng Luống Hoa của ta sao? Hiện tượng ở đây đã bị ta làm mờ hết rồi!", "nv": "Sương Mù"}, {"loi": "Đừng sợ! Đây là Máy Quang Hợp — cỗ máy trung tâm của Trạm. Trả lời đúng, từng bánh răng của máy sẽ sáng lên; đủ bốn bánh răng sáng, khiên sương trước Cổng Luống Hoa sẽ vỡ tan!", "nv": "Robot Hạt Đậu"}, {"loi": "Biệt đội Ánh Sao sẵn sàng! Cả lớp bình tĩnh quan sát, suy luận rồi chọn đáp án đúng nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Bánh răng thứ nhất của Máy Quang Hợp chờ khởi động: hãy nhớ lại cơ quan sinh sản của thực vật có hoa. Chọn đáp án đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "13", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Khiên sương rung lên! Bánh răng thứ hai cần kiến thức sự phát triển của cây con. Cả lớp chọn đáp án đúng nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "14", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù dồn sức vào màn thụ phấn, thụ tinh và tạo hạt, quả. Chọn đáp án đúng để bánh răng thứ ba sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "13", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối cùng! Máy Quang Hợp cần một câu hỏi khó về cách trồng cây con từ các bộ phận của cây mẹ. Chọn đáp án đúng để phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "14", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Bốn bánh răng sáng bừng! Cổng Luống Hoa mở rồi! Vườn Ươm thơm hương hoa, luống cây con xanh đều tăm tắp.", "nv": "Robot Hạt Đậu"}, {"loi": "Nhận Chìa Cổng Luống Hoa nào. Phía trước là Thung Lũng Vòng Đời bên Bể quan sát — tiếng ếch kêu và cánh bướm đang chờ đấy!", "nv": "Minh Anh"}, {"loi": "Khà... hoa trái xong thì sao? Vòng đời muôn loài, ta đã phủ sương từ lâu rồi...", "nv": "Sương Mù"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Luống Hoa", "tomTatTapTruoc": "Biệt đội đã khám phá bí mật sinh sản của hoa và theo dõi cây con lớn lên từ hạt, từ thân, từ lá. Giờ đây, Sương Mù Quên Lãng dựng khiên sương trước Cổng Luống Hoa...", "tuan": "14–15", "vatPham": "Chìa Cổng Luống Hoa"}], "tenMua": "Mùa 5 — Vườn Ươm Hoa Trái", "tomTatMua": "Chủ đề Thực vật và động vật mở ra trong Vườn Ươm thơm ngát của Trạm Khám Phá Xanh. Biệt đội soi nhị và nhuỵ dưới kính hiển vi, phân biệt hoa lưỡng tính và hoa đơn tính, theo chân ong bướm thụ phấn để hiểu chuỗi thụ phấn – thụ tinh – tạo hạt và quả; rồi gieo hạt, giâm cành, ghi chép cây con lớn lên từng ngày — để tiến tới Cổng Luống Hoa. Sương Mù Quên Lãng lẩn sau hàng rào kính, chờ làm mờ từng trang ghi chép."}, {"anhBia": "thung-lung-vong-doi", "anhCanTao": [{"khoa": "thung-lung-vong-doi", "moTa": "Thung lũng vòng đời bên Bể quan sát của Trạm Khám Phá Xanh: tổ chim trên cành với chim non, bướm sặc sỡ bay cạnh nhộng treo, ếch xanh bên bờ ao sen, cây lớn tỏa bóng; Biệt đội Ánh Sao áo trắng khăn quàng đỏ ghi chép quan sát, Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) cầm ống nhòm; sương xám mỏng trên mặt ao. Phong cách 3D Pixar, không chữ."}], "beCum": {"cacBai": ["13", "14", "15", "16", "17"], "moTa": "Cơ chế BỂ CHỦ ĐỀ (Khoa học lớp 5): tập Ôn tập chủ đề Thực vật và động vật (Bài 17) rút câu từ bể chung gồm toàn bộ câu trắc nghiệm có phương án của các bài 13–17 thuộc Chủ đề 3. Thực vật và động vật, lọc theo mucDo đã khai trong rutCau, không lặp trong cùng một tập. Trường rutCau.bai là bài Ôn tập; trường rutCau.be là danh sách bài của chủ đề."}, "cacBai": ["15", "16", "17"], "cacChuDe": ["3"], "id": "kh5-c6", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; dẫn đường cho Biệt đội Ánh Sao trong thế giới Khoa học và là người đưa ra câu cứu viện mang tên mình.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa, hay ghi chép sổ tay.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận nguyên nhân – kết quả trước khi hành động."}, "tap": [{"bai": "15", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Thung Lũng Vòng Đời nằm bên Bể quan sát lớn của Trạm: vịt mẹ ấp trứng bên bờ ao, bò mẹ cho nghé bú trong chuồng nhỏ, đàn cá thả trứng trong bể kính. Bảng phân loại sinh sản của động vật bị sương làm nhòe.", "nv": "Người kể"}, {"loi": "Hai hình thức sinh sản phải phân biệt rõ: động vật đẻ trứng như gà, vịt, chim, cá, ếch; động vật đẻ con như bò, chó, dê, ngựa. Trứng và tinh trùng kết hợp tạo thành hợp tử, hợp tử phát triển thành phôi!", "nv": "Robot Hạt Đậu"}, {"loi": "Điểm thú vị: ở bò, thụ tinh xảy ra bên trong cơ thể mẹ; ở nhiều loài cá, cá cái đẻ trứng ra nước rồi cá đực tưới tinh trùng — thụ tinh ở bên ngoài.", "nv": "Đức Trí"}, {"loi": "Mình quan sát khắp thung lũng và khôi phục bảng phân loại nhé!", "nv": "Minh Anh"}, {"loi": "Nhớ dấu hiệu nhanh: có vú nuôi con bằng sữa là đẻ con; còn lại phần lớn đẻ trứng — như muỗi, chim bồ câu đều đẻ trứng đấy!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Ổ trứng chim trên cành cây thấp có ba quả trứng đốm. Soi kỹ vỏ trứng và đoán xem con non sắp nở chưa nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Dưới kính lúp, ba quả trứng chim đốm nâu nằm gọn trong ổ rơm ấm áp. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "15", "mucDo": [1], "soCau": 1}}], "nhan": "Soi ổ trứng chim dưới kính lúp"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Vịt mẹ đang ấp ổ trứng bên góc vườn, thỉnh thoảng trở trứng cho đều nhiệt. Quan sát nhẹ nhàng thôi nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Vịt mẹ nằm yên ấp ổ trứng tròn, đầu gác lên lưng, mắt lim dim trong nắng sớm. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "15", "mucDo": [1], "soCau": 1}}], "nhan": "Ngắm vịt mẹ ấp trứng trong vườn"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ối, sương tràn xuống mặt bể, bảng ghi quá trình thụ tinh mờ hết rồi!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng là sương tan, chữ hiện rõ ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "15", "mucDo": [1], "soCau": 1}}, "danChuyen": "Bên Bể quan sát, đàn cá đang mùa sinh sản thả trứng trong làn nước; bảng ghi quá trình thụ tinh của Trạm bị sương che mờ. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "15", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi, gian phân loại lớn của thung lũng mở ra: mỗi loài một tấm thẻ, phải xếp đúng nhóm đẻ trứng hay đẻ con. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "15", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bảng phân loại sáng rõ rồi! Đẻ trứng hay đẻ con, hợp tử thành phôi — mình xếp loài nào cũng chuẩn!", "nv": "Thảo Nguyên"}, {"loi": "Hạt Đậu trao biệt đội Tấm Thẻ Vàng Sinh Sản. Nhìn vào lọ nước bên bể kìa — những con bọ gậy nhỏ xíu đang ngọ nguậy. Chúng sắp thành gì nhỉ?", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình khám phá vòng đời kỳ diệu của muỗi và bướm nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Đẻ trứng hay đẻ con?", "tomTatTapTruoc": "Mùa trước: Biệt đội phá Cổng Luống Hoa, Vườn Ươm thơm hương hoa trái. Bên kia vườn là Thung Lũng Vòng Đời với Bể quan sát lớn — nơi muôn loài động vật sinh sôi, mà bảng phân loại sinh sản đang bị sương làm mờ...", "tuan": "15–16", "vatPham": "Tấm Thẻ Vàng Sinh Sản"}, {"bai": "16", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Thung Lũng Vòng Đời vào mùa biến hình: bướm sặc sỡ bay trên luống hoa, ếch xanh ngồi bên ao sen, lọ nước của Trạm đầy bọ gậy. Tấm sơ đồ vòng đời treo trên vách bị sương làm mờ các mũi tên.", "nv": "Người kể"}, {"loi": "Vòng đời muỗi gồm bốn giai đoạn: trứng, ấu trùng (chính là bọ gậy, sống trong nước), nhộng, rồi muỗi trưởng thành. Bướm cũng bốn giai đoạn: trứng, sâu, nhộng, bướm trưởng thành!", "nv": "Robot Hạt Đậu"}, {"loi": "Điểm sâu sắc: ấu trùng muỗi sống trong nước, hình dạng khác hẳn muỗi trưởng thành — nên không thể nhìn ấu trùng mà đoán hết đặc điểm con trưởng thành được.", "nv": "Đức Trí"}, {"loi": "Mình khôi phục sơ đồ vòng đời, rồi tìm cách giúp Trạm hạn chế muỗi từ chính vòng đời của chúng nhé!", "nv": "Minh Anh"}, {"loi": "Đúng rồi: úp bát, đậy kín dụng cụ chứa nước, thả cá vào bể là cắt đứt nơi bọ gậy sinh sống đấy!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "cau-suong", "dong": [{"loi": "Đàn bướm sặc sỡ bay qua khung cửa của tháp quan sát. Đếm xem có bao nhiêu màu cánh nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Qua khung cửa trời, đàn bướm nhiều màu bay lượn trên nền trời xanh và luống hoa. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "16", "mucDo": [1], "soCau": 1}}], "nhan": "Ngắm bướm bay qua khung cửa trời"}, {"canh": [{"anh": "canh-chu", "dong": [{"loi": "Lọ nước mẫu của Trạm đây. Đưa bọ gậy lên kính soi, xem chúng ngọ nguậy và thở thế nào nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Dưới kính soi, những con bọ gậy nhỏ cong mình ngọ nguậy trong giọt nước. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "16", "mucDo": [1], "soCau": 1}}], "nhan": "Soi bọ gậy trong lọ nước dưới kính"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Ơ, sương phủ xuống, sơ đồ vòng đời mờ hết các giai đoạn rồi!", "nv": "Thảo Nguyên"}, {"loi": "Bình tĩnh nào! Câu cứu viện của Robot Hạt Đậu tới đây — trả lời đúng, chữ trên sơ đồ sẽ hiện rõ lại ngay!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "16", "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa thung lũng là tấm sơ đồ vòng đời khổ lớn của Trạm, thứ tự các giai đoạn đã bị sương làm mờ. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "16", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi, bên bờ ao sen, chú ếch xanh ngồi im ngắm mặt nước — vòng đời của ếch cũng kỳ diệu không kém muỗi và bướm. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "16", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Sơ đồ vòng đời sáng rõ rồi! Trứng, ấu trùng, nhộng, trưởng thành — hiểu vòng đời là biết cách sống chung và phòng tránh đúng cách!", "nv": "Đức Trí"}, {"loi": "Hạt Đậu trao biệt đội Chiếc Vòng Đời Xoay. Chủ đề Thực vật và động vật sắp khép lại — tấm Sơ đồ Chủ đề trong Vườn Ươm đang chờ buổi tổng ôn cuối học kỳ đấy!", "nv": "Robot Hạt Đậu"}, {"loi": "Vậy tập sau mình về Vườn Ươm, làm trạm tổng ôn Chủ đề Thực vật và động vật nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Vòng đời kỳ diệu", "tomTatTapTruoc": "Tập trước: Biệt đội phân loại sinh sản của động vật, nhận Tấm Thẻ Vàng Sinh Sản. Cuối tập, trong lọ nước bên Bể quan sát, những con bọ gậy nhỏ xíu đang ngọ nguậy chờ biến hình...", "tuan": "16–17", "vatPham": "Chiếc Vòng Đời Xoay"}, {"bai": "17", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Biệt đội quay lại Vườn Ươm trong buổi chiều cuối học kỳ 1. Tấm Sơ đồ Chủ đề Thực Vật Và Động Vật khổ lớn bị sương làm mờ các ô: hoa và hạt, cây con, sinh sản và vòng đời của động vật.", "nv": "Người kể"}, {"loi": "Buổi tổng ôn cuối học kỳ rút câu từ BỂ CHỦ ĐỀ — toàn bộ kiến thức Chủ đề 3 gộp lại. Ôn đều cả bốn bài: sinh sản của hoa, cây con lớn lên, sinh sản và vòng đời của động vật nhé!", "nv": "Robot Hạt Đậu"}, {"loi": "Tổng ôn là dịp nối liền hai thế giới: thực vật sinh sản bằng hoa và hạt; động vật sinh sản bằng trứng và con — tất cả đều là vòng đời nối tiếp nhau.", "nv": "Đức Trí"}, {"loi": "Khôi phục đủ các ô sơ đồ là học kỳ 1 khép lại trọn vẹn. Bắt đầu tổng ôn nào!", "nv": "Minh Anh"}, {"loi": "Mình ôn theo vòng quanh Vườn: từ luống hoa đến thung lũng, không sót mảng nào!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Có hai việc chờ mình ở đây. Cả lớp chọn việc nào trước?", "nv": "Đức Trí"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Góc sơ đồ về hoa và hạt đây: nhị, nhuỵ, thụ phấn và cây con mọc từ hạt, thân, lá. Ôn lại từ đầu nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Ô sơ đồ về hoa và hạt hiện mờ hình bông hoa và hạt đậu vừa nứt vỏ. Bên Bể quan sát bằng kính trong suốt, các sinh vật và vật mẫu đang ở những vị trí khác nhau, mỗi vị trí kèm một thẻ đáp án. Cả lớp chọn vị trí đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "17", "be": ["13", "14", "15", "16", "17"], "mucDo": [1], "soCau": 1}}], "nhan": "Ôn lại hoa và hạt"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Góc sơ đồ về động vật đây: đẻ trứng, đẻ con và các vòng đời kỳ diệu. Nhớ bọ gậy và nhộng bướm nhé!", "nv": "Tuấn Kiệt"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Ô sơ đồ về động vật hiện mờ hình quả trứng, con bọ gậy và cánh bướm. Từ Cửa sổ bầu trời của Trạm nhìn ra, cảnh vật hiện rõ trong tầm mắt; mỗi khung cửa gắn một thẻ đáp án. Cả lớp chọn khung cửa đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "17", "be": ["13", "14", "15", "16", "17"], "mucDo": [1], "soCau": 1}}], "nhan": "Ôn lại vòng đời động vật"}]}, {"anh": "canh-kho", "bienCo": {"dong": [{"loi": "Sương dồn xuống ô trung tâm của sơ đồ rồi!", "nv": "Minh Anh"}, {"loi": "Có Hạt Đậu đây! Câu cứu viện của Robot Hạt Đậu sẽ làm sương tan ngay — trả lời đúng nhé!", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "17", "be": ["13", "14", "15", "16", "17"], "mucDo": [1], "soCau": 1}}, "danChuyen": "Giữa tấm sơ đồ là ô trung tâm nối các mảng kiến thức của cả chủ đề, sương phủ dày nhất ở ô này. Dưới Kính hiển vi của Trạm, các mẫu vật hiện ra phóng to rõ nét; những lam kính mẫu vật xếp thành hàng, mỗi lam kính kèm một thẻ đáp án. Cả lớp chọn lam kính đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "17", "be": ["13", "14", "15", "16", "17"], "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Cuối buổi tổng ôn, chỉ còn ô vận dụng đời sống của sơ đồ: dùng hiểu biết vòng đời để làm việc có ích quanh nhà. Trong Vườn thí nghiệm, các chậu cây và chai thí nghiệm xếp thành hàng ngay ngắn, mỗi chậu kèm một thẻ đáp án ghi điều kiện khác nhau. Cả lớp chọn chậu đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "17", "be": ["13", "14", "15", "16", "17"], "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Tấm Sơ đồ Chủ đề Thực Vật Và Động Vật sáng đủ mọi ô rồi! Hoa, hạt, trứng, vòng đời — cả chủ đề gói trong một tấm sơ đồ!", "nv": "Đức Trí"}, {"loi": "Hạt Đậu trao biệt đội Tấm Sơ Đồ Vòng Đời Xanh. Nhìn kìa — sương đang tụ thành khiên dày trước Cổng Vườn Ươm, cổng khép học kỳ 1 của chúng ta!", "nv": "Robot Hạt Đậu"}, {"loi": "Cổng cuối học kỳ đang chờ. Cả lớp ơi, tập đặc biệt — cùng phá Cổng Vườn Ươm nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t3", "ten": "Tập 3 — Trạm tổng ôn: Sơ đồ Chủ đề Thực Vật Và Động Vật", "tomTatTapTruoc": "Tập trước: Biệt đội khôi phục sơ đồ vòng đời của muỗi, bướm và ếch, nhận Chiếc Vòng Đời Xoay. Chủ đề Thực vật và động vật sắp khép lại — và học kỳ 1 cũng vậy — tấm Sơ đồ Chủ đề trong Vườn Ươm chờ buổi tổng ôn...", "tuan": "17", "vatPham": "Tấm Sơ Đồ Vòng Đời Xanh"}, {"bai": "15+16+17", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Mấy nhà khoa học nhí mà đòi mở Cổng Vườn Ươm của ta sao? Hiện tượng ở đây đã bị ta làm mờ hết rồi!", "nv": "Sương Mù"}, {"loi": "Đừng sợ! Đây là Máy Quang Hợp — cỗ máy trung tâm của Trạm. Trả lời đúng, từng bánh răng của máy sẽ sáng lên; đủ bốn bánh răng sáng, khiên sương trước Cổng Vườn Ươm sẽ vỡ tan!", "nv": "Robot Hạt Đậu"}, {"loi": "Biệt đội Ánh Sao sẵn sàng! Cả lớp bình tĩnh quan sát, suy luận rồi chọn đáp án đúng nhé!", "nv": "Minh Anh"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Bánh răng thứ nhất của Máy Quang Hợp chờ khởi động: hãy nhớ lại sự sinh sản của động vật. Chọn đáp án đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "15", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Khiên sương rung lên! Bánh răng thứ hai cần kiến thức vòng đời và sự phát triển của động vật. Cả lớp chọn đáp án đúng nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "16", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù dồn sức vào màn tổng ôn cả Chủ đề Thực vật và động vật. Chọn đáp án đúng để bánh răng thứ ba sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "17", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối cùng! Máy Quang Hợp cần một câu hỏi khó về vòng đời trong đời sống. Chọn đáp án đúng để phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "16", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Bốn bánh răng sáng bừng! Cổng Vườn Ươm mở rồi! HỌC KỲ 1 KHÉP LẠI: Vườn thí nghiệm của Trạm xanh trở lại, Sổ Tay Thí Nghiệm sáng chữ trọn nửa đầu năm — từ đất, chất, năng lượng đến hoa trái và vòng đời.", "nv": "Robot Hạt Đậu"}, {"loi": "Nhận Chìa Cổng Vườn Ươm nào. Học kỳ 2, Phòng Kính Hiển Vi đang chờ — nơi cả một thế giới vi khuẩn tí hon sẽ hiện ra dưới ống kính!", "nv": "Minh Anh"}, {"loi": "Khà... nửa cuốn sổ thì sao? Thế giới tí hon trong kính mới là nơi sương của ta dày nhất... hẹn học kỳ 2!", "nv": "Sương Mù"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Vườn Ươm", "tomTatTapTruoc": "Biệt đội đã phân loại sinh sản của động vật, khôi phục sơ đồ vòng đời và tổng ôn trọn Chủ đề Thực vật và động vật. Giờ đây, Sương Mù Quên Lãng dựng khiên sương trước Cổng Vườn Ươm — cổng khép học kỳ 1...", "tuan": "17", "vatPham": "Chìa Cổng Vườn Ươm"}], "tenMua": "Mùa 6 — Thung Lũng Vòng Đời", "tomTatMua": "Chủ đề Thực vật và động vật khép lại ở Thung Lũng Vòng Đời bên Bể quan sát của Trạm Khám Phá Xanh — và học kỳ 1 cũng khép lại tại đây. Biệt đội phân biệt động vật đẻ trứng và đẻ con, lần theo vòng đời kỳ diệu của muỗi, bướm và ếch, rồi tổng ôn cả chủ đề qua tấm Sơ đồ Vòng Đời Xanh — để phá Cổng Vườn Ươm, cổng cuối học kỳ 1. Sương Mù Quên Lãng rút về phía Phòng Kính Hiển Vi, hẹn một học kỳ mới đầy bí ẩn tí hon."}, {"anhBia": "the-gioi-ti-hon-trong-kinh", "anhCanTao": [{"khoa": "the-gioi-ti-hon-trong-kinh", "moTa": "Phòng kính hiển vi: chiếc kính hiển vi khổng lồ giữa phòng thí nghiệm trắng xanh, qua vòng sáng của kính hiện thế giới vi khuẩn tí hon nhiều màu hình que và hình cầu dễ thương; Biệt đội Ánh Sao áo trắng khăn quàng đỏ thay nhau nhìn vào kính, Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) điều chỉnh núm vặn; sương xám làm mờ một góc vòng sáng. Phong cách 3D Pixar, không chữ."}], "cacBai": ["18", "19"], "cacChuDe": ["4"], "id": "kh5-c7", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; là người dẫn đường của Biệt đội ở Trạm và đọc câu cứu viện trong thế giới Khoa học.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách của Thư viện Ánh Sao.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."}, "tap": [{"bai": "18", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Phòng Kính Hiển Vi là phòng đầu tiên của học kỳ 2. Sáng nay Sương Mù phủ mờ vòng sáng của chiếc kính hiển vi lớn và làm nhòe trang Sổ Tay ghi về vi khuẩn — những sinh vật bé nhỏ sống ở khắp nơi quanh ta.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc điều quan trọng nhất của bài này nè: vi khuẩn rất nhỏ, không thể nhìn thấy bằng mắt thường. Muốn quan sát chúng, người ta phải dùng kính hiển vi.", "nv": "Robot Hạt Đậu"}, {"loi": "Vi khuẩn sống ở khắp nơi: trong đất, trong nước, trên cơ thể sinh vật khác — và cả trên bàn tay mình nữa, dù nhìn tay có vẻ sạch.", "nv": "Thảo Nguyên"}, {"loi": "Vì không nhìn thấy nên càng phải suy luận cẩn thận: không thấy vi khuẩn trên tay không có nghĩa là tay sạch vi khuẩn. Rửa tay thường xuyên là việc cần làm.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, vào phòng kính, làm sáng lại vòng kính hiển vi thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Vòng sáng của kính mờ thành hai nửa: nửa mẫu đất và nửa mẫu nước. Cả lớp soi nửa nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-chu", "dong": [{"loi": "Nửa này là mẫu đất lấy từ vườn trường. Chọn mẫu vật ghi đúng điều về vi khuẩn trong đất nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi chiếu vào mẫu đất vườn trường, hiện những điều về vi khuẩn sống trong đất. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "18", "mucDo": [1], "soCau": 1}}], "nhan": "Soi nửa Kính hiển vi — vi khuẩn trong đất"}, {"canh": [{"anh": "canh-kho", "dong": [{"loi": "Nửa này là các chai nước và chậu mẫu trong vườn thí nghiệm. Chọn chậu gắn thẻ đúng điều về vi khuẩn trong nước nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày các chai nước mẫu lấy từ ao và vòi nước của Trạm, chờ cả lớp nhận đúng nơi vi khuẩn sinh sống. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "18", "mucDo": [1], "soCau": 1}}], "nhan": "Soi nửa Vườn thí nghiệm — vi khuẩn trong nước"}]}, {"anh": "cau-suong", "bienCo": {"dong": [{"loi": "Sương làm mờ kính bể rồi, mình không phân biệt được mẫu nào có vi khuẩn nữa!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là bể quan sát trong veo ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "18", "mucDo": [1], "soCau": 1}}, "danChuyen": "Bể quan sát hiện những mẫu nước và mẫu đất ngâm trong bể kính, chờ cả lớp kết luận đúng về nơi sống của vi khuẩn. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "18", "mucDo": [2], "soCau": 1}}, {"anh": "kho-sang", "danChuyen": "Cửa sổ bầu trời mở ra, hiện câu hỏi khó nhất của bài: vì sao không nhìn thấy vi khuẩn mà vẫn phải cẩn thận với chúng. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "18", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Vòng kính sáng rõ rồi, Sổ Tay đã ghi lại: vi khuẩn ở khắp nơi quanh ta! Hạt Đậu tặng biệt đội Chiếc Lam Kính Sáng nhé!", "nv": "Robot Hạt Đậu"}, {"loi": "Ngày mai mình gặp những vi khuẩn có ích: chúng giúp làm sữa chua và muối chua rau củ đấy.", "nv": "Thảo Nguyên"}, {"loi": "Tập sau mình vào bếp thí nghiệm của Trạm nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Vi Khuẩn Ở Khắp Nơi", "tomTatTapTruoc": "Học kỳ 1 khép lại ở Cổng Vườn Ươm: Vườn thí nghiệm xanh trở lại, Sổ Tay Thí Nghiệm nửa đầu năm đã sáng chữ. Sau những tuần nghỉ, Biệt đội trở lại Trạm và bước vào Phòng Kính Hiển Vi — nơi một thế giới tí hon đang bị sương làm mờ...", "tuan": "19", "vatPham": "Chiếc Lam Kính Sáng"}, {"bai": "19", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Bếp thí nghiệm của Trạm có những hũ sữa chua và vại dưa muối thơm ngon. Sáng nay Sương Mù làm nhòe tờ công thức lên men treo trên tường — chẳng ai nhớ vi khuẩn có ích làm việc thế nào nữa.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc nè: vi khuẩn lactic là bạn tốt trong bếp — chúng giúp làm sữa chua và muối chua rau, củ, quả. Nhờ chúng ăn đường trong sữa mà sữa chua có vị chua, ít ngọt.", "nv": "Robot Hạt Đậu"}, {"loi": "Không phải vi khuẩn nào cũng có hại đâu. Có loài gây bệnh, nhưng cũng có loài giúp con người chế biến thực phẩm ngon và để được lâu.", "nv": "Thảo Nguyên"}, {"loi": "Làm sữa chua phải đúng cách: cho men vào khi sữa còn đang sôi thì vi khuẩn có ích sẽ chết; làm xong thì cho vào tủ lạnh để sữa chua ngon lâu.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, vào bếp, khôi phục tờ công thức lên men thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-kho", "dong": [{"loi": "Tờ công thức mờ thành hai nửa: nửa làm sữa chua và nửa muối chua. Cả lớp khôi phục nửa nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Nửa này là những hũ sữa đang lên men trong vườn thí nghiệm. Chọn chậu gắn thẻ đúng về cách làm sữa chua nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày những hũ sữa và lọ men mẫu, chờ cả lớp chọn đúng điều kiện lên men của sữa chua. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "19", "mucDo": [1], "soCau": 1}}], "nhan": "Khôi phục nửa Vườn thí nghiệm — làm sữa chua"}, {"canh": [{"anh": "cau-suong", "dong": [{"loi": "Nửa này là các vại sung và rau đang muối chua ngâm trong bể kính. Chọn vị trí ghi đúng cách muối chua nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Bể quan sát hiện những vại sung và rau muối chua, chờ cả lớp nhận đúng vai trò của vi khuẩn lactic. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "19", "mucDo": [1], "soCau": 1}}], "nhan": "Khôi phục nửa Bể quan sát — muối chua rau củ"}]}, {"anh": "kho-sang", "bienCo": {"dong": [{"loi": "Sương làm mình quên mất vì sao sữa chua lại chua rồi!", "nv": "Thảo Nguyên"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là công thức rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "19", "mucDo": [1], "soCau": 1}}, "danChuyen": "Cửa sổ bầu trời hiện hình những hũ sữa chua và vại dưa muối khắp nơi, chờ cả lớp nói đúng vai trò của vi khuẩn có ích. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "19", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi soi vào hũ sữa chua mẫu, hiện thử thách khó: phân biệt lên men có ích với thức ăn ôi thiu. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "19", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Công thức lên men rõ ràng rồi! Hạt Đậu tặng biệt đội Hũ Sữa Chua Ánh Sao — chua dịu và thơm ngon nhé!", "nv": "Robot Hạt Đậu"}, {"loi": "Nhưng không phải vi khuẩn nào cũng là bạn. Ngày mai mình học về những vi khuẩn gây bệnh và cách phòng tránh.", "nv": "Đức Trí"}, {"loi": "Tập sau mình tới Cổng Gác Phòng Bệnh nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Những Người Bạn Lên Men", "tomTatTapTruoc": "Tập trước: Biệt đội làm sáng vòng kính hiển vi, ghi lại rằng vi khuẩn sống ở khắp nơi và nhận Chiếc Lam Kính Sáng. Hôm nay bếp thí nghiệm của Trạm thơm mùi sữa chua — mà sương đang làm nhòe công thức lên men...", "tuan": "20", "vatPham": "Hũ Sữa Chua Ánh Sao"}, {"bai": "18+19", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Thế giới tí hon là của ta. Không có vòng sáng kính hiển vi, các ngươi sẽ chẳng bao giờ phân biệt nổi vi khuẩn bạn hay thù...", "nv": "Sương Mù"}, {"loi": "Biệt đội sẵn sàng! Ánh sáng của kính hiển vi chính là những điều chúng mình đã quan sát đúng. Hạt Đậu ơi, nhắc luật cổng nào!", "nv": "Minh Anh"}, {"loi": "Luật cổng: bốn đòn luân phiên hai bài của mùa. Mỗi câu đúng là một bánh răng của cỗ máy trung tâm sáng lên, phá khiên sương trước cổng. Cố lên, các bạn ơi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Cỗ máy trung tâm của Trạm quay bánh răng đầu tiên: vi khuẩn xung quanh chúng ta — kích thước, nơi sống và cách quan sát. Cả lớp chọn chiêu thức đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "18", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Một bánh răng đã sáng! Đòn tiếp theo là những người bạn lên men: sữa chua và muối chua. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "19", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù dồn sương vào vòng kính hiển vi. Cả lớp chọn chiêu thức đúng về vi khuẩn ở khắp nơi nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "18", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối của mùa quay lại bếp thí nghiệm: phân biệt vi khuẩn có ích và thức ăn ôi thiu. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "19", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Thôi được... Cổng Kính Hiển Vi là của các ngươi. Ta rút vào phòng bên đây — nơi những vi khuẩn gây bệnh đang chờ, xem các ngươi gác cổng phòng bệnh thế nào...", "nv": "Sương Mù"}, {"loi": "Cổng mở rồi! Hạt Đậu trao biệt đội Huy Hiệu Người Gác Kính — Sổ Tay Thí Nghiệm đã ghi trọn hai trang đầu của học kỳ 2.", "nv": "Robot Hạt Đậu"}, {"loi": "Hai bài đầu của chủ đề Vi khuẩn đã sáng rõ: có loài là bạn, có loài gây bệnh — phải hiểu đúng mới phòng tránh đúng.", "nv": "Đức Trí"}, {"loi": "Mùa sau mình sang Cổng Gác Phòng Bệnh — học cách bảo vệ cơ thể khỏi vi khuẩn gây bệnh nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Kính Hiển Vi", "tomTatTapTruoc": "Biệt đội đã khôi phục hai trang Sổ Tay của Phòng Kính Hiển Vi: vi khuẩn ở khắp nơi và những vi khuẩn có ích trong bếp. Giờ đây, trước Cổng Kính Hiển Vi của mùa, Sương Mù Quên Lãng dồn sương làm mờ mọi vòng sáng của Trạm...", "tuan": "20", "vatPham": "Huy Hiệu Người Gác Kính"}], "tenMua": "Mùa 7 — Thế Giới Tí Hon Trong Kính", "tomTatMua": "Học kỳ 2 mở ra ở Phòng Kính Hiển Vi của Trạm Khám Phá Xanh. Biệt đội Ánh Sao — lứa nhà khoa học nhí kỳ cựu nhất của Trạm — soi vào thế giới tí hon của vi khuẩn: những sinh vật nhỏ đến mức mắt thường không thấy, sống ở khắp nơi, vừa có loài giúp người lên men thực phẩm vừa có loài gây bệnh. Sương Mù Quên Lãng làm mờ vòng sáng của kính hiển vi và nhòe Sổ Tay Thí Nghiệm — cả đội phải quan sát thật đúng để khôi phục từng trang ghi chép."}, {"anhBia": "cong-gac-phong-benh", "anhCanTao": [{"khoa": "cong-gac-phong-benh", "moTa": "Cổng gác phòng bệnh của Trạm Khám Phá Xanh: cổng vòm trắng sạch, trạm rửa tay với bong bóng xà phòng bay, lá chắn ánh sáng vàng trong suốt dựng trước cổng; Biệt đội Ánh Sao áo trắng khăn quàng đỏ rửa tay và đeo khẩu trang y tế, Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) cầm nhiệt kế lớn; sương xám bị chặn ngoài lá chắn. Phong cách 3D Pixar, không chữ."}], "beCum": {"cacBai": ["18", "19", "20", "21"], "moTa": "Cơ chế BỂ CHỦ ĐỀ (Khoa học lớp 5): tập Ôn tập chủ đề Vi khuẩn (Bài 21) rút mọi thử thách và câu cứu viện từ bể chung gồm tất cả câu trắc nghiệm có phương án của các bài 18, 19, 20, 21 thuộc Chủ đề 4, lọc theo mucDo đã khai trong rutCau, không lặp trong cùng một tập. Trường rutCau.bai là bài của tập; trường rutCau.be là danh sách bài của bể."}, "cacBai": ["20", "21"], "cacChuDe": ["4"], "id": "kh5-c8", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; là người dẫn đường của Biệt đội ở Trạm và đọc câu cứu viện trong thế giới Khoa học.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách của Thư viện Ánh Sao.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."}, "tap": [{"bai": "20", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Cổng Gác Phòng Bệnh là nơi Trạm dạy cách bảo vệ cơ thể. Sáng nay Sương Mù làm mờ bảng quy tắc phòng bệnh và nhòe trang Sổ Tay ghi về sâu răng và bệnh tả — hai bệnh do vi khuẩn gây ra.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc nè: sâu răng do vi khuẩn trong miệng tạo a-xít ăn mòn răng, nhất là khi thức ăn ngọt còn bám trên răng. Bệnh tả do vi khuẩn tả xâm nhập qua đường tiêu hoá, qua thức ăn và nước uống không sạch.", "nv": "Robot Hạt Đậu"}, {"loi": "Phòng sâu răng thì phải đánh răng đúng cách, hạn chế đồ ngọt và khám răng đều đặn. Phòng bệnh tả thì ăn chín, uống sôi, rửa tay sạch.", "nv": "Thảo Nguyên"}, {"loi": "Người bị bệnh tả mất nhiều nước nên cần được chăm sóc đặc biệt về nước và chất điện giải, đưa đi cơ sở y tế kịp thời. Hiểu đúng bệnh mới phòng đúng cách.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, vào cổng gác, dựng lại bảng quy tắc phòng bệnh thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Bảng quy tắc mờ thành hai nửa: nửa phòng sâu răng và nửa phòng bệnh tả. Cả lớp dựng lại nửa nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-chu", "dong": [{"loi": "Nửa này soi vào chiếc răng mẫu và mảng bám thức ăn. Chọn mẫu vật ghi đúng nguyên nhân sâu răng nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi soi vào chiếc răng mẫu, hiện những điều về vi khuẩn gây sâu răng. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "20", "mucDo": [1], "soCau": 1}}], "nhan": "Dựng nửa Kính hiển vi — phòng sâu răng"}, {"canh": [{"anh": "canh-kho", "dong": [{"loi": "Nửa này là các chai nước và bếp mẫu trong vườn thí nghiệm. Chọn chậu gắn thẻ đúng cách phòng bệnh tả nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày những chai nước uống và mẫu thức ăn, chờ cả lớp chọn đúng cách phòng tránh vi khuẩn tả. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "20", "mucDo": [1], "soCau": 1}}], "nhan": "Dựng nửa Vườn thí nghiệm — phòng bệnh tả"}]}, {"anh": "cau-suong", "bienCo": {"dong": [{"loi": "Sương làm mình quên mất khi nào răng sâu thường đau nhiều rồi!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là bảng quy tắc rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "20", "mucDo": [1], "soCau": 1}}, "danChuyen": "Bể quan sát hiện những mẫu nước sinh hoạt và khay dụng cụ vệ sinh răng miệng, chờ cả lớp chọn đúng việc phòng bệnh. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "20", "mucDo": [2], "soCau": 1}}, {"anh": "kho-sang", "danChuyen": "Cửa sổ bầu trời hiện câu hỏi khó nhất của bài: vì sao thức ăn bám trên răng lại làm răng sâu, và em sẽ khuyên bạn điều gì. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "20", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bảng quy tắc sáng rõ rồi! Hạt Đậu tặng biệt đội Chiếc Khẩu Trang Ánh Sao — nhớ đeo khi cần và rửa tay thật sạch nhé!", "nv": "Robot Hạt Đậu"}, {"loi": "Ngày mai mình tổng ôn cả chủ đề Vi khuẩn ở trạm tổng ôn cuối cổng gác.", "nv": "Thảo Nguyên"}, {"loi": "Tập sau mình ghé Trạm Tổng Ôn Vi Khuẩn nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Kẻ Thù Tí Hon Gây Bệnh", "tomTatTapTruoc": "Mùa trước: Biệt đội phá Cổng Kính Hiển Vi và nhận Huy Hiệu Người Gác Kính. Nay cả đội tới Cổng Gác Phòng Bệnh — mà bảng quy tắc phòng bệnh treo ở cổng đang bị sương làm mờ từng dòng...", "tuan": "21", "vatPham": "Chiếc Khẩu Trang Ánh Sao"}, {"bai": "21", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Trạm Tổng Ôn Vi Khuẩn nằm ngay bên Cổng Gác Phòng Bệnh. Muốn qua cổng, mỗi đội phải ghép đúng sơ đồ cả chủ đề: vi khuẩn ở đâu, loài nào có ích, loài nào gây bệnh và cách phòng tránh. Hôm nay sương làm lẫn hết các ô sơ đồ.", "nv": "Người kể"}, {"loi": "Trạm này ôn cả bốn bài của chủ đề Vi khuẩn nhé. Hạt Đậu nhắc một ý mẫu: vi khuẩn không nhìn thấy bằng mắt thường — muốn quan sát phải dùng kính hiển vi.", "nv": "Robot Hạt Đậu"}, {"loi": "Bí quyết là nhớ theo mạch chủ đề: xung quanh chúng ta → có ích trong bếp → gây bệnh và phòng tránh. Mở cửa sổ, rửa tay, làm sữa chua đúng cách đều nói lên điều gì đó về vi khuẩn.", "nv": "Thảo Nguyên"}, {"loi": "Ghép đúng hết các ô sơ đồ, trạm sẽ trao Sơ Đồ Chủ Đề Vi Khuẩn đã khôi phục.", "nv": "Đức Trí"}, {"loi": "Đúng rồi! Nào, vào trạm ghép lại sơ đồ cả chủ đề thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-kho", "dong": [{"loi": "Các ô sơ đồ lẫn thành hai chồng: chồng vi khuẩn quanh ta và chồng bạn — thù của con người. Cả lớp ghép chồng nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Chồng này có những ô về nơi sống của vi khuẩn và vi khuẩn có ích trong bếp. Chọn chậu gắn thẻ đúng nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày những ô sơ đồ về nơi sống của vi khuẩn và những hũ lên men, chờ cả lớp ghép đúng. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "21", "be": ["18", "19", "20", "21"], "mucDo": [1], "soCau": 1}}], "nhan": "Ghép chồng Vườn thí nghiệm — quanh ta và có ích"}, {"canh": [{"anh": "cau-suong", "dong": [{"loi": "Chồng này có những ô về vi khuẩn gây bệnh và cách phòng tránh. Chọn vị trí ghi đúng nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Bể quan sát hiện những ô sơ đồ về sâu răng, bệnh tả và cách phòng tránh, chờ cả lớp ghép đúng. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "21", "be": ["18", "19", "20", "21"], "mucDo": [1], "soCau": 1}}], "nhan": "Ghép chồng Bể quan sát — gây bệnh và phòng tránh"}]}, {"anh": "kho-sang", "bienCo": {"dong": [{"loi": "Sương làm hai ô sơ đồ dính chặt vào nhau rồi, mình không tách được ô nào thuộc bài nào nữa!", "nv": "Minh Anh"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là hai ô tách ra rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "21", "be": ["18", "19", "20", "21"], "mucDo": [1], "soCau": 1}}, "danChuyen": "Cửa sổ bầu trời hiện những ý tổng hợp của cả chủ đề Vi khuẩn, chờ cả lớp gọi đúng. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "21", "be": ["18", "19", "20", "21"], "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi soi vào ô sơ đồ khó nhất của trạm, trộn cả chủ đề Vi khuẩn. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "21", "be": ["18", "19", "20", "21"], "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Mọi ô sơ đồ đã ghép đúng! Trạm Tổng Ôn trao biệt đội Sơ Đồ Chủ Đề Vi Khuẩn — trọn chủ đề đã nằm gọn trong một sơ đồ!", "nv": "Robot Hạt Đậu"}, {"loi": "Nhìn kìa — Cổng Gác Phòng Bệnh đang chìm trong lớp sương dày nhất của chủ đề...", "nv": "Tuấn Kiệt"}, {"loi": "Tập đặc biệt: lên cổng gác, phá Cổng Gác Phòng Bệnh thôi, cả lớp!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Trạm Tổng Ôn Vi Khuẩn", "tomTatTapTruoc": "Tập trước: Biệt đội dựng lại bảng quy tắc phòng bệnh và nhận Chiếc Khẩu Trang Ánh Sao. Trước khi phá cổng mùa, cả đội ghé Trạm Tổng Ôn Vi Khuẩn — nơi sơ đồ cả chủ đề đang bị sương làm lẫn lộn...", "tuan": "21", "vatPham": "Sơ Đồ Chủ Đề Vi Khuẩn"}, {"bai": "20+21", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Sâu răng, bệnh tả — những kẻ thù tí hon là quân của ta. Không có lá chắn hiểu biết, các ngươi sẽ chẳng bảo vệ nổi ai...", "nv": "Sương Mù"}, {"loi": "Biệt đội sẵn sàng! Lá chắn của chúng mình chính là hiểu đúng bệnh và làm đúng cách phòng tránh. Hạt Đậu ơi, nhắc luật cổng nào!", "nv": "Minh Anh"}, {"loi": "Luật cổng: bốn đòn luân phiên hai bài của mùa. Mỗi câu đúng là một bánh răng của cỗ máy trung tâm sáng lên, phá khiên sương trước cổng. Cố lên, các bạn ơi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Cỗ máy trung tâm quay bánh răng đầu tiên: vi khuẩn gây bệnh — sâu răng và bệnh tả. Cả lớp chọn chiêu thức đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "20", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Một bánh răng đã sáng! Đòn tiếp theo là những ý tổng ôn của cả chủ đề Vi khuẩn. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "21", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù tung khói vào cổng gác. Cả lớp chọn chiêu thức đúng về cách phòng tránh bệnh do vi khuẩn nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "20", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối của mùa là ô sơ đồ tổng hợp khó nhất của chủ đề. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "21", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Thôi được... Cổng Gác Phòng Bệnh là của các ngươi. Ta rút về phía Sảnh Sức Khỏe đây — nơi cơ thể các ngươi đang lớn lên từng ngày, xem các ngươi giữ được bao lâu...", "nv": "Sương Mù"}, {"loi": "Cổng mở rồi! Hạt Đậu trao biệt đội Lá Chắn Phòng Bệnh — chủ đề Vi khuẩn đã khép lại trọn vẹn trong Sổ Tay Thí Nghiệm.", "nv": "Robot Hạt Đậu"}, {"loi": "Bốn bài của chủ đề đã sáng rõ: vi khuẩn có bạn có thù, hiểu đúng thì phòng tránh đúng.", "nv": "Đức Trí"}, {"loi": "Mùa sau mình vào Sảnh Lớn Lên Từng Ngày — khám phá chính cơ thể chúng mình nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Gác Phòng Bệnh", "tomTatTapTruoc": "Biệt đội đã khôi phục hai trang Sổ Tay của Cổng Gác Phòng Bệnh: vi khuẩn gây bệnh và cách phòng tránh, cùng sơ đồ tổng ôn cả chủ đề Vi khuẩn. Giờ đây Sương Mù Quên Lãng dồn hết sương của chủ đề giữ Cổng Gác Phòng Bệnh...", "tuan": "21", "vatPham": "Lá Chắn Phòng Bệnh"}], "tenMua": "Mùa 8 — Cổng Gác Phòng Bệnh", "tomTatMua": "Sau Phòng Kính Hiển Vi, Biệt đội Ánh Sao tới Cổng Gác Phòng Bệnh — trạm gác của Trạm Khám Phá Xanh, nơi cả đội học cách nhận diện vi khuẩn gây bệnh như vi khuẩn sâu răng và vi khuẩn tả, rồi tổng ôn cả chủ đề Vi khuẩn ở trạm tổng ôn cuối mùa. Sương Mù làm mờ bảng quy tắc phòng bệnh treo ở cổng gác; chỉ có hiểu đúng và làm đúng mới dựng lại được lá chắn bảo vệ mọi người."}, {"anhBia": "sanh-lon-len-tung-ngay", "anhCanTao": [{"khoa": "sanh-lon-len-tung-ngay", "moTa": "Sảnh lớn lên từng ngày: thước đo chiều cao khổng lồ nhiều vạch màu gắn trên tường, các cột mốc tuổi xếp thành hàng, tấm gương lớn sáng; Biệt đội Ánh Sao áo trắng khăn quàng đỏ đứng đo chiều cao và so vai nhau, Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) ghi số đo vào sổ tay; ánh sáng ấm, sương xám mỏng ở góc sảnh. Phong cách 3D Pixar, không chữ."}], "cacBai": ["22", "23", "24"], "cacChuDe": ["5"], "id": "kh5-c9", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; là người dẫn đường của Biệt đội ở Trạm và đọc câu cứu viện trong thế giới Khoa học.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách của Thư viện Ánh Sao.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."}, "tap": [{"bai": "22", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Giữa Sảnh Lớn Lên Từng Ngày treo sơ đồ lớn về sự hình thành cơ thể người. Sáng nay Sương Mù làm nhòe các mũi tên của sơ đồ — chẳng ai còn nối đúng trứng, tinh trùng và sự thụ tinh nữa.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc nè: cơ thể người được hình thành từ sự kết hợp giữa trứng của mẹ và tinh trùng của bố. Sự kết hợp đó gọi là sự thụ tinh; trứng đã thụ tinh gọi là hợp tử.", "nv": "Robot Hạt Đậu"}, {"loi": "Hợp tử phát triển thành phôi, rồi thành thai nhi trong tử cung của mẹ. Khoảng chín tháng sau thụ tinh, em bé được sinh ra.", "nv": "Thảo Nguyên"}, {"loi": "Sự sinh sản có ý nghĩa lớn: giúp gia đình, dòng họ tiếp nối các thế hệ, và xã hội có thêm những con người mới. Nói về sơ đồ này, thuật ngữ không thể thiếu là sự thụ tinh.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, vào sảnh, nối lại các mũi tên của sơ đồ thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Sơ đồ mờ thành hai nửa: nửa ý nghĩa của sự sinh sản và nửa quá trình thụ tinh. Cả lớp khôi phục nửa nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-chu", "dong": [{"loi": "Nửa này soi vào các ô thuật ngữ của sơ đồ: trứng, tinh trùng, hợp tử. Chọn mẫu vật ghi đúng nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi soi vào các ô thuật ngữ trên sơ đồ hình thành cơ thể, chờ cả lớp gọi đúng từng thuật ngữ. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "22", "mucDo": [1], "soCau": 1}}], "nhan": "Khôi phục nửa Kính hiển vi — các thuật ngữ"}, {"canh": [{"anh": "canh-kho", "dong": [{"loi": "Nửa này là các chậu cây con và mầm sống trong vườn thí nghiệm — giống như một cơ thể bắt đầu lớn lên. Chọn chậu gắn thẻ đúng ý nghĩa sinh sản nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày những chậu mầm sống và cây con, chờ cả lớp chọn đúng ý nghĩa của sự sinh sản ở người. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "22", "mucDo": [1], "soCau": 1}}], "nhan": "Khôi phục nửa Vườn thí nghiệm — ý nghĩa sinh sản"}]}, {"anh": "cau-suong", "bienCo": {"dong": [{"loi": "Sương làm mình lẫn lộn thứ tự rồi: hợp tử trước hay phôi trước nhỉ!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là thứ tự rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "22", "mucDo": [1], "soCau": 1}}, "danChuyen": "Bể quan sát hiện các ô sơ đồ theo thứ tự hình thành cơ thể người, chờ cả lớp xếp đúng trình tự. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "22", "mucDo": [2], "soCau": 1}}, {"anh": "kho-sang", "danChuyen": "Cửa sổ bầu trời hiện câu hỏi khó nhất của bài: vì sao sự sinh sản giúp tiếp nối các thế hệ, và nếu thiếu sự thụ tinh thì điều gì không xảy ra. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "22", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Sơ đồ nối đúng hết rồi! Hạt Đậu tặng biệt đội Sơ Đồ Hình Thành Cơ Thể — trang Sổ Tay về chính chúng mình đã sáng rõ.", "nv": "Robot Hạt Đậu"}, {"loi": "Ngày mai mình đo các giai đoạn lớn lên của con người: ấu thơ, vị thành niên, trưởng thành.", "nv": "Thảo Nguyên"}, {"loi": "Tập sau mình tới thước đo các giai đoạn nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Cơ Thể Người Bắt Đầu Thế Nào", "tomTatTapTruoc": "Mùa trước: Biệt đội phá Cổng Gác Phòng Bệnh, nhận Lá Chắn Phòng Bệnh và khép trọn chủ đề Vi khuẩn. Nay cả đội vào Sảnh Lớn Lên Từng Ngày — mà sơ đồ hình thành cơ thể người treo giữa sảnh đang bị sương làm nhòe từng mũi tên...", "tuan": "22–23", "vatPham": "Sơ Đồ Hình Thành Cơ Thể"}, {"bai": "23", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Trong sảnh có thước đo khổng lồ chia các giai đoạn phát triển chính của con người. Sáng nay Sương Mù làm mờ các vạch thước — chẳng ai còn biết mình đang ở giai đoạn nào nữa.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc nè: con người lớn lên qua các giai đoạn chính — tuổi ấu thơ, tuổi vị thành niên và tuổi trưởng thành. Tuổi dậy thì nằm chủ yếu ở đầu tuổi vị thành niên.", "nv": "Robot Hạt Đậu"}, {"loi": "Tuổi dậy thì ở nữ thường bắt đầu khoảng 10–11 tuổi, ở nam khoảng 11–12 tuổi. Học sinh lớp 5 như chúng mình đang ở cuối tuổi ấu thơ, bước vào đầu tuổi vị thành niên.", "nv": "Thảo Nguyên"}, {"loi": "Người trưởng thành có vai trò nổi bật là lao động, xây dựng gia đình và xã hội. Còn tuổi vị thành niên thì cần rèn luyện và học tập tốt để chuẩn bị cho tương lai.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, làm rõ lại các vạch thước đo thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-kho", "dong": [{"loi": "Thước đo mờ thành hai nửa: nửa các giai đoạn đầu đời và nửa tuổi vị thành niên — trưởng thành. Cả lớp làm rõ nửa nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Nửa này là các chậu cây từ hạt mầm tới cây non trong vườn thí nghiệm — như tuổi ấu thơ của con người. Chọn chậu gắn thẻ đúng nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày những chậu cây theo từng chặng lớn lên, chờ cả lớp gắn đúng giai đoạn đầu đời của con người. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "23", "mucDo": [1], "soCau": 1}}], "nhan": "Làm rõ nửa Vườn thí nghiệm — giai đoạn đầu đời"}, {"canh": [{"anh": "cau-suong", "dong": [{"loi": "Nửa này là bể quan sát với các sinh vật đang thay hình đổi dạng. Chọn vị trí ghi đúng về tuổi vị thành niên và trưởng thành nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Bể quan sát hiện những sinh vật ở các chặng phát triển khác nhau, chờ cả lớp nhận đúng giai đoạn vị thành niên và trưởng thành của con người. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "23", "mucDo": [1], "soCau": 1}}], "nhan": "Làm rõ nửa Bể quan sát — vị thành niên và trưởng thành"}]}, {"anh": "kho-sang", "bienCo": {"dong": [{"loi": "Sương làm mình hoa mắt rồi, không nhớ tuổi dậy thì nằm ở đâu trong các giai đoạn nữa!", "nv": "Thảo Nguyên"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là vạch thước rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "23", "mucDo": [1], "soCau": 1}}, "danChuyen": "Cửa sổ bầu trời hiện hình một bạn học sinh lớp 5 và một người 35 tuổi, chờ cả lớp gọi đúng giai đoạn của từng người. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "23", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi soi vào vạch thước khó nhất: sắp xếp đúng thứ tự các giai đoạn phát triển chính của con người. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "23", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Thước đo rõ mọi vạch rồi! Hạt Đậu tặng biệt đội Thước Đo Các Giai Đoạn — ai cũng biết mình đang ở chặng nào của đường lớn lên.", "nv": "Robot Hạt Đậu"}, {"loi": "Ngày mai mình tìm hiểu nam và nữ: khác nhau ở đặc điểm sinh học, còn vai trò trong gia đình và xã hội thì bình đẳng.", "nv": "Đức Trí"}, {"loi": "Tập sau mình tới tấm gương tôn trọng nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Những Chặng Đường Lớn Lên", "tomTatTapTruoc": "Tập trước: Biệt đội nối lại sơ đồ hình thành cơ thể người và nhận Sơ Đồ Hình Thành Cơ Thể. Hôm nay thước đo khổng lồ trong sảnh bị sương làm mờ các vạch giai đoạn...", "tuan": "23–24", "vatPham": "Thước Đo Các Giai Đoạn"}, {"bai": "24", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Cuối sảnh có tấm gương lớn ghi hai cột: đặc điểm sinh học và đặc điểm xã hội của nam và nữ. Sáng nay Sương Mù phủ mờ tấm gương — các dòng chữ lẫn vào nhau, chẳng ai phân biệt được nữa.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc nè: đặc điểm sinh học của nam và nữ khác nhau cơ bản ở cơ quan sinh dục. Chỉ nữ mới mang thai và cho con bú được — đó là đặc điểm sinh học riêng của nữ.", "nv": "Robot Hạt Đậu"}, {"loi": "Còn nấu ăn, học tập, tham gia công việc xã hội là đặc điểm xã hội — nam và nữ đều làm được. Ở nhà, bố nấu ăn chăm con, mẹ đi làm và tham gia việc xã hội là chuyện bình thường.", "nv": "Thảo Nguyên"}, {"loi": "Ngày nay nhiều phụ nữ giữ vị trí lãnh đạo — điều đó cho thấy nam và nữ bình đẳng về vai trò. Khi bạn khác giới nêu ý kiến, mình lắng nghe và tôn trọng như với mọi bạn khác.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, lau sáng tấm gương tôn trọng thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "cau-suong", "dong": [{"loi": "Tấm gương mờ thành hai nửa: nửa đặc điểm sinh học và nửa đặc điểm xã hội. Cả lớp lau sáng nửa nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "cau-suong", "dong": [{"loi": "Nửa này soi các sinh vật trong bể: con nào mang thai, con nào chăm con. Chọn vị trí ghi đúng đặc điểm sinh học nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Bể quan sát hiện những sinh vật với đặc điểm sinh học khác nhau, chờ cả lớp nhận đúng đặc điểm sinh học của nam và nữ. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "24", "mucDo": [1], "soCau": 1}}], "nhan": "Lau sáng nửa Bể quan sát — đặc điểm sinh học"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Nửa này mở ra khung trời sinh hoạt: người nấu ăn, người đi làm, người lãnh đạo. Chọn hiện tượng ghi đúng đặc điểm xã hội nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "kho-sang", "danChuyen": "Cửa sổ bầu trời hiện những hình ảnh sinh hoạt gia đình và xã hội, chờ cả lớp nhận đúng đặc điểm xã hội của nam và nữ. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "24", "mucDo": [1], "soCau": 1}}], "nhan": "Lau sáng nửa Cửa sổ bầu trời — đặc điểm xã hội"}]}, {"anh": "canh-chu", "bienCo": {"dong": [{"loi": "Sương làm mình lẫn rồi: nấu ăn là đặc điểm sinh học hay xã hội nhỉ!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là tấm gương trong veo ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "24", "mucDo": [1], "soCau": 1}}, "danChuyen": "Kính hiển vi soi vào từng dòng chữ trên tấm gương, chờ cả lớp phân loại đúng sinh học hay xã hội. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "24", "mucDo": [2], "soCau": 1}}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm hiện câu hỏi khó nhất: vì sao không nên phân biệt đối xử giữa nam và nữ, và thái độ đúng khi bạn khác giới nêu ý kiến. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "24", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Tấm gương trong veo rồi! Hạt Đậu tặng biệt đội Tấm Gương Tôn Trọng — soi vào là nhớ: khác nhau để tôn trọng nhau hơn.", "nv": "Robot Hạt Đậu"}, {"loi": "Chủ đề Con người và sức khoẻ còn nửa sau: chăm sóc tuổi dậy thì và lá chắn an toàn.", "nv": "Thảo Nguyên"}, {"loi": "Mùa sau mình sang Lá Chắn Tuổi Dậy Thì nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t3", "ten": "Tập 3 — Nam Và Nữ, Tôn Trọng Nhau", "tomTatTapTruoc": "Tập trước: Biệt đội làm rõ thước đo các giai đoạn và nhận Thước Đo Các Giai Đoạn. Hôm nay tấm gương lớn trong sảnh bị sương phủ mờ — nơi cả đội học cách phân biệt đặc điểm sinh học và đặc điểm xã hội của nam và nữ...", "tuan": "25", "vatPham": "Tấm Gương Tôn Trọng"}, {"bai": "22+23+24", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Cơ thể, giai đoạn, giới tính — những trang sách về chính các ngươi là của ta. Không hiểu nổi mình, các ngươi sẽ lớn lên trong sương mù mãi...", "nv": "Sương Mù"}, {"loi": "Biệt đội sẵn sàng! Hiểu mình chính là ánh sáng của chúng mình. Hạt Đậu ơi, nhắc luật cổng nào!", "nv": "Minh Anh"}, {"loi": "Luật cổng: bốn đòn luân phiên ba bài của mùa. Mỗi câu đúng là một bánh răng của cỗ máy trung tâm sáng lên, phá khiên sương trước cổng. Cố lên, các bạn ơi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Cỗ máy trung tâm quay bánh răng đầu tiên: sự hình thành cơ thể người — trứng, tinh trùng và sự thụ tinh. Cả lớp chọn chiêu thức đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "22", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Một bánh răng đã sáng! Đòn tiếp theo là những chặng đường lớn lên của con người. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "23", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù tung khói vào tấm gương tôn trọng. Cả lớp chọn chiêu thức đúng về nam và nữ nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "24", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối của mùa quay lại sơ đồ hình thành cơ thể. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "22", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Thôi được... Cổng Sảnh Lớn Lên là của các ngươi. Ta rút về khu vườn yên tĩnh phía sau đây — nơi tuổi dậy thì của các ngươi đang đến, xem lá chắn của các ngươi chắc đến đâu...", "nv": "Sương Mù"}, {"loi": "Cổng mở rồi! Hạt Đậu trao biệt đội Huy Hiệu Hiểu Mình — ba trang Sổ Tay về chính cơ thể chúng mình đã sáng rõ.", "nv": "Robot Hạt Đậu"}, {"loi": "Hiểu cơ thể hình thành thế nào, mình đang ở giai đoạn nào và tôn trọng mọi bạn — đó là nền của sức khoẻ.", "nv": "Đức Trí"}, {"loi": "Mùa sau mình sang Lá Chắn Tuổi Dậy Thì — học chăm sóc và bảo vệ chính mình nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Sảnh Lớn Lên", "tomTatTapTruoc": "Biệt đội đã khôi phục ba trang Sổ Tay của Sảnh Lớn Lên Từng Ngày: hình thành cơ thể, các giai đoạn lớn lên và nam — nữ tôn trọng nhau. Giờ đây Sương Mù Quên Lãng dồn sương giữ Cổng Sảnh Lớn Lên ở cuối sảnh...", "tuan": "25", "vatPham": "Huy Hiệu Hiểu Mình"}], "tenMua": "Mùa 9 — Sảnh Lớn Lên Từng Ngày", "tomTatMua": "Biệt đội Ánh Sao bước vào Sảnh Lớn Lên Từng Ngày — sảnh trang trọng của Trạm Khám Phá Xanh, nơi cả đội tìm hiểu cơ thể người được hình thành thế nào, con người lớn lên qua những giai đoạn nào, và nam với nữ khác nhau ra sao để tôn trọng nhau hơn. Sương Mù làm nhòe sơ đồ hình thành cơ thể và mờ thước đo các giai đoạn treo trong sảnh; chỉ có hiểu đúng, cả đội mới khôi phục được những trang Sổ Tay về chính mình."}, {"anhBia": "la-chan-tuoi-day-thi", "anhCanTao": [{"khoa": "la-chan-tuoi-day-thi", "moTa": "Khu vườn yên tĩnh của Trạm với lá chắn ánh sáng vàng dịu hình vòm bảo vệ: Biệt đội Ánh Sao áo trắng khăn quàng đỏ ngồi đọc sách và trò chuyện dưới tán cây lớn, ghế đá và lối đi sỏi sạch; Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) ngồi cạnh với cuốn sổ tay; không khí ấm áp, riêng tư, sương xám bị đẩy ra ngoài vòm sáng. Phong cách 3D Pixar, không chữ."}], "beCum": {"cacBai": ["22", "23", "24", "25", "26", "27"], "moTa": "Cơ chế BỂ CHỦ ĐỀ (Khoa học lớp 5): tập Ôn tập chủ đề Con người và sức khoẻ (Bài 27) rút mọi thử thách và câu cứu viện từ bể chung gồm tất cả câu trắc nghiệm có phương án của các bài 22, 23, 24, 25, 26, 27 thuộc Chủ đề 5, lọc theo mucDo đã khai trong rutCau, không lặp trong cùng một tập. Trường rutCau.bai là bài của tập; trường rutCau.be là danh sách bài của bể."}, "cacBai": ["25", "26", "27"], "cacChuDe": ["5"], "id": "kh5-c10", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; là người dẫn đường của Biệt đội ở Trạm và đọc câu cứu viện trong thế giới Khoa học.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách của Thư viện Ánh Sao.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."}, "tap": [{"bai": "25", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Khu vườn của Lá Chắn Tuổi Dậy Thì yên tĩnh và xanh mát. Sáng nay Sương Mù làm mờ bảng hướng dẫn chăm sóc sức khoẻ tuổi dậy thì treo giữa vườn — chẳng ai còn nhớ phải chăm sóc mình thế nào khi cơ thể thay đổi.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc nè: tuổi dậy thì cần chăm sóc cả thể chất lẫn tinh thần. Thể chất là ăn đủ chất, vận động, ngủ đủ giấc và giữ vệ sinh cơ thể; tinh thần là vui vẻ, chia sẻ với người tin cậy khi lo lắng.", "nv": "Robot Hạt Đậu"}, {"loi": "Ở tuổi dậy thì cơ thể ra nhiều mồ hôi và chất nhờn hơn nên càng cần tắm gội bằng nước sạch, vệ sinh cơ quan sinh dục ngoài hằng ngày để tránh viêm nhiễm và mùi khó chịu.", "nv": "Thảo Nguyên"}, {"loi": "Khi cơ thể thay đổi, đừng hoảng và đừng giấu: hãy hỏi bố mẹ, thầy cô hoặc người đáng tin cậy. Bạn nào đang lo lắng vì thay đổi, mình nên lắng nghe và động viên bạn.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, vào vườn, làm rõ bảng hướng dẫn chăm sóc thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Bảng hướng dẫn mờ thành hai nửa: nửa chăm sóc thể chất và nửa chăm sóc tinh thần. Cả lớp làm rõ nửa nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-chu", "dong": [{"loi": "Nửa này soi vào những giọt mồ hôi và vi khuẩn trên da sau khi vận động. Chọn mẫu vật ghi đúng cách giữ vệ sinh nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi soi vào làn da sau giờ vận động, hiện những điều về vệ sinh cơ thể ở tuổi dậy thì. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "25", "mucDo": [1], "soCau": 1}}], "nhan": "Làm rõ nửa Kính hiển vi — vệ sinh cơ thể"}, {"canh": [{"anh": "canh-kho", "dong": [{"loi": "Nửa này là các chậu cây được chăm đủ nắng, đủ nước trong vườn thí nghiệm — như cơ thể được ăn đủ, ngủ đủ. Chọn chậu gắn thẻ đúng việc chăm thể chất nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày những chậu cây với chế độ chăm sóc khác nhau, chờ cả lớp chọn đúng việc chăm sóc sức khoẻ thể chất. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "25", "mucDo": [1], "soCau": 1}}], "nhan": "Làm rõ nửa Vườn thí nghiệm — chăm sóc thể chất"}]}, {"anh": "cau-suong", "bienCo": {"dong": [{"loi": "Sương làm mình lẫn rồi: ngủ đủ giấc là chăm thể chất hay tinh thần nhỉ!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là bảng hướng dẫn rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "25", "mucDo": [1], "soCau": 1}}, "danChuyen": "Bể quan sát hiện những hình ảnh sinh hoạt hằng ngày: vận động, ăn uống, ngủ nghỉ, chờ cả lớp phân loại đúng mặt chăm sóc. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "25", "mucDo": [2], "soCau": 1}}, {"anh": "kho-sang", "danChuyen": "Cửa sổ bầu trời hiện câu hỏi khó nhất: vì sao phải vệ sinh cơ quan sinh dục ngoài hằng ngày, và em nên làm gì khi bạn lo lắng vì cơ thể thay đổi. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "25", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bảng hướng dẫn rõ ràng rồi! Hạt Đậu tặng biệt đội Chiếc Gương Soi Sức Khỏe — soi vào là nhớ chăm sóc mình mỗi ngày.", "nv": "Robot Hạt Đậu"}, {"loi": "Ngày mai mình lập danh sách người đáng tin cậy và học cách phòng tránh xâm hại.", "nv": "Thảo Nguyên"}, {"loi": "Tập sau mình dựng lá chắn an toàn nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Chăm Sóc Tuổi Dậy Thì", "tomTatTapTruoc": "Mùa trước: Biệt đội phá Cổng Sảnh Lớn Lên và nhận Huy Hiệu Hiểu Mình. Nay cả đội vào khu vườn của Lá Chắn Tuổi Dậy Thì — mà bảng hướng dẫn chăm sóc sức khoẻ treo giữa vườn đang bị sương làm mờ...", "tuan": "26–27", "vatPham": "Chiếc Gương Soi Sức Khỏe"}, {"bai": "26", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Giữa vườn có tấm bảng vàng ghi danh sách người đáng tin cậy của mỗi bạn. Sáng nay Sương Mù che mờ tấm bảng — chẳng ai còn nhớ khi không an toàn thì tìm đến ai và làm gì.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc điều quan trọng nhất nè: mọi trẻ em đều có quyền được an toàn và quyền phản đối mọi sự xâm hại. Cảm giác không an toàn là tín hiệu phải hành động ngay.", "nv": "Robot Hạt Đậu"}, {"loi": "Người đáng tin cậy thường là bố mẹ, thầy cô, người thân trong gia đình. Khi có người rủ đi một mình, hứa cho quà và bảo đừng nói với bố mẹ — đó là dấu hiệu nguy hiểm, phải từ chối và kể ngay với người đáng tin cậy.", "nv": "Thảo Nguyên"}, {"loi": "Nếu bạn trong lớp có nguy cơ bị xâm hại, mình không giữ bí mật hộ kẻ xấu: phải báo cho thầy cô hoặc người lớn đáng tin cậy để giúp bạn. Lập sẵn danh sách người đáng tin cậy giúp mình phản ứng nhanh khi cần.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, vào vườn, làm rõ tấm bảng vàng thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-kho", "dong": [{"loi": "Tấm bảng mờ thành hai nửa: nửa quyền được an toàn và nửa nhận biết nguy cơ. Cả lớp làm rõ nửa nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Nửa này là các chậu cây có hàng rào bảo vệ quanh vườn thí nghiệm — như quyền được an toàn của mỗi bạn. Chọn chậu gắn thẻ đúng nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày những chậu cây sau hàng rào bảo vệ, chờ cả lớp chọn đúng quyền và cảm giác an toàn của trẻ em. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "26", "mucDo": [1], "soCau": 1}}], "nhan": "Làm rõ nửa Vườn thí nghiệm — quyền được an toàn"}, {"canh": [{"anh": "cau-suong", "dong": [{"loi": "Nửa này là bể quan sát với những tình huống lạ: người rủ đi riêng, hứa quà, bắt giữ bí mật. Chọn vị trí ghi đúng dấu hiệu nguy cơ nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Bể quan sát hiện những tình huống thường ngày, chờ cả lớp nhận đúng nguy cơ bị xâm hại. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "26", "mucDo": [1], "soCau": 1}}], "nhan": "Làm rõ nửa Bể quan sát — nhận biết nguy cơ"}]}, {"anh": "kho-sang", "bienCo": {"dong": [{"loi": "Sương làm mình rối rồi: người ta bảo giữ bí mật với bố mẹ thì có nghe theo không nhỉ!", "nv": "Thảo Nguyên"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là tấm bảng rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "26", "mucDo": [1], "soCau": 1}}, "danChuyen": "Cửa sổ bầu trời hiện những tình huống cần ứng phó, chờ cả lớp chọn cách làm đúng để bảo vệ mình và bạn. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "26", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi soi vào tình huống khó nhất của bài: chọn cách ứng phó đúng khi có nguy cơ bị xâm hại và hiểu vì sao phải lập sẵn danh sách người đáng tin cậy. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "26", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Tấm bảng vàng sáng rõ rồi! Hạt Đậu tặng biệt đội Tấm Thẻ Người Đáng Tin Cậy — hãy ghi tên bố mẹ, thầy cô vào thẻ của mình nhé!", "nv": "Robot Hạt Đậu"}, {"loi": "Ngày mai mình tổng ôn cả chủ đề Con người và sức khoẻ ở trạm tổng ôn cuối mùa.", "nv": "Đức Trí"}, {"loi": "Tập sau mình ghé Trạm Tổng Ôn Sức Khỏe nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Lá Chắn An Toàn Của Em", "tomTatTapTruoc": "Tập trước: Biệt đội làm rõ bảng hướng dẫn chăm sóc tuổi dậy thì và nhận Chiếc Gương Soi Sức Khỏe. Hôm nay tấm bảng danh sách người đáng tin cậy trong vườn bị sương che mờ — danh sách quan trọng nhất của mùa...", "tuan": "27–28", "vatPham": "Tấm Thẻ Người Đáng Tin Cậy"}, {"bai": "27", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Trạm Tổng Ôn Sức Khỏe nằm ngay bên khu vườn của Lá Chắn. Muốn phá cổng mùa, mỗi đội phải ghép đúng sơ đồ cả chủ đề: từ sự hình thành cơ thể, các giai đoạn lớn lên, nam và nữ, tới chăm sóc dậy thì và phòng tránh xâm hại. Hôm nay sương làm lẫn hết các ô sơ đồ.", "nv": "Người kể"}, {"loi": "Trạm này ôn cả sáu bài của chủ đề Con người và sức khoẻ nhé. Hạt Đậu nhắc một ý mẫu: cơ thể người được hình thành từ sự kết hợp giữa trứng và tinh trùng.", "nv": "Robot Hạt Đậu"}, {"loi": "Bí quyết là nhớ theo mạch chủ đề: hình thành → lớn lên qua các giai đoạn → tôn trọng nhau → chăm sóc mình → bảo vệ mình. Ở tuổi dậy thì, em cần giữ vệ sinh, ăn ngủ điều độ và tìm người đáng tin cậy khi không an toàn.", "nv": "Thảo Nguyên"}, {"loi": "Ghép đúng hết các ô sơ đồ, trạm sẽ trao Sơ Đồ Chủ Đề Sức Khỏe đã khôi phục.", "nv": "Đức Trí"}, {"loi": "Đúng rồi! Nào, vào trạm ghép lại sơ đồ cả chủ đề thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "cau-suong", "dong": [{"loi": "Các ô sơ đồ lẫn thành hai chồng: chồng hình thành và lớn lên, chồng chăm sóc và bảo vệ. Cả lớp ghép chồng nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "cau-suong", "dong": [{"loi": "Chồng này có những ô về sự hình thành cơ thể và các giai đoạn phát triển. Chọn vị trí ghi đúng nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Bể quan sát hiện những ô sơ đồ về hình thành cơ thể và các giai đoạn lớn lên, chờ cả lớp ghép đúng. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "27", "be": ["22", "23", "24", "25", "26", "27"], "mucDo": [1], "soCau": 1}}], "nhan": "Ghép chồng Bể quan sát — hình thành và lớn lên"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Chồng này có những ô về nam và nữ, chăm sóc dậy thì và phòng tránh xâm hại. Chọn hiện tượng ghi đúng nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "kho-sang", "danChuyen": "Cửa sổ bầu trời hiện những ô sơ đồ về tôn trọng, chăm sóc và bảo vệ bản thân, chờ cả lớp ghép đúng. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "27", "be": ["22", "23", "24", "25", "26", "27"], "mucDo": [1], "soCau": 1}}], "nhan": "Ghép chồng Cửa sổ bầu trời — chăm sóc và bảo vệ"}]}, {"anh": "canh-chu", "bienCo": {"dong": [{"loi": "Sương làm hai ô sơ đồ dính chặt vào nhau rồi, mình không tách được ô nào thuộc bài nào nữa!", "nv": "Minh Anh"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là hai ô tách ra rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "27", "be": ["22", "23", "24", "25", "26", "27"], "mucDo": [1], "soCau": 1}}, "danChuyen": "Kính hiển vi soi vào những ô sơ đồ tổng hợp của cả chủ đề, chờ cả lớp gọi đúng. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "27", "be": ["22", "23", "24", "25", "26", "27"], "mucDo": [2], "soCau": 1}}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày ô sơ đồ khó nhất của trạm: chọn cách ứng xử đúng trong đời sống sau khi học cả chủ đề. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "27", "be": ["22", "23", "24", "25", "26", "27"], "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Mọi ô sơ đồ đã ghép đúng! Trạm Tổng Ôn trao biệt đội Sơ Đồ Chủ Đề Sức Khỏe — trọn chủ đề đã nằm gọn trong một sơ đồ!", "nv": "Robot Hạt Đậu"}, {"loi": "Nhìn kìa — vòm lá chắn trên khu vườn đang chìm trong lớp sương dày nhất của mùa...", "nv": "Tuấn Kiệt"}, {"loi": "Tập đặc biệt: dựng Lá Chắn Tuổi Dậy Thì thôi, cả lớp!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t3", "ten": "Tập 3 — Trạm Tổng Ôn Sức Khỏe", "tomTatTapTruoc": "Tập trước: Biệt đội làm rõ tấm bảng người đáng tin cậy và nhận Tấm Thẻ Người Đáng Tin Cậy. Trước khi phá cổng mùa, cả đội ghé Trạm Tổng Ôn Sức Khỏe — nơi sơ đồ cả chủ đề Con người và sức khoẻ đang bị sương làm lẫn...", "tuan": "28", "vatPham": "Sơ Đồ Chủ Đề Sức Khỏe"}, {"bai": "25+26+27", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Cơ thể thay đổi, nguy cơ rình rập — tuổi dậy thì là lúc các ngươi dễ hoang mang nhất. Không có lá chắn, các ngươi sẽ chẳng bảo vệ nổi chính mình...", "nv": "Sương Mù"}, {"loi": "Biệt đội sẵn sàng! Lá chắn của chúng mình là hiểu đúng, chăm sóc đúng và biết tìm người đáng tin cậy. Hạt Đậu ơi, nhắc luật cổng nào!", "nv": "Minh Anh"}, {"loi": "Luật cổng: bốn đòn luân phiên ba bài của mùa. Mỗi câu đúng là một bánh răng của cỗ máy trung tâm sáng lên, dựng thêm một lớp lá chắn ánh sáng. Cố lên, các bạn ơi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Cỗ máy trung tâm quay bánh răng đầu tiên: chăm sóc sức khoẻ tuổi dậy thì — thể chất và tinh thần. Cả lớp chọn chiêu thức đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "25", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Một bánh răng đã sáng! Đòn tiếp theo là phòng tránh bị xâm hại: nhận biết nguy cơ và ứng phó đúng. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "26", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù tung khói vào vòm lá chắn. Cả lớp chọn chiêu thức đúng từ sơ đồ tổng ôn cả chủ đề nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "27", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối của mùa quay lại vệ sinh cơ thể ở tuổi dậy thì. Cả lớp chọn chiêu thức đúng để lá chắn vững vàng, phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "25", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Thôi được... Cổng Lá Chắn Vàng là của các ngươi. Ta rút ra Đài Quan Sát Trái Đất đây — trạm cuối cùng của năm, xem các ngươi giữ nổi hành tinh xanh này không...", "nv": "Sương Mù"}, {"loi": "Cổng mở rồi! Hạt Đậu trao biệt đội Lá Chắn Tuổi Dậy Thì — chủ đề Con người và sức khoẻ đã khép trọn trong Sổ Tay Thí Nghiệm.", "nv": "Robot Hạt Đậu"}, {"loi": "Chăm sóc mình, bảo vệ mình và giúp bạn bảo vệ bạn — đó là những trang Sổ Tay quý nhất của năm cuối cấp.", "nv": "Đức Trí"}, {"loi": "Mùa cuối của năm: mình ra Đài Quan Sát Trái Đất — khép năm và chia tay Trạm nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Lá Chắn Vàng", "tomTatTapTruoc": "Biệt đội đã khôi phục ba trang Sổ Tay của mùa Lá Chắn Tuổi Dậy Thì: chăm sóc sức khoẻ dậy thì, phòng tránh xâm hại và sơ đồ tổng ôn cả chủ đề. Giờ đây Sương Mù Quên Lãng dồn hết sương của mùa giữ Cổng Lá Chắn Vàng trên khu vườn...", "tuan": "28", "vatPham": "Lá Chắn Tuổi Dậy Thì"}], "tenMua": "Mùa 10 — Lá Chắn Tuổi Dậy Thì", "tomTatMua": "Sau Sảnh Lớn Lên Từng Ngày, Biệt đội Ánh Sao vào khu vườn yên tĩnh của Trạm — nơi dựng Lá Chắn Tuổi Dậy Thì. Cả đội học cách chăm sóc sức khoẻ thể chất và tinh thần khi cơ thể thay đổi, lập danh sách người đáng tin cậy và nhận biết nguy cơ xâm hại để bảo vệ mình và bạn bè. Sương Mù làm mờ bảng hướng dẫn chăm sóc treo trong vườn; chỉ có hiểu đúng và bình tĩnh làm đúng, lá chắn ánh sáng mới dựng vững quanh mỗi bạn."}, {"anhBia": "cong-trai-dat-xanh", "anhCanTao": [{"khoa": "cong-trai-dat-xanh", "moTa": "Cổng Trái Đất Xanh khép năm: quả địa cầu lớn xanh tươi đặt giữa cổng vòm phủ dây leo và hoa, Biệt đội Ánh Sao áo trắng khăn quàng đỏ cùng Robot Hạt Đậu (robot nhỏ thân hình hạt đậu, xanh ngọc lục bảo và trắng phòng thí nghiệm) đứng trước cổng vẫy tay chia tay Trạm, vali và Sổ Tay Thí Nghiệm đặt cạnh; bầu trời trong, sương xám rút xa ở chân trời phía sau. Phong cách 3D Pixar, không chữ."}], "beCum": {"cacBai": ["28", "29", "30"], "moTa": "Cơ chế BỂ CHỦ ĐỀ (Khoa học lớp 5): tập Ôn tập chủ đề Sinh vật và môi trường (Bài 30) rút mọi thử thách và câu cứu viện từ bể chung gồm tất cả câu trắc nghiệm có phương án của các bài 28, 29, 30 thuộc Chủ đề 6, lọc theo mucDo đã khai trong rutCau, không lặp trong cùng một tập. Trường rutCau.bai là bài của tập; trường rutCau.be là danh sách bài của bể."}, "cacBai": ["28", "29", "30"], "cacChuDe": ["6"], "id": "kh5-c11", "lop": 5, "mon": "Khoa học", "nhanVat": {"Minh Anh": "Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.", "Robot Hạt Đậu": "Robot Hạt Đậu — trợ lý thí nghiệm của Trạm Khám Phá Xanh, thân hình hạt đậu, hay tò mò, ghi chép mọi số liệu vào Sổ Tay Thí Nghiệm; là người dẫn đường của Biệt đội ở Trạm và đọc câu cứu viện trong thế giới Khoa học.", "Sương Mù": "Sương Mù Quên Lãng — thế lực xám lạnh chuyên làm mờ hiện tượng và nhòe sổ tay thí nghiệm trong các cuốn sách của Thư viện Ánh Sao.", "Thảo Nguyên": "Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.", "Thủ thư Số": "Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.", "Tuấn Kiệt": "Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.", "Đức Trí": "Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."}, "tap": [{"bai": "28", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Đài Quan Sát Trái Đất là trạm cuối cùng của Trạm Khám Phá Xanh. Sáng nay Sương Mù làm mờ tấm bản đồ ba chức năng của môi trường — chẳng ai còn nói đúng môi trường làm gì cho muôn loài nữa.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc nè: môi trường có ba chức năng cơ bản — cung cấp chỗ ở, thức ăn và những nhu cầu sống thiết yếu; là nơi chứa đựng chất thải của sinh vật; và bảo vệ sinh vật khỏi những tác động từ bên ngoài.", "nv": "Robot Hạt Đậu"}, {"loi": "Không khí, nước, ánh sáng, cỏ và chỗ ở — mọi thứ sinh vật cần để sống, lớn lên và sinh sản đều lấy từ môi trường.", "nv": "Thảo Nguyên"}, {"loi": "Rừng đầu nguồn giữ nước mưa cho nước thấm xuống đất — đó là chức năng bảo vệ. Còn phân và nước thải của động vật thải vào môi trường là nhờ chức năng chứa đựng chất thải.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, lên đài, làm rõ tấm bản đồ chức năng thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-chu", "dong": [{"loi": "Tấm bản đồ mờ thành hai nửa: nửa cung cấp cho sự sống và nửa chứa đựng — bảo vệ. Cả lớp làm rõ nửa nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-chu", "dong": [{"loi": "Nửa này soi vào giọt nước, hạt không khí và tia sáng — những nhu cầu sống thiết yếu. Chọn mẫu vật ghi đúng nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi soi vào những yếu tố môi trường quanh một cây non, hiện chức năng cung cấp của môi trường. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "28", "mucDo": [1], "soCau": 1}}], "nhan": "Làm rõ nửa Kính hiển vi — cung cấp cho sự sống"}, {"canh": [{"anh": "canh-kho", "dong": [{"loi": "Nửa này là các chậu cây có mái che và hàng rào chắn gió trong vườn thí nghiệm. Chọn chậu gắn thẻ đúng chức năng bảo vệ và chứa đựng nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày những chậu cây dưới mái che và bên luống đất thấm nước thải, chờ cả lớp nhận đúng chức năng của môi trường. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "28", "mucDo": [1], "soCau": 1}}], "nhan": "Làm rõ nửa Vườn thí nghiệm — chứa đựng và bảo vệ"}]}, {"anh": "cau-suong", "bienCo": {"dong": [{"loi": "Sương làm mình lẫn rồi: rừng giữ nước là chức năng cung cấp hay bảo vệ nhỉ!", "nv": "Tuấn Kiệt"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là bản đồ rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "28", "mucDo": [1], "soCau": 1}}, "danChuyen": "Bể quan sát hiện một khu rừng bên bờ suối và đàn bò trên đồng cỏ, chờ cả lớp gọi đúng chức năng của môi trường trong từng cảnh. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "28", "mucDo": [2], "soCau": 1}}, {"anh": "kho-sang", "danChuyen": "Cửa sổ bầu trời mở ra dãy rừng đầu nguồn xa xa, hiện câu hỏi khó nhất: nếu rừng biến mất, chức năng nào giảm rõ nhất và hệ quả là gì. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "28", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Tấm bản đồ rõ cả ba chức năng rồi! Hạt Đậu tặng biệt đội Chiếc Lá Chức Năng — cầm lá là nhớ môi trường nuôi sống muôn loài.", "nv": "Robot Hạt Đậu"}, {"loi": "Ngày mai mình nhìn lại bàn tay con người: có tác động làm hại môi trường, cũng có việc làm bảo vệ môi trường.", "nv": "Thảo Nguyên"}, {"loi": "Tập sau mình xem con người tác động tới môi trường thế nào nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t1", "ten": "Tập 1 — Môi Trường Nuôi Sống Muôn Loài", "tomTatTapTruoc": "Mùa trước: Biệt đội phá Cổng Lá Chắn Vàng, nhận Lá Chắn Tuổi Dậy Thì và khép trọn chủ đề Con người và sức khoẻ. Nay cả đội ra Đài Quan Sát Trái Đất — mùa cuối của năm — mà tấm bản đồ chức năng của môi trường treo ở đài đang bị sương làm mờ...", "tuan": "29–30", "vatPham": "Chiếc Lá Chức Năng"}, {"bai": "29", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Ở đài treo bức tranh hai bàn tay của con người với môi trường: một phía đốt rừng, xả rác; một phía trồng cây, tiết kiệm tài nguyên. Sáng nay Sương Mù làm lẫn hai phía của bức tranh — chẳng ai phân biệt được việc nào hại, việc nào lợi nữa.", "nv": "Người kể"}, {"loi": "Hạt Đậu nhắc nè: tài nguyên thiên nhiên là những gì thiên nhiên ban cho con người. Săn bắt, khai thác bừa bãi, đốt rừng là tác động tiêu cực; trồng cây, phân loại rác, tiết kiệm điện nước là tác động tích cực.", "nv": "Robot Hạt Đậu"}, {"loi": "Đốt rừng làm hại không khí và nơi sống của sinh vật. Còn em, em bảo vệ môi trường bằng việc chăm cây ở trường, ở nhà và vận động mọi người bằng tranh vẽ, sơ đồ.", "nv": "Thảo Nguyên"}, {"loi": "Gặp món ăn làm từ động vật hoang dã quý hiếm thì phải từ chối — đó là cách sống hoà hợp với thiên nhiên. Việc nhỏ mỗi ngày cũng góp phần bảo vệ hành tinh.", "nv": "Đức Trí"}, {"loi": "Đúng thế! Nào, tách lại hai phía của bức tranh thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-kho", "dong": [{"loi": "Bức tranh lẫn thành hai phía: phía tác động tiêu cực và phía việc làm bảo vệ. Cả lớp tách phía nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "canh-kho", "dong": [{"loi": "Phía này là các chậu cây bị đốt cháy và luống đất đầy rác trong vườn thí nghiệm. Chọn chậu gắn thẻ đúng tác động tiêu cực nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày những luống đất bị tàn phá và những cây non bị chặt phá, chờ cả lớp nhận đúng tác động tiêu cực của con người. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "29", "mucDo": [1], "soCau": 1}}], "nhan": "Tách phía Vườn thí nghiệm — tác động tiêu cực"}, {"canh": [{"anh": "cau-suong", "dong": [{"loi": "Phía này là bể quan sát với dòng nước trong và đàn cá khỏe sau khi được dọn rác. Chọn vị trí ghi đúng việc làm bảo vệ nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Bể quan sát hiện dòng nước trong veo và những việc làm thiết thực bảo vệ môi trường, chờ cả lớp chọn đúng. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "29", "mucDo": [1], "soCau": 1}}], "nhan": "Tách phía Bể quan sát — việc làm bảo vệ"}]}, {"anh": "kho-sang", "bienCo": {"dong": [{"loi": "Sương làm mình rối rồi: dùng tiết kiệm điện nước là tác động tích cực hay tiêu cực nhỉ!", "nv": "Thảo Nguyên"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là bức tranh tách rõ ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "29", "mucDo": [1], "soCau": 1}}, "danChuyen": "Cửa sổ bầu trời hiện những việc làm hằng ngày của con người với môi trường, chờ cả lớp phân loại đúng. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "29", "mucDo": [2], "soCau": 1}}, {"anh": "canh-chu", "danChuyen": "Kính hiển vi soi vào tình huống khó nhất: ứng xử khi được mời món ăn từ động vật hoang dã quý hiếm và chọn nhóm việc làm hoà hợp với thiên nhiên. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "29", "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Bức tranh tách rõ hai phía rồi! Hạt Đậu tặng biệt đội Đôi Găng Tay Trồng Cây — đeo vào là sẵn sàng trồng thêm một cây xanh.", "nv": "Robot Hạt Đậu"}, {"loi": "Ngày mai mình tổng ôn cả chủ đề Sinh vật và môi trường — trạm tổng ôn cuối cùng của năm.", "nv": "Đức Trí"}, {"loi": "Tập sau mình ghé Trạm Tổng Ôn Trái Đất nhé!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t2", "ten": "Tập 2 — Bàn Tay Người Với Môi Trường", "tomTatTapTruoc": "Tập trước: Biệt đội làm rõ ba chức năng của môi trường và nhận Chiếc Lá Chức Năng. Hôm nay bức tranh hai bàn tay — một làm hại, một bảo vệ môi trường — treo ở đài bị sương làm lẫn hai phía...", "tuan": "31–32", "vatPham": "Đôi Găng Tay Trồng Cây"}, {"bai": "30", "canh": [{"anh": "canh-dau", "dong": [{"loi": "Trạm Tổng Ôn Trái Đất nằm ngay dưới Cổng Trái Đất Xanh. Muốn khép năm, mỗi đội phải ghép đúng sơ đồ cả chủ đề: ba chức năng của môi trường, tác động của con người và những việc làm bảo vệ. Hôm nay sương làm lẫn hết các ô sơ đồ — cũng là lần lẫn sơ đồ cuối cùng ở Trạm.", "nv": "Người kể"}, {"loi": "Trạm này ôn cả ba bài của chủ đề Sinh vật và môi trường nhé. Hạt Đậu nhắc một ý mẫu: ba chức năng cơ bản của môi trường là cung cấp, chứa đựng chất thải và bảo vệ.", "nv": "Robot Hạt Đậu"}, {"loi": "Bí quyết là nhớ theo mạch chủ đề: môi trường nuôi sống → con người tác động hai chiều → việc làm bảo vệ. Đốt rơm rạ làm ô nhiễm không khí; ủ rơm làm phân bón thì hợp lí hơn nhiều.", "nv": "Thảo Nguyên"}, {"loi": "Ghép đúng hết các ô sơ đồ, trạm sẽ trao Sơ Đồ Chủ Đề Môi Trường — và Cổng Trái Đất Xanh sẽ mở ra phía sau.", "nv": "Đức Trí"}, {"loi": "Đúng rồi! Nào, vào trạm ghép những ô sơ đồ cuối của năm thôi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "cau-suong", "dong": [{"loi": "Các ô sơ đồ lẫn thành hai chồng: chồng chức năng của môi trường và chồng tác động — bảo vệ. Cả lớp ghép chồng nào trước?", "nv": "Minh Anh"}], "loai": "re-nhanh", "luaChon": [{"canh": [{"anh": "cau-suong", "dong": [{"loi": "Chồng này có những ô về ba chức năng của môi trường với sinh vật. Chọn vị trí ghi đúng nhé!", "nv": "Đức Trí"}], "loai": "thoai"}, {"anh": "cau-suong", "danChuyen": "Bể quan sát hiện những ô sơ đồ về chức năng của môi trường, chờ cả lớp ghép đúng. Bể quan sát trong veo của Trạm hiện rõ từng sinh vật và vật nổi chìm, mỗi vị trí trong bể mang một đáp án khác nhau. Cả lớp chọn vị trí ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "30", "be": ["28", "29", "30"], "mucDo": [1], "soCau": 1}}], "nhan": "Ghép chồng Bể quan sát — chức năng môi trường"}, {"canh": [{"anh": "kho-sang", "dong": [{"loi": "Chồng này có những ô về tác động của con người và việc làm bảo vệ môi trường. Chọn hiện tượng ghi đúng nhé!", "nv": "Thảo Nguyên"}], "loai": "thoai"}, {"anh": "kho-sang", "danChuyen": "Cửa sổ bầu trời hiện những ô sơ đồ về tác động hai chiều của con người và cách bảo vệ môi trường, chờ cả lớp ghép đúng. Cửa sổ bầu trời của Trạm mở ra khoảng trời rộng, những hiện tượng và chòm sao hiện lên kèm các đáp án khác nhau. Cả lớp chọn hiện tượng ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "30", "be": ["28", "29", "30"], "mucDo": [1], "soCau": 1}}], "nhan": "Ghép chồng Cửa sổ bầu trời — tác động và bảo vệ"}]}, {"anh": "canh-chu", "bienCo": {"dong": [{"loi": "Sương làm hai ô sơ đồ dính chặt vào nhau rồi, mình không tách được ô nào thuộc bài nào nữa!", "nv": "Minh Anh"}, {"loi": "Đừng lo! Hạt Đậu có câu cứu viện của Robot Hạt Đậu đây — trả lời đúng là hai ô tách ra rõ ràng ngay.", "nv": "Robot Hạt Đậu"}], "rutCauCuuVien": {"bai": "30", "be": ["28", "29", "30"], "mucDo": [1], "soCau": 1}}, "danChuyen": "Kính hiển vi soi vào những ô sơ đồ tổng hợp của cả chủ đề, chờ cả lớp gọi đúng. Kính hiển vi của Trạm phóng to cảnh vật trước mắt. Những mẫu vật đặt trên bàn kính mang các đáp án khác nhau. Cả lớp chọn mẫu vật ghi đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "30", "be": ["28", "29", "30"], "mucDo": [2], "soCau": 1}}, {"anh": "canh-kho", "danChuyen": "Vườn thí nghiệm bày ô sơ đồ khó nhất của trạm: nêu một việc hằng ngày em làm để bảo vệ môi trường và giải thích vì sao việc đó có lợi. Vườn thí nghiệm của Trạm bày những chậu cây và chai nước với điều kiện khác nhau, mỗi chậu gắn một thẻ ghi đáp án. Cả lớp chọn chậu cây gắn thẻ đáp án đúng nhé!", "loai": "thu-thach", "rutCau": {"bai": "30", "be": ["28", "29", "30"], "mucDo": [2, 3], "soCau": 1}}, {"anh": "sach-sang", "dong": [{"loi": "Mọi ô sơ đồ đã ghép đúng! Trạm Tổng Ôn trao biệt đội Sơ Đồ Chủ Đề Môi Trường — trọn chủ đề cuối của năm đã nằm gọn trong một sơ đồ!", "nv": "Robot Hạt Đậu"}, {"loi": "Nhìn lên kìa — Cổng Trái Đất Xanh đang chìm trong lớp sương dày nhất của cả năm cuối cấp...", "nv": "Tuấn Kiệt"}, {"loi": "Tập đặc biệt cuối cùng ở Trạm: phá Cổng Trái Đất Xanh và chia tay Trạm Khám Phá Xanh thôi, cả lớp!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "t3", "ten": "Tập 3 — Trạm Tổng Ôn Trái Đất", "tomTatTapTruoc": "Tập trước: Biệt đội tách rõ hai phía tác động của con người và nhận Đôi Găng Tay Trồng Cây. Trước ngày khép năm, cả đội ghé Trạm Tổng Ôn Trái Đất — trạm ôn cuối cùng của năm, cũng là của cả thời tiểu học ở Trạm...", "tuan": "32", "vatPham": "Sơ Đồ Chủ Đề Môi Trường"}, {"bai": "28+29+30", "canh": [{"anh": "canh-trum", "dong": [{"loi": "Khà... khà... Năm cuối cấp rồi đấy, những nhà khoa học nhí. Đất, điện, vi khuẩn, cơ thể, môi trường — các ngươi đi hết Trạm rồi. Nhưng Cổng Trái Đất Xanh này là của ta. Không có ánh sáng hiểu biết, lời chia tay của các ngươi sẽ chìm trong sương mãi mãi...", "nv": "Sương Mù"}, {"loi": "Biệt đội sẵn sàng! Ánh sáng của chúng mình là cả một năm quan sát, thí nghiệm và ghi chép đúng ở Trạm này. Hạt Đậu ơi, nhắc luật cổng cuối cùng nào!", "nv": "Minh Anh"}, {"loi": "Luật như cũ: bốn đòn luân phiên ba bài cuối năm. Mỗi câu đúng là một bánh răng của cỗ máy trung tâm sáng lên, phá khiên sương trước Cổng Trái Đất Xanh. Cố lên, các bạn ơi!", "nv": "Robot Hạt Đậu"}], "loai": "thoai"}, {"anh": "canh-trum", "danChuyen": "Cỗ máy trung tâm quay bánh răng đầu tiên: ba chức năng của môi trường đối với sinh vật. Cả lớp chọn chiêu thức đúng để bánh răng sáng lên nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "28", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Một bánh răng đã sáng! Đòn tiếp theo là bàn tay con người với môi trường: tác động hai chiều và việc làm bảo vệ. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "29", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Sương Mù tung những ô sơ đồ tổng ôn cuối năm vào khói. Cả lớp chọn chiêu thức đúng để ghép lại nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "30", "mucDo": [2, 3], "soCau": 1}}, {"anh": "canh-trum", "danChuyen": "Đòn cuối của năm quay lại tấm bản đồ chức năng của môi trường. Cả lớp chọn chiêu thức đúng để cổng bừng sáng, phá tan khiên sương nhé!", "laDonTrum": true, "loai": "thu-thach", "rutCau": {"bai": "28", "mucDo": [2, 3], "soCau": 1}}, {"anh": "cua-mo", "dong": [{"loi": "Thôi được... Cổng Trái Đất Xanh là của các ngươi. Ta rút về phía Thư viện Ánh Sao đây — ở Đêm Chung Kết của cả thư viện, ta sẽ trở lại với sương dày hơn gấp bội, chờ các ngươi ở cấp học mới...", "nv": "Sương Mù"}, {"loi": "Cổng mở rồi! Sổ Tay Thí Nghiệm đã khôi phục trọn vẹn cả năm. Hạt Đậu trao biệt đội Huy Hiệu Nhà Khoa Học Nhí — từ trang đất đầu tiên tới trang Trái Đất xanh cuối cùng, các bạn đã ghi lại tất cả bằng quan sát đúng.", "nv": "Robot Hạt Đậu"}, {"loi": "Một năm ở Trạm: sáu chủ đề, ba mươi bài — tất cả đã khôi phục sáng ngời bằng thí nghiệm và hiểu biết.", "nv": "Đức Trí"}, {"loi": "Tạm biệt Trạm Khám Phá Xanh, tạm biệt Hạt Đậu! Hẹn gặp lại ở Đêm Chung Kết của cả Thư viện Ánh Sao — và ở cấp học mới đang chờ phía trước. Lớp 5, khép năm thật đẹp!", "nv": "Minh Anh"}], "loai": "thoai"}], "id": "trum", "laTapTrum": true, "ten": "Tập đặc biệt — Cổng Trái Đất Xanh", "tomTatTapTruoc": "Biệt đội đã khôi phục ba trang Sổ Tay cuối của năm: chức năng của môi trường, tác động của con người và sơ đồ tổng ôn cả chủ đề Sinh vật và môi trường. Giờ đây, trước Cổng Trái Đất Xanh phủ dây leo và hoa, Sương Mù Quên Lãng dồn hết sương của năm cuối cấp giữ cổng khép năm của Trạm...", "tuan": "32", "vatPham": "Huy Hiệu Nhà Khoa Học Nhí"}], "tenMua": "Mùa 11 — Cổng Trái Đất Xanh", "tomTatMua": "Mùa cuối của năm — và của cả thời tiểu học ở Trạm Khám Phá Xanh — mở ra ở Đài Quan Sát Trái Đất. Biệt đội Ánh Sao tìm hiểu ba chức năng của môi trường đối với sinh vật, nhìn lại những tác động của con người lên môi trường và những việc làm bảo vệ hành tinh xanh. Khép mùa ở Cổng Trái Đất Xanh: cả đội trao lại Sổ Tay Thí Nghiệm đã khôi phục trọn vẹn cho Robot Hạt Đậu, nhận Huy hiệu Nhà Khoa Học Nhí và chia tay Trạm để bước sang cấp học mới — còn Sương Mù Quên Lãng hẹn gặp lại ở Đêm Chung Kết của cả Thư viện Ánh Sao."}], "cauHoi": {"bai": {"1": {"cauHoi": [{"cauHoi": "Thành phần chính của đất gồm những gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo SGK: chất khoáng, mùn, nước, không khí và một số thành phần khác.", "id": "KH5-B01-01", "mucDo": 1, "phuongAn": ["Chỉ có đá và rễ cây", "Chỉ có nước và không khí", "Chất khoáng, mùn, nước, không khí", "Chỉ có muối và đường"]}, {"cauHoi": "Thành phần nào chiếm tỉ lệ nhiều nhất trong đất?", "dang": "TN", "dapAn": 0, "giaiThich": "Chất khoáng chiếm tỉ lệ nhiều nhất trong đất.", "id": "KH5-B01-02", "mucDo": 1, "phuongAn": ["Chất khoáng", "Không khí", "Mùn", "Nước"]}, {"cauHoi": "Thả đất vào cốc nước, có bọt khí nổi lên. Thí nghiệm chứng tỏ trong đất có gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Bọt khí nổi lên chứng tỏ trong đất có không khí.", "id": "KH5-B01-03", "mucDo": 1, "phuongAn": ["Đường", "Không khí", "Sắt", "Muối ăn"]}, {"cauHoi": "Khi đun đất trong ống nghiệm, hơi nước thoát ra chứng tỏ trong đất có gì?", "dang": "TN", "dapAn": 3, "giaiThich": "Nước trong đất bay hơi khi đun nóng.", "id": "KH5-B01-04", "mucDo": 1, "phuongAn": ["Mùn", "Không khí", "Ánh sáng", "Nước"]}, {"cauHoi": "Rễ cây lấy những gì từ đất?", "dang": "TN", "dapAn": 0, "giaiThich": "Rễ lấy chất khoáng, mùn, nước và không khí từ đất.", "id": "KH5-B01-05", "mucDo": 1, "phuongAn": ["Chất dinh dưỡng, nước và không khí", "Chỉ lấy không khí", "Chỉ lấy nước", "Chỉ lấy ánh sáng"]}, {"cauHoi": "Ngoài việc cung cấp chất dinh dưỡng, nước và không khí, đất còn có vai trò nào đối với cây trồng?", "dang": "TN", "dapAn": 3, "giaiThich": "Đất là chỗ bám để cây đứng vững.", "id": "KH5-B01-06", "mucDo": 1, "phuongAn": ["Cung cấp ánh sáng", "Làm cây không cần nước", "Làm cây đổi màu", "Giúp cây đứng vững, không bị đổ"]}, {"cauHoi": "Chất dinh dưỡng trong đất gồm những thành phần nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Chất dinh dưỡng gồm chất khoáng và mùn.", "id": "KH5-B01-07", "mucDo": 2, "phuongAn": ["Chỉ có nước", "Chỉ có không khí", "Chất khoáng và mùn", "Chỉ có cát sỏi"]}, {"cauHoi": "Đất được hình thành chủ yếu như thế nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo thông tin SGK.", "id": "KH5-B01-08", "mucDo": 2, "phuongAn": ["Do chỉ có mưa rơi xuống", "Do đá bị phá vỡ sau một quá trình lâu dài dưới tác động của nhiệt, nước, không khí, gió, mưa", "Do cây trồng tự tạo ra", "Do người pha chế trong một ngày"]}, {"cauHoi": "Xới đất, vun gốc chủ yếu giúp thay đổi thành phần nào của đất?", "dang": "TN", "dapAn": 2, "giaiThich": "Xới đất làm đất tơi xốp, tăng không khí trong đất.", "id": "KH5-B01-09", "mucDo": 2, "phuongAn": ["Làm mất hết mùn", "Làm giảm hoàn toàn nước trong đất", "Không khí, làm đất tơi xốp hơn", "Làm đất bị mặn"]}, {"cauHoi": "Bón phân hữu cơ cho đất nhằm mục đích gì?", "dang": "TN", "dapAn": 0, "giaiThich": "Bón phân hữu cơ làm tăng chất dinh dưỡng cho đất.", "id": "KH5-B01-10", "mucDo": 2, "phuongAn": ["Tăng chất khoáng và mùn, cung cấp thêm dinh dưỡng cho cây", "Giảm không khí trong đất", "Làm đất bị chai cứng", "Làm đất bị ô nhiễm"]}, {"cauHoi": "Vì sao cần giữ đất tơi xốp khi trồng cây?", "dang": "TN", "dapAn": 1, "giaiThich": "Đất tơi xốp giúp rễ lấy đủ không khí, nước và dinh dưỡng.", "id": "KH5-B01-11", "mucDo": 3, "phuongAn": ["Để cây không cần ánh sáng", "Để rễ cây lấy được không khí, nước và chất dinh dưỡng", "Để đất nặng hơn, cây thấp đi", "Để đất không còn mùn"]}, {"cauHoi": "Việc làm nào giúp tăng vai trò của đất đối với cây trồng?", "dang": "TN", "dapAn": 3, "giaiThich": "Xới đất và bón phân hữu cơ giúp đất tơi xốp, giàu dinh dưỡng.", "id": "KH5-B01-12", "mucDo": 3, "phuongAn": ["Đổ rác thải chưa xử lí ra đất", "Tưới quá nhiều thuốc trừ sâu", "Để đất bị chai cứng", "Xới đất và bón phân hữu cơ"]}, {"cauHoi": "Nêu hai vai trò của đất đối với cây trồng.", "dang": "TL", "giaiThich": "Cung cấp chất dinh dưỡng (khoáng, mùn), nước, không khí; giúp cây đứng vững, không bị đổ.", "id": "KH5-B01-13", "mucDo": 3}], "chuDe": "1", "ten": "Thành phần và vai trò của đất đối với cây trồng", "tenChuDe": "Chủ đề 1. Chất", "tenGoc": "Bài 1. Thành phần và vai trò của đất đối với cây trồng", "tuan": "1", "yeuCauCanDat": ["Nêu được một số thành phần của đất.", "Trình bày được vai trò của đất đối với cây trồng."]}, "10": {"cauHoi": [{"cauHoi": "Nguồn năng lượng chất đốt có trong tự nhiên gồm", "dang": "TN", "dapAn": 2, "giaiThich": "Theo SGK.", "id": "KH5-B10-01", "mucDo": 1, "phuongAn": ["Chỉ có nước chảy", "Chỉ có điện", "Than, dầu mỏ, khí tự nhiên", "Chỉ có gió"]}, {"cauHoi": "Nguồn năng lượng chất đốt do con người tạo ra được nêu trong bài là", "dang": "TN", "dapAn": 0, "giaiThich": "Khí sinh học được tạo từ ủ chất hữu cơ.", "id": "KH5-B10-02", "mucDo": 1, "phuongAn": ["Khí sinh học", "Năng lượng nước chảy", "Năng lượng mặt trời", "Năng lượng gió"]}, {"cauHoi": "Khí sinh học được tạo ra từ đâu?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo SGK.", "id": "KH5-B10-03", "mucDo": 1, "phuongAn": ["Chưng cất nước suối", "Ủ các chất hữu cơ như mùn, rác, phân động vật trong bể chứa", "Khai thác dầu mỏ ngoài biển", "Khai thác than trong lòng đất"]}, {"cauHoi": "Than, dầu mỏ được dùng làm gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Vai trò của chất đốt.", "id": "KH5-B10-04", "mucDo": 1, "phuongAn": ["Chỉ để thắp đèn pin", "Làm chất đốt trong gia đình, nhà máy, luyện kim; chế xăng, dầu cho máy móc", "Chỉ để uống", "Chỉ để trồng cây"]}, {"cauHoi": "Vai trò của năng lượng chất đốt trong đời sống và sản xuất là", "dang": "TN", "dapAn": 3, "giaiThich": "Theo SGK.", "id": "KH5-B10-05", "mucDo": 1, "phuongAn": ["Thay hoàn toàn ánh sáng mặt trời cho cây", "Làm mát phòng như máy lạnh điện", "Chỉ dùng để trang trí", "Đun nấu, đun nước; chạy máy cày, ô tô, tàu hoả,... giúp tăng hiệu quả sản xuất, giảm sức lao động"]}, {"cauHoi": "Đun nấu bằng bếp than trong nhà có thể gây hại gì?", "dang": "TN", "dapAn": 0, "giaiThich": "Cần hạn chế, phòng chống ô nhiễm khi dùng chất đốt.", "id": "KH5-B10-06", "mucDo": 2, "phuongAn": ["Gây ô nhiễm môi trường, có thể nguy hiểm cho sức khoẻ", "Không sinh ra gì cả", "Chỉ tạo hơi nước sạch", "Làm không khí trong lành hơn"]}, {"cauHoi": "Biện pháp nào giúp phòng chống cháy, nổ khi dùng chất đốt?", "dang": "TN", "dapAn": 2, "giaiThich": "Biện pháp an toàn khi dùng chất đốt.", "id": "KH5-B10-07", "mucDo": 2, "phuongAn": ["Để bếp gas gần cửa ra vào và không kiểm tra", "Đun bếp khi vắng nhà, không người trông", "Sử dụng đúng quy định, không để rò rỉ khí, không đốt gần chất dễ cháy, khoá van khi không dùng", "Chứa xăng trong chai nhựa gần bếp lửa"]}, {"cauHoi": "Việc làm nào giúp tiết kiệm năng lượng chất đốt?", "dang": "TN", "dapAn": 2, "giaiThich": "Tiết kiệm chất đốt đã học.", "id": "KH5-B10-08", "mucDo": 2, "phuongAn": ["Để bếp cháy suốt ngày", "Dùng lửa lớn khi chỉ cần lửa nhỏ", "Đun nấu vừa đủ, khoá bếp khi không dùng, hạn chế đun bếp than không cần thiết", "Đun nước già nhiều lần khi không cần"]}, {"cauHoi": "Vì sao cần sử dụng tiết kiệm than, dầu mỏ, khí tự nhiên?", "dang": "TN", "dapAn": 1, "giaiThich": "SGV/SGK: chất đốt hoá thạch không vô tận. Không nêu địa danh cụ thể.", "id": "KH5-B10-09", "mucDo": 3, "phuongAn": ["Vì chúng không dùng được vào việc gì", "Vì chúng không phải là nguồn vô tận, được hình thành rất lâu", "Vì chúng không gây ô nhiễm", "Vì chúng được tạo ra thêm mỗi ngày rất nhiều"]}, {"cauHoi": "Em sẽ khuyên gia đình làm gì để vừa an toàn vừa giảm ô nhiễm khi đun nấu?", "dang": "TN", "dapAn": 3, "giaiThich": "Vận dụng biện pháp an toàn, tiết kiệm, giảm ô nhiễm.", "id": "KH5-B10-10", "mucDo": 3, "phuongAn": ["Để bếp gas mở khi đi vắng", "Đốt than trong phòng ngủ kín", "Đun bằng xăng trong nhà", "Dùng bếp đúng cách, khoá van khi không dùng; hạn chế bếp than, thông thoáng nhà bếp"]}, {"cauHoi": "Khí tự nhiên thường được dùng để", "dang": "TN", "dapAn": 0, "giaiThich": "Theo bài.", "id": "KH5-B10-11", "mucDo": 1, "phuongAn": ["Nấu ăn bằng bếp gas và đun trong một số lò", "Tưới cây", "Thả diều", "Phơi muối"]}, {"cauHoi": "Đun nấu vừa đủ, không để bếp cháy khi không cần là việc", "dang": "TN", "dapAn": 3, "giaiThich": "Việc làm tiết kiệm đã học.", "id": "KH5-B10-12", "mucDo": 1, "phuongAn": ["Làm tăng nguy cơ cháy", "Không liên quan chất đốt", "Làm than nhiều hơn", "Tiết kiệm năng lượng chất đốt"]}, {"cauHoi": "Máy cày, máy gặt, ôtô, xe máy chạy bằng xăng hoặc dầu đi-ê-den cho thấy vai trò nào của chất đốt?", "dang": "TN", "dapAn": 0, "giaiThich": "Vai trò trong đời sống và sản xuất.", "id": "KH5-B10-13", "mucDo": 2, "phuongAn": ["Giúp sản xuất và đi lại, giảm sức lao động", "Chỉ dùng để trồng cây không cần máy", "Chỉ dùng để thắp đèn pin", "Không có vai trò trong sản xuất"]}, {"cauHoi": "Nêu hai nguồn năng lượng chất đốt và hai biện pháp sử dụng an toàn, tiết kiệm.", "dang": "TL", "giaiThich": "Nguồn: than, dầu mỏ, khí tự nhiên, khí sinh học. An toàn, tiết kiệm: khoá van khi không dùng, không để rò rỉ, hạn chế bếp than, đun vừa đủ, không đốt gần chất dễ cháy.", "id": "KH5-B10-14", "mucDo": 3}], "chuDe": "2", "ten": "Năng lượng chất đốt", "tenChuDe": "Chủ đề 2. Năng lượng", "tenGoc": "Bài 10. Năng lượng chất đốt", "tuan": "10", "yeuCauCanDat": ["Nêu được một số nguồn năng lượng chất đốt và vai trò của chúng trong đời sống và sản xuất.", "Trình bày được biện pháp phòng chống cháy, nổ, ô nhiễm khi sử dụng năng lượng chất đốt.", "Nêu và thực hiện được việc làm thiết thực để tiết kiệm năng lượng chất đốt."]}, "11": {"cauHoi": [{"cauHoi": "Con người dùng năng lượng mặt trời vào việc nào dưới đây?", "dang": "TN", "dapAn": 2, "giaiThich": "Ví dụ trong SGK.", "id": "KH5-B11-01", "mucDo": 1, "phuongAn": ["Chạy ô tô bằng xăng", "Đốt than trong lò", "Phơi muối, phơi thóc, làm nóng nước, sấy nông sản", "Khai thác dầu mỏ"]}, {"cauHoi": "Pin mặt trời dùng để làm gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo SGK.", "id": "KH5-B11-02", "mucDo": 1, "phuongAn": ["Tạo gió nhân tạo", "Biến đổi năng lượng mặt trời thành điện năng", "Bơm xăng", "Đốt cháy rác"]}, {"cauHoi": "Năng lượng gió được dùng cho hoạt động nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo bài.", "id": "KH5-B11-03", "mucDo": 1, "phuongAn": ["Đun nước bằng than", "Khai thác khí tự nhiên", "Sạc pin mặt trời vào ban đêm không có gió", "Làm quay tua-bin gió để phát điện, thả diều, đẩy thuyền buồm"]}, {"cauHoi": "Năng lượng nước chảy được dùng để", "dang": "TN", "dapAn": 0, "giaiThich": "Nước chảy quay tua-bin, máy phát điện.", "id": "KH5-B11-04", "mucDo": 1, "phuongAn": ["Làm quay tua-bin nhà máy thuỷ điện, chạy máy cơ đơn giản, cối nước", "Phơi muối", "Thắp đèn pin", "Đốt bếp gas"]}, {"cauHoi": "Ưu điểm của điện tạo ra từ năng lượng mặt trời, gió, nước chảy là", "dang": "TN", "dapAn": 2, "giaiThich": "Theo SGK.", "id": "KH5-B11-05", "mucDo": 1, "phuongAn": ["Làm tăng khí độc trong phòng", "Cần đốt than mới chạy được", "Không gây ô nhiễm không khí, tiết kiệm nhiên liệu dùng để sản xuất điện", "Luôn gây khói bụi như bếp than"]}, {"cauHoi": "Có thể dùng năng lượng mặt trời để sản xuất điện bằng cách nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Hai cách được nêu trong SGV/SGK.", "id": "KH5-B11-06", "mucDo": 2, "phuongAn": ["Chỉ cần để pin điện thoại ra nắng", "Dùng pin mặt trời hoặc dùng nhiệt mặt trời đun nước, hơi nước quay tua-bin", "Khuấy nước muối", "Đốt than rồi gọi là điện mặt trời"]}, {"cauHoi": "Vì sao năng lượng mặt trời, gió, nước chảy được coi là nguồn năng lượng sạch?", "dang": "TN", "dapAn": 1, "giaiThich": "Ưu điểm đã học.", "id": "KH5-B11-07", "mucDo": 2, "phuongAn": ["Vì chúng làm cạn kiệt than đá nhanh hơn", "Khi sử dụng không gây ô nhiễm không khí như đốt than, dầu", "Vì chúng tạo nhiều khói", "Vì chúng làm tăng rác thải nhựa"]}, {"cauHoi": "Nhà máy thuỷ điện hoạt động dựa trên nguồn năng lượng nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Tua-bin thuỷ điện quay nhờ nước chảy.", "id": "KH5-B11-08", "mucDo": 2, "phuongAn": ["Năng lượng gió trên mặt biển", "Năng lượng hoá học của đường", "Năng lượng nước chảy", "Năng lượng chất đốt"]}, {"cauHoi": "Ngày nắng, muốn đun nóng một chậu nước, nên ưu tiên nguồn nào vì an toàn và tiết kiệm?", "dang": "TN", "dapAn": 0, "giaiThich": "Bài ôn tập: mặt trời an toàn, tiết kiệm hơn chất đốt trong tình huống này.", "id": "KH5-B11-09", "mucDo": 3, "phuongAn": ["Năng lượng mặt trời", "Đốt than trong phòng kín", "Đốt xăng trực tiếp dưới chậu", "Dùng thật nhiều điện khi không cần"]}, {"cauHoi": "Nhà máy điện gió và thuyền buồm đều sử dụng nguồn năng lượng nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Cả hai đều dùng năng lượng gió.", "id": "KH5-B11-10", "mucDo": 2, "phuongAn": ["Năng lượng trong pin đèn", "Năng lượng chất đốt", "Năng lượng hoá học của đường", "Năng lượng gió"]}, {"cauHoi": "Kể mỗi nguồn (mặt trời, gió, nước chảy) một máy móc hoặc hoạt động sử dụng nguồn đó và nêu một ưu điểm chung.", "dang": "TL", "giaiThich": "Mặt trời: pin mặt trời, phơi thóc, đun nước. Gió: tuabin gió, thuyền buồm. Nước chảy: thuỷ điện, cối nước. Ưu điểm: ít ô nhiễm không khí, tiết kiệm nhiên liệu hoá thạch.", "id": "KH5-B11-11", "mucDo": 3}], "chuDe": "2", "ten": "Sử dụng năng lượng mặt trời, năng lượng gió, năng lượng nước chảy", "tenChuDe": "Chủ đề 2. Năng lượng", "tenGoc": "Bài 11. Sử dụng năng lượng mặt trời, năng lượng gió, năng lượng nước chảy", "tuan": "11–12", "yeuCauCanDat": ["Kể được tên một số phương tiện, máy móc và hoạt động của con người sử dụng năng lượng mặt trời, gió và nước chảy.", "Thu thập, xử lí thông tin và trình bày được về việc khai thác, sử dụng các dạng năng lượng nêu trên."]}, "12": {"cauHoi": [{"cauHoi": "Nguồn năng lượng thông dụng đã học gồm", "dang": "TN", "dapAn": 3, "giaiThich": "Ôn tập nguồn năng lượng.", "id": "KH5-B12-01", "mucDo": 1, "phuongAn": ["Chỉ có pin", "Chỉ có than", "Chỉ có sức người", "Mặt trời, gió, nước chảy, chất đốt và điện"]}, {"cauHoi": "Mạch điện thắp sáng đơn giản cần có", "dang": "TN", "dapAn": 2, "giaiThich": "Ôn tập mạch điện.", "id": "KH5-B12-02", "mucDo": 1, "phuongAn": ["Chỉ bóng đèn", "Chỉ dây dẫn", "Nguồn điện, công tắc, bóng đèn và dây dẫn", "Chỉ công tắc"]}, {"cauHoi": "Sấy tóc khi đứng trên sàn nhà tắm ướt có thể gây hậu quả gì? Nên làm thế nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Tình huống ôn tập SGK/SGV.", "id": "KH5-B12-03", "mucDo": 2, "phuongAn": ["Không sao; cứ sấy bình thường", "Có thể bị điện giật; nên đứng nơi khô hoặc đi dép cách điện, không sấy tóc trong nhà tắm ướt", "Chỉ làm tóc đẹp hơn", "Làm tiết kiệm điện"]}, {"cauHoi": "Thay bóng đèn khi vẫn còn cắm điện có thể bị điện giật. Cách làm đúng là", "dang": "TN", "dapAn": 0, "giaiThich": "An toàn điện đã học.", "id": "KH5-B12-04", "mucDo": 2, "phuongAn": ["Rút phích cắm khỏi ổ điện trước khi thay bóng", "Đứng chân trần trên nền ướt để thay", "Dùng tay ướt vặn bóng", "Thay thật nhanh khi vẫn cắm điện"]}, {"cauHoi": "Vật nào khi lắp vào mạch thử sẽ làm đèn sáng?", "dang": "TN", "dapAn": 0, "giaiThich": "Ôn tập vật dẫn điện, cách điện.", "id": "KH5-B12-05", "mucDo": 2, "phuongAn": ["Kim loại dẫn điện", "Gỗ khô", "Nhựa cách điện", "Cao su khô"]}, {"cauHoi": "Muốn làm một chậu nước nóng lên, có thể dùng những nguồn nào? Nguồn nào an toàn, tiết kiệm hơn vào ngày nắng?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo bài tập ôn tập chủ đề.", "id": "KH5-B12-06", "mucDo": 3, "phuongAn": ["Chỉ có thể dùng than trong phòng kín", "Không nguồn nào dùng được", "Có thể dùng mặt trời, chất đốt hoặc điện; ngày nắng nên dùng năng lượng mặt trời", "Chỉ có gió mới làm nước nóng"]}, {"cauHoi": "Hãy chọn việc làm thể hiện vừa an toàn điện vừa tiết kiệm năng lượng.", "dang": "TN", "dapAn": 1, "giaiThich": "Vận dụng cả chủ đề Năng lượng.", "id": "KH5-B12-07", "mucDo": 3, "phuongAn": ["Đốt than trong phòng kín và sạc điện thoại trên giường ướt", "Tắt đèn khi ra khỏi phòng, không dùng điện thoại khi đang sạc, hạn chế bếp than", "Nắm dây điện để rút phích", "Để đèn sáng cả đêm, sửa điện khi tay ướt"]}, {"cauHoi": "Lập sơ đồ miệng: kể các nguồn năng lượng đã học và với mỗi nguồn một lưu ý an toàn hoặc tiết kiệm.", "dang": "TL", "giaiThich": "Mặt trời, gió, nước chảy: ưu tiên vì sạch. Chất đốt: phòng cháy, nổ, ô nhiễm, dùng tiết kiệm. Điện: tắt khi không dùng, không sửa khi ẩm, rút phích trước khi sửa chữa.", "id": "KH5-B12-08", "mucDo": 3}], "chuDe": "2", "ten": "Ôn tập chủ đề Năng lượng", "tenChuDe": "Chủ đề 2. Năng lượng", "tenGoc": "Bài 12. Ôn tập chủ đề Năng lượng", "tuan": "12", "yeuCauCanDat": ["Tóm tắt được những nội dung chính đã học dưới dạng sơ đồ.", "Vận dụng được kiến thức và kĩ năng của chủ đề vào giải quyết một số tình huống đơn giản trong cuộc sống."]}, "13": {"cauHoi": [{"cauHoi": "Cơ quan sinh sản của thực vật có hoa là gì?", "dang": "TN", "dapAn": 3, "giaiThich": "Hoa là cơ quan sinh sản của thực vật có hoa.", "id": "KH5-B13-01", "mucDo": 1, "phuongAn": ["Thân gỗ", "Lá bánh tẻ", "Rễ", "Hoa"]}, {"cauHoi": "Các bộ phận của hoa gồm", "dang": "TN", "dapAn": 2, "giaiThich": "Theo SGK.", "id": "KH5-B13-02", "mucDo": 1, "phuongAn": ["Chỉ có lá và cành", "Chỉ có rễ và thân", "Đài, cánh, nhị, nhuỵ", "Chỉ có hạt và quả"]}, {"cauHoi": "Nhị hoa gồm những phần nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Nhị: chỉ nhị và bao phấn.", "id": "KH5-B13-03", "mucDo": 1, "phuongAn": ["Chỉ có cánh hoa", "Đầu nhuỵ, vòi nhuỵ, bầu nhuỵ", "Chỉ có đài hoa", "Chỉ nhị và bao phấn, bao phấn mang hạt phấn"]}, {"cauHoi": "Nhuỵ hoa gồm những phần nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Nhuỵ: đầu, vòi, bầu; bầu chứa noãn.", "id": "KH5-B13-04", "mucDo": 1, "phuongAn": ["Đầu nhuỵ, vòi nhuỵ, bầu nhuỵ; trong bầu nhuỵ chứa noãn", "Chỉ có đài hoa", "Chỉ nhị và bao phấn", "Chỉ có cuống lá"]}, {"cauHoi": "Hoa lưỡng tính là hoa", "dang": "TN", "dapAn": 1, "giaiThich": "Định nghĩa SGK.", "id": "KH5-B13-05", "mucDo": 1, "phuongAn": ["Chỉ có nhị", "Có cả nhị và nhuỵ trên cùng một hoa", "Chỉ có nhuỵ", "Không có nhị, không có nhuỵ"]}, {"cauHoi": "Hoa đơn tính là hoa", "dang": "TN", "dapAn": 0, "giaiThich": "Định nghĩa SGK.", "id": "KH5-B13-06", "mucDo": 1, "phuongAn": ["Chỉ có nhị hoặc chỉ có nhuỵ", "Chỉ có đài, không có cánh", "Có cả nhị và nhuỵ trên cùng một hoa", "Không phải là hoa"]}, {"cauHoi": "Hoa bưởi và hoa bí ngô: hoa nào là hoa lưỡng tính, hoa nào là hoa đơn tính?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo hình và thông tin SGK.", "id": "KH5-B13-07", "mucDo": 1, "phuongAn": ["Cả hai đều là hoa đơn tính", "Hoa bưởi đơn tính, hoa bí ngô lưỡng tính", "Hoa bưởi là hoa lưỡng tính, hoa bí ngô là hoa đơn tính", "Cả hai đều là hoa lưỡng tính"]}, {"cauHoi": "Vai trò của nhị trong quá trình thụ phấn, thụ tinh là gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Nhị mang hạt phấn.", "id": "KH5-B13-08", "mucDo": 2, "phuongAn": ["Cánh hoa tạo noãn", "Bao phấn chứa hạt phấn (tế bào sinh dục đực) tham gia thụ phấn", "Đài hoa tạo hạt", "Nhuỵ tạo quả ngay không cần hạt phấn"]}, {"cauHoi": "Vai trò của nhuỵ trong quá trình thụ phấn, thụ tinh, tạo hạt và quả là gì?", "dang": "TN", "dapAn": 3, "giaiThich": "Nhuỵ chứa noãn, sau thụ tinh tạo hạt và quả.", "id": "KH5-B13-09", "mucDo": 2, "phuongAn": ["Cánh hoa rụng thành rễ", "Đài hoa nở thành hạt", "Nhị tự tạo quả", "Noãn trong bầu nhuỵ kết hợp với tế bào sinh dục đực sau thụ phấn, thụ tinh để tạo hạt, quả"]}, {"cauHoi": "Nếu hoa không được thụ phấn, thụ tinh thì điều gì xảy ra?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo hình so sánh hoa được và không được thụ phấn, thụ tinh.", "id": "KH5-B13-10", "mucDo": 2, "phuongAn": ["Không tạo được hạt và quả bình thường", "Cây chết ngay lập tức", "Hoa biến thành rễ", "Vẫn luôn tạo nhiều hạt"]}, {"cauHoi": "Vì sao nhiều hoa có màu sắc, mật ngọt, mùi hương?", "dang": "TN", "dapAn": 3, "giaiThich": "Thông tin SGK về vai trò côn trùng đối với thụ phấn.", "id": "KH5-B13-11", "mucDo": 2, "phuongAn": ["Để cây khỏi cần nước", "Để đất thêm mùn", "Để rễ mọc nhanh hơn", "Để hấp dẫn côn trùng như ong, bướm, giúp mang hạt phấn, hỗ trợ thụ phấn"]}, {"cauHoi": "Câu hỏi nào giúp tìm hiểu sự sinh sản của cây có hoa?", "dang": "TN", "dapAn": 2, "giaiThich": "YCCĐ: đặt câu hỏi về sự sinh sản của thực vật có hoa.", "id": "KH5-B13-12", "mucDo": 3, "phuongAn": ["Lá có màu gì vào ban đêm?", "Cây cao bao nhiêu mét so với nhà?", "Cơ quan sinh sản của cây gồm những bộ phận nào? Quả và hạt được hình thành như thế nào?", "Rễ cây có ngọt không?"]}, {"cauHoi": "Nêu sự khác nhau giữa hoa đơn tính và hoa lưỡng tính; lấy một ví dụ mỗi loại theo SGK.", "dang": "TL", "giaiThich": "Hoa lưỡng tính có cả nhị và nhuỵ (ví dụ hoa bưởi). Hoa đơn tính chỉ có nhị hoặc chỉ có nhuỵ (ví dụ hoa bí ngô đực, hoa bí ngô cái).", "id": "KH5-B13-13", "mucDo": 3}], "chuDe": "3", "ten": "Sinh sản của thực vật có hoa", "tenChuDe": "Chủ đề 3. Thực vật và động vật", "tenGoc": "Bài 13. Sinh sản của thực vật có hoa", "tuan": "13", "yeuCauCanDat": ["Xác định được cơ quan sinh sản của thực vật có hoa; phân biệt được hoa đơn tính và hoa lưỡng tính.", "Vẽ sơ đồ hoặc sử dụng sơ đồ đã cho, ghi chú được tên các bộ phận của hoa.", "Dựa trên sơ đồ nêu được vai trò của nhị và nhuỵ trong quá trình thụ phấn, thụ tinh, tạo hạt và quả.", "Đặt được câu hỏi về sự sinh sản của thực vật có hoa."]}, "14": {"cauHoi": [{"cauHoi": "Hạt gồm những bộ phận chính nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo SGK/SGV.", "id": "KH5-B14-01", "mucDo": 1, "phuongAn": ["Chỉ có đất", "Vỏ hạt, phôi (mầm cây) và chất dinh dưỡng dự trữ", "Chỉ có vỏ cứng", "Chỉ có nước"]}, {"cauHoi": "Khi gặp điều kiện thuận lợi, hạt nảy mầm theo thứ tự nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo thông tin bài học.", "id": "KH5-B14-02", "mucDo": 1, "phuongAn": ["Lá xuất hiện trước, rễ mọc sau cùng", "Hạt hút nước phình to, rễ mầm mọc ra, thân mầm nhô lên, lá mới phát triển", "Hoa nở trước khi có rễ", "Thân gỗ già xuất hiện trước"]}, {"cauHoi": "Điều kiện thuận lợi để hạt nảy mầm gồm", "dang": "TN", "dapAn": 0, "giaiThich": "Đủ nước, không khí, nhiệt độ thích hợp.", "id": "KH5-B14-03", "mucDo": 1, "phuongAn": ["Đủ nước, không khí và nhiệt độ thích hợp", "Chỉ cần tối hoàn toàn, không cần nước", "Không cần gì cả", "Chỉ cần muối"]}, {"cauHoi": "Cây con có thể mọc lên từ những bộ phận nào của cây mẹ?", "dang": "TN", "dapAn": 2, "giaiThich": "YCCĐ và nội dung bài.", "id": "KH5-B14-04", "mucDo": 1, "phuongAn": ["Chỉ từ hoa đã héo", "Chỉ từ đất không có cây", "Thân (cành), rễ hoặc lá của một số loài", "Chỉ từ ánh sáng"]}, {"cauHoi": "Ví dụ cây con mọc từ thân, cành là", "dang": "TN", "dapAn": 3, "giaiThich": "SGV nêu rau muống, sắn,...", "id": "KH5-B14-05", "mucDo": 1, "phuongAn": ["Đậu mọc từ hạt", "Ngô mọc từ hạt", "Lúa mọc từ hạt", "Rau muống, sắn (khoai mì)"]}, {"cauHoi": "Ví dụ cây con có thể mọc từ lá là", "dang": "TN", "dapAn": 0, "giaiThich": "Theo thông tin bài/SGV.", "id": "KH5-B14-06", "mucDo": 1, "phuongAn": ["Cây sống đời, cây lưỡi hổ, cây sen đá", "Đậu xanh", "Lúa", "Ngô"]}, {"cauHoi": "Lúc mới nảy mầm, cây con lấy chất dinh dưỡng từ đâu?", "dang": "TN", "dapAn": 3, "giaiThich": "Phôi dùng chất dự trữ trong hạt.", "id": "KH5-B14-07", "mucDo": 2, "phuongAn": ["Từ hoa của cây mẹ", "Từ quả đã chín trên cây khác", "Từ điện trong đất", "Từ chất dinh dưỡng dự trữ trong hạt"]}, {"cauHoi": "Cây con bắt đầu tự tạo chất dinh dưỡng khi nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Khi có lá, cây tự tạo dinh dưỡng.", "id": "KH5-B14-08", "mucDo": 2, "phuongAn": ["Ngay khi hạt còn khô, chưa hút nước", "Trước khi rễ mầm xuất hiện", "Khi lá mới đã phát triển, lá mầm teo dần", "Khi cây đã ra hoa"]}, {"cauHoi": "Chất dinh dưỡng dự trữ của hạt ngô, hạt lúa thường chứa ở đâu?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo thông tin bổ sung phù hợp bài (nội nhũ).", "id": "KH5-B14-09", "mucDo": 2, "phuongAn": ["Ở rễ cây mẹ", "Trong nội nhũ", "Ở đài hoa", "Ở cánh hoa"]}, {"cauHoi": "Vì sao khi trồng cây bằng hạt cần giữ đất ẩm, thoáng, không quá lạnh hay quá nóng?", "dang": "TN", "dapAn": 1, "giaiThich": "Vận dụng điều kiện nảy mầm.", "id": "KH5-B14-10", "mucDo": 3, "phuongAn": ["Vì hạt không cần nước", "Vì hạt cần đủ nước, không khí và nhiệt độ thích hợp để nảy mầm", "Vì hạt nảy mầm tốt nhất khi bị ngập úng hoàn toàn", "Vì hạt chỉ cần ánh sáng mạnh suốt ngày"]}, {"cauHoi": "Em muốn có thêm cây rau muống. Nên trồng bằng cách nào đã học?", "dang": "TN", "dapAn": 3, "giaiThich": "Rau muống mọc từ thân, cành.", "id": "KH5-B14-11", "mucDo": 3, "phuongAn": ["Chỉ có thể trồng bằng hạt ngô", "Ngâm trong dầu ăn", "Ươp lạnh hạt lúa", "Trồng bằng đoạn thân (cành)"]}, {"cauHoi": "Cây sắn (khoai mì) thường được trồng bằng", "dang": "TN", "dapAn": 0, "giaiThich": "Ví dụ trồng bằng thân.", "id": "KH5-B14-12", "mucDo": 1, "phuongAn": ["Đoạn thân (cành)", "Chỉ bằng lá lúa", "Chỉ bằng hạt ngô", "Chỉ bằng đá"]}, {"cauHoi": "Bộ phận nào của hạt sẽ phát triển thành cây con?", "dang": "TN", "dapAn": 2, "giaiThich": "Phôi là mầm cây.", "id": "KH5-B14-13", "mucDo": 1, "phuongAn": ["Chỉ có đất dính ngoài vỏ", "Cánh hoa", "Phôi (mầm cây)", "Chỉ có vỏ hạt"]}, {"cauHoi": "Cây lưỡi hổ, cây sống đời có thể mọc cây con từ", "dang": "TN", "dapAn": 0, "giaiThich": "Ví dụ cây con mọc từ lá.", "id": "KH5-B14-14", "mucDo": 2, "phuongAn": ["Lá", "Chỉ từ hạt lúa", "Chỉ từ dầu ăn", "Chỉ từ đá"]}, {"cauHoi": "Nêu các giai đoạn chính khi cây con mọc lên từ hạt.", "dang": "TL", "giaiThich": "Hạt hút nước, nảy mầm; rễ mầm mọc xuống đất; thân mầm nhô lên; lá mới phát triển, cây con lớn dần và tự tạo chất dinh dưỡng.", "id": "KH5-B14-15", "mucDo": 3}], "chuDe": "3", "ten": "Sự phát triển của cây con", "tenChuDe": "Chủ đề 3. Thực vật và động vật", "tenGoc": "Bài 14. Sự phát triển của cây con", "tuan": "14–15", "yeuCauCanDat": ["Vẽ sơ đồ hoặc sử dụng sơ đồ đã cho, ghi chú được tên các bộ phận của hạt.", "Sử dụng sơ đồ đã cho, ghi chú được tên một số giai đoạn phát triển chính của cây con mọc lên từ hạt và cây con mọc lên từ một số bộ phận của cây mẹ; trình bày được sự lớn lên của cây con.", "Nêu được ví dụ về cây con mọc ra từ thân, rễ, lá của một số thực vật có hoa.", "Thực hành: Trồng cây bằng hạt và trồng cây bằng thân (hoặc lá, rễ)."]}, "15": {"cauHoi": [{"cauHoi": "Động vật nào dưới đây đẻ trứng?", "dang": "TN", "dapAn": 1, "giaiThich": "Ví dụ SGK: ốc sên, bướm, chim bồ câu,...", "id": "KH5-B15-01", "mucDo": 1, "phuongAn": ["Mèo, chó", "Ốc sên, bướm, chim bồ câu, ếch, gà, vịt", "Người", "Lợn, bò, dê, ngựa"]}, {"cauHoi": "Động vật nào dưới đây đẻ con?", "dang": "TN", "dapAn": 2, "giaiThich": "Ví dụ SGK.", "id": "KH5-B15-02", "mucDo": 1, "phuongAn": ["Gà, vịt", "Bướm, muỗi", "Lợn, bò, dê, ngựa, hổ", "Ếch, cóc"]}, {"cauHoi": "Động vật thường sinh sản khi nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Cơ quan sinh dục của con trưởng thành tạo trứng, tinh trùng.", "id": "KH5-B15-03", "mucDo": 1, "phuongAn": ["Khi vừa mới nở hoặc mới sinh", "Khi chưa có cơ quan sinh dục", "Khi còn là trứng", "Khi đã trưởng thành"]}, {"cauHoi": "Ở bò, thụ tinh xảy ra ở đâu?", "dang": "TN", "dapAn": 1, "giaiThich": "Đại diện động vật đẻ con.", "id": "KH5-B15-04", "mucDo": 1, "phuongAn": ["Trên lá cây", "Bên trong cơ thể con cái, qua giao phối", "Ở ngoài nước như một số cá", "Trong tổ chim"]}, {"cauHoi": "Ở một số cá, khi cá cái đẻ trứng, cá đực tưới tinh trùng. Thụ tinh xảy ra ở đâu?", "dang": "TN", "dapAn": 2, "giaiThich": "Hình thức thụ tinh ngoài, đại diện động vật đẻ trứng.", "id": "KH5-B15-05", "mucDo": 1, "phuongAn": ["Trong trứng đã nở thành cá con", "Chỉ trong tử cung", "Bên ngoài, trong nước", "Trên cạn, trong không khí"]}, {"cauHoi": "Sau thụ tinh, trứng và tinh trùng kết hợp tạo thành gì?", "dang": "TN", "dapAn": 0, "giaiThich": "Hợp tử phát triển thành phôi.", "id": "KH5-B15-06", "mucDo": 2, "phuongAn": ["Hợp tử", "Lá mầm", "Chỉ là sữa mẹ", "Chỉ là vỏ trứng"]}, {"cauHoi": "Điểm khác nhau thường thấy về số lượng con, trứng mỗi lần sinh sản là", "dang": "TN", "dapAn": 3, "giaiThich": "SGV nhấn mạnh sự khác biệt về số lượng.", "id": "KH5-B15-07", "mucDo": 2, "phuongAn": ["Động vật đẻ trứng luôn chỉ đẻ một trứng", "Không có khác biệt nào", "Động vật đẻ con luôn đẻ hàng trăm con mỗi lần", "Nhiều động vật đẻ trứng đẻ số lượng lớn; động vật đẻ con thường đẻ ít hơn mỗi lứa"]}, {"cauHoi": "Vịt mẹ ấp trứng, trâu mẹ mang thai rồi đẻ nghé. Đây là hai hình thức", "dang": "TN", "dapAn": 2, "giaiThich": "Tình huống mở đầu bài.", "id": "KH5-B15-08", "mucDo": 2, "phuongAn": ["Cả hai đều đẻ trứng trên cạn", "Cả hai đều đẻ con dưới nước", "Đẻ trứng và đẻ con", "Không phải sinh sản"]}, {"cauHoi": "Câu hỏi nào giúp tìm hiểu sự sinh sản của động vật?", "dang": "TN", "dapAn": 0, "giaiThich": "YCCĐ: đặt câu hỏi về sinh sản động vật.", "id": "KH5-B15-09", "mucDo": 3, "phuongAn": ["Động vật này đẻ trứng hay đẻ con? Thụ tinh xảy ra ở đâu?", "Nó chạy nhanh hay chậm hơn ôtô?", "Con vật này thích màu gì?", "Nó nặng bao nhiêu tấn so với tàu lửa?"]}, {"cauHoi": "Vì sao không thể xếp muỗi vào nhóm động vật đẻ con?", "dang": "TN", "dapAn": 1, "giaiThich": "Muỗi thuộc động vật đẻ trứng (thụ tinh trong cơ thể con cái, vẫn đẻ trứng).", "id": "KH5-B15-10", "mucDo": 3, "phuongAn": ["Vì muỗi không sinh sản", "Vì muỗi đẻ trứng", "Vì muỗi đẻ con và nuôi bằng sữa", "Vì muỗi là thực vật"]}, {"cauHoi": "Chim bồ câu thuộc nhóm động vật", "dang": "TN", "dapAn": 3, "giaiThich": "Ví dụ trong SGK.", "id": "KH5-B15-11", "mucDo": 1, "phuongAn": ["Sinh sản bằng hạt", "Đẻ con và nuôi bằng sữa", "Không sinh sản", "Đẻ trứng"]}, {"cauHoi": "Dê, ngựa thuộc nhóm động vật", "dang": "TN", "dapAn": 3, "giaiThich": "Ví dụ trong SGK.", "id": "KH5-B15-12", "mucDo": 1, "phuongAn": ["Không có hợp tử", "Sinh sản bằng hoa", "Đẻ trứng như gà", "Đẻ con"]}, {"cauHoi": "Ở bò, sau thụ tinh, hợp tử phát triển thành phôi, phôi phát triển thành thai ở đâu?", "dang": "TN", "dapAn": 0, "giaiThich": "Đặc điểm động vật đẻ con.", "id": "KH5-B15-13", "mucDo": 2, "phuongAn": ["Trong cơ thể con cái", "Trong tổ chim", "Trong nước như trứng cá thụ tinh ngoài", "Trên lá cây"]}, {"cauHoi": "Kể ba động vật đẻ trứng và ba động vật đẻ con; nêu một điểm khác về hình thức sinh sản của hai nhóm.", "dang": "TL", "giaiThich": "Đẻ trứng: gà, vịt, ếch, bướm, ốc, chim,... Đẻ con: lợn, bò, dê, ngựa, mèo, chó,... Đẻ trứng: hợp tử thường phát triển trong trứng ngoài cơ thể mẹ; đẻ con: phôi, thai phát triển trong cơ thể mẹ.", "id": "KH5-B15-14", "mucDo": 3}], "chuDe": "3", "ten": "Sinh sản của động vật", "tenChuDe": "Chủ đề 3. Thực vật và động vật", "tenGoc": "Bài 15. Sinh sản của động vật", "tuan": "15–16", "yeuCauCanDat": ["Nêu được tên một số động vật đẻ trứng, đẻ con và các hình thức sinh sản của chúng qua quan sát tranh ảnh.", "Đặt được câu hỏi về sự sinh sản của động vật."]}, "16": {"cauHoi": [{"cauHoi": "Vòng đời của muỗi gồm những giai đoạn nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Bốn giai đoạn: trứng, ấu trùng, nhộng, trưởng thành.", "id": "KH5-B16-01", "mucDo": 1, "phuongAn": ["Trứng, thú con, thú mẹ", "Trứng, ấu trùng, nhộng, muỗi trưởng thành", "Chỉ có trứng và muỗi trưởng thành", "Chỉ có con non và thú mẹ"]}, {"cauHoi": "Ấu trùng nở từ trứng muỗi còn được gọi là gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo SGK/SGV.", "id": "KH5-B16-02", "mucDo": 1, "phuongAn": ["Muỗi trưởng thành", "Nhộng muỗi", "Bọ gậy (con lăng quăng)", "Trứng gà"]}, {"cauHoi": "Vòng đời của bướm gồm những giai đoạn nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Bướm cái đẻ trứng trên lá, trứng nở thành ấu trùng,...", "id": "KH5-B16-03", "mucDo": 1, "phuongAn": ["Trứng, nhộng, bỏ qua ấu trùng", "Trứng, ấu trùng (sâu), nhộng, bướm trưởng thành", "Con non bú sữa mẹ", "Chỉ có bướm lớn"]}, {"cauHoi": "Một số động vật đẻ trứng như gián, châu chấu có vòng đời gồm", "dang": "TN", "dapAn": 3, "giaiThich": "Ba giai đoạn, không qua nhộng.", "id": "KH5-B16-04", "mucDo": 1, "phuongAn": ["Chỉ có nhộng", "Chỉ có trứng", "Bốn giai đoạn như bướm", "Trứng, ấu trùng và con trưởng thành"]}, {"cauHoi": "Vòng đời của động vật đẻ con như bò, chó, mèo, lợn trải qua", "dang": "TN", "dapAn": 2, "giaiThich": "Đặc điểm động vật đẻ con: mang thai, đẻ con, nuôi con bằng sữa.", "id": "KH5-B16-05", "mucDo": 1, "phuongAn": ["Chỉ có trứng và ấu trùng", "Trứng, ấu trùng, nhộng, trưởng thành", "Con non và con trưởng thành (con non được sinh ra từ mẹ, nuôi bằng sữa)", "Chỉ có nhộng"]}, {"cauHoi": "Ấu trùng muỗi sống ở đâu, khác muỗi trưởng thành như thế nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Ấu trùng (bọ gậy) sống dưới nước.", "id": "KH5-B16-06", "mucDo": 2, "phuongAn": ["Sống trong nước, hình dạng và môi trường sống khác muỗi trưởng thành", "Sống trong sữa mẹ", "Sống trong tổ chim", "Sống trên cạn như muỗi trưởng thành, hình dạng giống hệt"]}, {"cauHoi": "Sự lớn lên của chó con khác ấu trùng muỗi ở điểm nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Trình bày sự lớn lên của con non thú mẹ.", "id": "KH5-B16-07", "mucDo": 2, "phuongAn": ["Chó con sinh ra đã giống con trưởng thành hơn, được mẹ nuôi bằng sữa; không qua giai đoạn ấu trùng, nhộng như muỗi", "Chó con phải hoá nhộng", "Chó không có vòng đời", "Chó con cũng sống dưới nước như bọ gậy"]}, {"cauHoi": "Ếch thuộc nhóm nào và vòng đời của ếch có đặc điểm gì nổi bật?", "dang": "TN", "dapAn": 3, "giaiThich": "Bài ôn tập cũng nêu vòng đời ếch.", "id": "KH5-B16-08", "mucDo": 2, "phuongAn": ["Chỉ có giai đoạn nhộng", "Đẻ con và nuôi bằng sữa", "Không có vòng đời", "Đẻ trứng; con non (nòng nọc) sống dưới nước, hình dạng khác ếch trưởng thành"]}, {"cauHoi": "Muốn hạn chế muỗi phát triển, em nên làm gì dựa vào vòng đời của muỗi?", "dang": "TN", "dapAn": 1, "giaiThich": "Vận dụng vòng đời muỗi vào thực tế (gợi ý ôn tập).", "id": "KH5-B16-09", "mucDo": 3, "phuongAn": ["Trồng thêm vũng nước dưới gầm giường", "Không để nước đọng, diệt bọ gậy, không cho trứng và ấu trùng muỗi phát triển", "Ủ nước mưa quanh nhà cho muỗi đẻ", "Chỉ đuổi muỗi trưởng thành, để nguyên vũng nước"]}, {"cauHoi": "Vì sao không thể dựa vào hình dạng ấu trùng để nhận ra hết đặc điểm của con trưởng thành ở muỗi hay bướm?", "dang": "TN", "dapAn": 2, "giaiThich": "Sự biến đổi hình thái trong vòng đời.", "id": "KH5-B16-10", "mucDo": 3, "phuongAn": ["Vì chúng đẻ con", "Vì chúng giống hệt nhau từ đầu", "Vì ấu trùng khác xa con trưởng thành về hình dạng và môi trường sống", "Vì chúng không lớn lên"]}, {"cauHoi": "Gà là động vật đẻ trứng; vòng đời có con non nở ra từ trứng, hình dạng", "dang": "TN", "dapAn": 0, "giaiThich": "So sánh sự lớn lên của con non nở từ trứng (gà) với ấu trùng muỗi.", "id": "KH5-B16-11", "mucDo": 1, "phuongAn": ["Khác ấu trùng muỗi, gà con đã khá giống gà lớn, không qua giai đoạn nhộng", "Giống hệt bọ gậy", "Sống hoàn toàn dưới nước như nòng nọc", "Phải hoá nhộng trong kén"]}, {"cauHoi": "Bướm cái trưởng thành thường đẻ trứng ở đâu theo bài?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo mô tả vòng đời bướm.", "id": "KH5-B16-12", "mucDo": 2, "phuongAn": ["Trong sữa mẹ", "Dưới đất sâu hàng mét", "Trên lá", "Trong tổ chim thú"]}, {"cauHoi": "Ghi chú vòng đời của muỗi hoặc bướm và nêu một điểm khác với vòng đời của chó.", "dang": "TL", "giaiThich": "Muỗi/bướm: trứng – ấu trùng – nhộng – trưởng thành. Chó: con non – trưởng thành; con non được mẹ sinh ra và nuôi bằng sữa, không qua ấu trùng, nhộng.", "id": "KH5-B16-13", "mucDo": 3}], "chuDe": "3", "ten": "Vòng đời và sự phát triển của động vật", "tenChuDe": "Chủ đề 3. Thực vật và động vật", "tenGoc": "Bài 16. Vòng đời và sự phát triển của động vật", "tuan": "16–17", "yeuCauCanDat": ["Sử dụng sơ đồ đã cho, ghi chú được vòng đời của một số động vật đẻ trứng và đẻ con; trình bày được sự lớn lên của con non nở ra từ trứng và con non được sinh ra từ thú mẹ."]}, "17": {"cauHoi": [{"cauHoi": "Cơ quan sinh sản của thực vật có hoa là", "dang": "TN", "dapAn": 1, "giaiThich": "Ôn tập.", "id": "KH5-B17-01", "mucDo": 1, "phuongAn": ["Rễ củ", "Hoa", "Thân gỗ", "Lá già"]}, {"cauHoi": "Hoa có cả nhị và nhuỵ được gọi là", "dang": "TN", "dapAn": 3, "giaiThich": "Ôn tập.", "id": "KH5-B17-02", "mucDo": 1, "phuongAn": ["Hoa không thụ phấn", "Quả", "Hoa đơn tính", "Hoa lưỡng tính"]}, {"cauHoi": "Gà, ếch thuộc nhóm động vật", "dang": "TN", "dapAn": 2, "giaiThich": "Ôn tập.", "id": "KH5-B17-03", "mucDo": 1, "phuongAn": ["Đẻ con và nuôi bằng sữa", "Sinh sản bằng hạt", "Đẻ trứng", "Không sinh sản"]}, {"cauHoi": "Bò, lợn thuộc nhóm động vật", "dang": "TN", "dapAn": 0, "giaiThich": "Ôn tập.", "id": "KH5-B17-04", "mucDo": 1, "phuongAn": ["Đẻ con", "Không có vòng đời", "Sinh sản bằng hoa", "Đẻ trứng như gà"]}, {"cauHoi": "Cây con có thể mọc từ", "dang": "TN", "dapAn": 3, "giaiThich": "Ôn tập cách cây con xuất hiện.", "id": "KH5-B17-05", "mucDo": 2, "phuongAn": ["Chỉ từ đá", "Chỉ từ không khí", "Chỉ từ ánh sáng", "Hạt hoặc thân, rễ, lá của một số cây mẹ"]}, {"cauHoi": "Vòng đời có giai đoạn nhộng điển hình ở động vật nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Bốn giai đoạn có nhộng.", "id": "KH5-B17-06", "mucDo": 2, "phuongAn": ["Lợn, mèo", "Muỗi, bướm", "Bò, chó", "Người"]}, {"cauHoi": "Dựa vào vòng đời ếch hoặc muỗi, nêu một việc làm có lợi trong đời sống.", "dang": "TN", "dapAn": 3, "giaiThich": "Vận dụng vòng đời vào thực tế.", "id": "KH5-B17-07", "mucDo": 3, "phuongAn": ["Phá hết trứng ếch ở mọi ao hồ mà không cần lí do", "Ủ nước đọng quanh nhà", "Phun hoá chất bừa bãi vào đất sạch", "Diệt bọ gậy, không để nước đọng để phòng muỗi; bảo vệ nơi ếch sinh sản nếu cần giữ cân bằng sinh thái"]}, {"cauHoi": "Tóm tắt bằng sơ đồ miệng bốn nội dung: sinh sản thực vật có hoa; cây con mọc từ hạt hoặc bộ phận cây mẹ; động vật đẻ trứng; động vật đẻ con.", "dang": "TL", "giaiThich": "Hoa (nhị, nhuỵ) thụ phấn, thụ tinh tạo hạt, quả. Cây con từ hạt hoặc thân, rễ, lá. Đẻ trứng: gà, ếch, muỗi,... có vòng đời trứng (và ấu trùng, có khi nhộng). Đẻ con: bò, chó,... con non bú sữa.", "id": "KH5-B17-08", "mucDo": 3}], "chuDe": "3", "ten": "Ôn tập chủ đề Thực vật và động vật", "tenChuDe": "Chủ đề 3. Thực vật và động vật", "tenGoc": "Bài 17. Ôn tập chủ đề Thực vật và động vật", "tuan": "17", "yeuCauCanDat": ["Tóm tắt được những nội dung chính đã học dưới dạng sơ đồ.", "Vận dụng được kiến thức và kĩ năng của chủ đề vào giải quyết một số tình huống đơn giản trong đời sống."]}, "18": {"cauHoi": [{"cauHoi": "Vi khuẩn có đặc điểm kích thước như thế nào?", "dang": "TN", "dapAn": 0, "giaiThich": "YCCĐ và chốt kiến thức bài.", "id": "KH5-B18-01", "mucDo": 1, "phuongAn": ["Rất nhỏ, không thể nhìn thấy bằng mắt thường", "To bằng quả bóng", "Không có kích thước", "To bằng hạt gạo, nhìn rõ bằng mắt thường"]}, {"cauHoi": "Muốn quan sát vi khuẩn, người ta dùng gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Hình ảnh vi khuẩn được quan sát nhờ kính hiển vi.", "id": "KH5-B18-02", "mucDo": 1, "phuongAn": ["Kính râm", "Kính hiển vi có độ phóng đại lớn", "Chỉ dùng mắt thường", "Kính lúp thường không đủ trong mọi trường hợp như kính hiển vi"]}, {"cauHoi": "Vi khuẩn sống ở đâu?", "dang": "TN", "dapAn": 2, "giaiThich": "YCCĐ: sống ở khắp nơi trong đất, nước, sinh vật khác.", "id": "KH5-B18-03", "mucDo": 1, "phuongAn": ["Chỉ ở trên mây", "Chỉ trong phòng thí nghiệm", "Ở khắp nơi: trong đất, nước, sinh vật khác và nhiều nơi xung quanh ta", "Không sống ở đất, nước"]}, {"cauHoi": "Vì sao rửa tay thường xuyên lại cần thiết, dù nhìn tay có vẻ sạch?", "dang": "TN", "dapAn": 2, "giaiThich": "Chốt bài: cần rửa tay để loại bỏ vi khuẩn.", "id": "KH5-B18-04", "mucDo": 1, "phuongAn": ["Vì rửa tay làm tăng vi khuẩn", "Vì trên tay không bao giờ có vi khuẩn", "Vì vi khuẩn có thể bám trên tay mà mắt thường không thấy", "Vì vi khuẩn chỉ sống trên chân"]}, {"cauHoi": "Hai mẫu đất và nước trông như không có gì chuyển động. Có thể kết luận không có vi khuẩn được không?", "dang": "TN", "dapAn": 1, "giaiThich": "Bài mở đầu, dự đoán mẫu vật.", "id": "KH5-B18-05", "mucDo": 2, "phuongAn": ["Được, vì vi khuẩn chỉ sống trong không khí sạch", "Không, vì vi khuẩn nhỏ, mắt thường không thấy, chúng có thể có trong đất, nước", "Không, vì vi khuẩn to bằng viên sỏi", "Được, vì không nhìn thấy là không có"]}, {"cauHoi": "Vi khuẩn khác virus ở chỗ bài này nhấn mạnh điều gì khi quan sát?", "dang": "TN", "dapAn": 3, "giaiThich": "SGV lưu ý không nhầm vi khuẩn với virus.", "id": "KH5-B18-06", "mucDo": 2, "phuongAn": ["Vi khuẩn nhìn rõ bằng mắt thường còn virus thì không", "Cả hai đều nhìn rõ không cần kính", "Virus chính là vi khuẩn", "Vi khuẩn được quan sát, nghiên cứu dưới kính hiển vi; không nhầm với virus chỉ nghe tên bệnh"]}, {"cauHoi": "Sau khi chơi ở sân, trước khi ăn, em nên làm gì? Vì sao?", "dang": "TN", "dapAn": 0, "giaiThich": "Vận dụng: vi khuẩn ở khắp nơi, mắt thường không thấy.", "id": "KH5-B18-07", "mucDo": 2, "phuongAn": ["Rửa tay sạch vì tay có thể dính vi khuẩn dù nhìn không thấy", "Ăn luôn cho nhanh", "Không cần rửa vì mắt không thấy gì", "Chỉ lau tay vào áo"]}, {"cauHoi": "Vì sao nói “vi khuẩn sống ở khắp mọi nơi” không có nghĩa mọi vi khuẩn đều nhìn thấy trên mặt bàn?", "dang": "TN", "dapAn": 0, "giaiThich": "Kết nối kích thước và nơi sống.", "id": "KH5-B18-08", "mucDo": 2, "phuongAn": ["Vì chúng rất nhỏ, phải dùng kính hiển vi mới thấy; chúng vẫn có thể có trên bàn, tay, đất, nước", "Vì chúng chỉ sống dưới đại dương", "Vì chúng không tồn tại", "Vì chúng to nhưng trong suốt hoàn toàn"]}, {"cauHoi": "Vi khuẩn có thể có trong những môi trường nào?", "dang": "TN", "dapAn": 3, "giaiThich": "YCCĐ: đất, nước, sinh vật khác.", "id": "KH5-B18-09", "mucDo": 1, "phuongAn": ["Chỉ trên đỉnh núi băng", "Chỉ trong sách giáo khoa sạch", "Không ở trong đất", "Đất, nước và cơ thể sinh vật khác"]}, {"cauHoi": "Hình ảnh vi khuẩn trong sách được quan sát nhờ", "dang": "TN", "dapAn": 1, "giaiThich": "Theo bài.", "id": "KH5-B18-10", "mucDo": 1, "phuongAn": ["Kính râm", "Kính hiển vi phóng đại rất lớn", "Mắt thường không cần dụng cụ", "Kính viễn vọng"]}, {"cauHoi": "Không nhìn thấy vi khuẩn trên bàn tay có nghĩa là tay chắc chắn sạch vi khuẩn không?", "dang": "TN", "dapAn": 2, "giaiThich": "Chốt kiến thức bài 18.", "id": "KH5-B18-11", "mucDo": 2, "phuongAn": ["Có, vì không nhìn thấy là không có", "Không, vì vi khuẩn to bằng hạt cát", "Không, vì mắt thường không thấy được vi khuẩn", "Có, vì vi khuẩn chỉ sống dưới nước"]}, {"cauHoi": "Nêu hai đặc điểm của vi khuẩn đã học và một việc làm phù hợp trong đời sống.", "dang": "TL", "giaiThich": "Rất nhỏ, không nhìn thấy bằng mắt thường; sống ở khắp nơi (đất, nước, sinh vật,...). Việc làm: rửa tay, giữ sạch đồ dùng, không đưa tay bẩn lên miệng.", "id": "KH5-B18-12", "mucDo": 3}], "chuDe": "4", "ten": "Vi khuẩn xung quanh chúng ta", "tenChuDe": "Chủ đề 4. Vi khuẩn", "tenGoc": "Bài 18. Vi khuẩn xung quanh chúng ta", "tuan": "19", "yeuCauCanDat": ["Nhận ra được vi khuẩn có kích thước nhỏ, không thể nhìn thấy bằng mắt thường; chúng sống ở khắp nơi trong đất, nước, sinh vật khác,... qua quan sát tranh ảnh, video."]}, "19": {"cauHoi": [{"cauHoi": "Vi khuẩn lactic được dùng trong chế biến thực phẩm nào dưới đây?", "dang": "TN", "dapAn": 3, "giaiThich": "Ví dụ chính của bài.", "id": "KH5-B19-01", "mucDo": 1, "phuongAn": ["Chỉ trong dầu ăn", "Chỉ trong nước ngọt có ga", "Chỉ trong muối tinh khiết", "Sữa chua, muối chua rau củ quả"]}, {"cauHoi": "Vì sao sữa chua có vị chua, ít ngọt?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo bài.", "id": "KH5-B19-02", "mucDo": 1, "phuongAn": ["Vì sữa chua không có sữa", "Vì vi khuẩn làm mất hết nước", "Vì vi khuẩn lactic đã sử dụng đường trong sữa", "Vì người ta thêm ớt"]}, {"cauHoi": "Khi muối chua quả sung, vì sao nên cho đường?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo gợi ý SGV/SGK.", "id": "KH5-B19-03", "mucDo": 1, "phuongAn": ["Vì không cần vi khuẩn", "Vì vi khuẩn lactic sử dụng đường có trong nguyên liệu", "Vì đường diệt hết vi khuẩn ngay", "Vì đường làm quả sung chín cây"]}, {"cauHoi": "Tất cả vi khuẩn có hại với con người hay không?", "dang": "TN", "dapAn": 0, "giaiThich": "Mở đầu bài: không chỉ nghĩ đến vi khuẩn có hại.", "id": "KH5-B19-04", "mucDo": 1, "phuongAn": ["Không, một số vi khuẩn có ích, được dùng trong chế biến thực phẩm", "Vi khuẩn không liên quan thực phẩm", "Không có vi khuẩn có ích nào", "Có, mọi vi khuẩn đều gây bệnh"]}, {"cauHoi": "Nếu cho sữa chua vào ngay khi sữa còn đang sôi, có thể xảy ra điều gì?", "dang": "TN", "dapAn": 2, "giaiThich": "SGV: vi khuẩn lactic chết nếu cho vào khi vừa đun sôi.", "id": "KH5-B19-05", "mucDo": 2, "phuongAn": ["Sữa chua ngon hơn ngay", "Vi khuẩn sống tốt hơn trong nước sôi", "Vi khuẩn lactic chết vì nhiệt độ quá cao, sữa khó thành sữa chua đúng cách", "Không ảnh hưởng gì"]}, {"cauHoi": "Vì sao nên cho sữa chua đã làm xong vào tủ lạnh?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo SGV.", "id": "KH5-B19-06", "mucDo": 2, "phuongAn": ["Để sữa sôi lại", "Vì tủ lạnh diệt hết mọi chất dinh dưỡng", "Để vi khuẩn hoạt động mạnh hơn, chua thêm rất nhanh", "Nhiệt độ thấp kìm hãm hoạt động của vi khuẩn lactic, sữa không chua thêm, bảo quản được lâu hơn"]}, {"cauHoi": "Hãy chọn đúng một ví dụ sử dụng vi khuẩn có ích trong chế biến thực phẩm và nêu ngắn gọn vai trò của chúng.", "dang": "TN", "dapAn": 0, "giaiThich": "YCCĐ: một đến hai ví dụ.", "id": "KH5-B19-07", "mucDo": 3, "phuongAn": ["Làm sữa chua hoặc muối chua rau củ: vi khuẩn lactic làm thay đổi vị, tạo sản phẩm", "Giữ thịt sống ở nhiệt độ phòng nhiều ngày để vi khuẩn gây hỏng", "Rửa tay thay cho việc chế biến", "Đun sôi sữa chua để tăng số vi khuẩn lactic"]}, {"cauHoi": "Vì sao cần phân biệt vi khuẩn có ích trong chế biến thực phẩm với việc để thức ăn ôi thiu?", "dang": "TN", "dapAn": 1, "giaiThich": "Vận dụng, tránh hiểu nhầm.", "id": "KH5-B19-08", "mucDo": 3, "phuongAn": ["Vi khuẩn không bao giờ có hại", "Không phải vi khuẩn nào cũng có ích; chỉ một số được dùng có kiểm soát trong chế biến; thức ăn ôi thiu là hỏng, có hại", "Mọi thức ăn ôi thiu đều là sữa chua", "Muối chua và thức ăn thiu là một"]}, {"cauHoi": "Muối chua rau, củ, quả là ví dụ về", "dang": "TN", "dapAn": 2, "giaiThich": "Ví dụ thứ hai của bài.", "id": "KH5-B19-09", "mucDo": 1, "phuongAn": ["Không liên quan vi khuẩn", "Chỉ phơi nắng", "Sử dụng vi khuẩn có ích trong chế biến thực phẩm", "Chỉ dùng nhiệt để nấu chín"]}, {"cauHoi": "Vi khuẩn không chỉ gây bệnh mà còn", "dang": "TN", "dapAn": 0, "giaiThich": "Phân biệt vi khuẩn có ích và có hại.", "id": "KH5-B19-10", "mucDo": 2, "phuongAn": ["Được dùng để làm sữa chua, muối chua rau củ", "Không sống trong thực phẩm", "Luôn làm hỏng mọi thức ăn", "Chỉ sống trong không khí sạch"]}, {"cauHoi": "Trình bày một ví dụ sử dụng vi khuẩn có ích trong chế biến thực phẩm.", "dang": "TL", "giaiThich": "Làm sữa chua hoặc muối chua rau, củ, quả nhờ vi khuẩn lactic; chúng sử dụng đường, tạo vị chua đặc trưng.", "id": "KH5-B19-11", "mucDo": 3}], "chuDe": "4", "ten": "Vi khuẩn có ích trong chế biến thực phẩm", "tenChuDe": "Chủ đề 4. Vi khuẩn", "tenGoc": "Bài 19. Vi khuẩn có ích trong chế biến thực phẩm", "tuan": "20", "yeuCauCanDat": ["Trình bày được một đến hai ví dụ về việc sử dụng vi khuẩn có ích trong chế biến thực phẩm."]}, "2": {"cauHoi": [{"cauHoi": "Nguyên nhân nào do con người gây ra làm ô nhiễm đất?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo hình và thông tin SGK.", "id": "KH5-B02-01", "mucDo": 1, "phuongAn": ["Đổ rác thải sinh hoạt, nước thải chưa xử lí và dùng thừa thuốc trừ sâu ra môi trường", "Núi lửa phun trào", "Gió thổi trên mặt đất", "Mưa rơi xuống đất"]}, {"cauHoi": "Hiện tượng núi lửa phun trào dung nham làm đất khô cứng thuộc nhóm nguyên nhân nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Đây là nguyên nhân tự nhiên.", "id": "KH5-B02-02", "mucDo": 1, "phuongAn": ["Chỉ do tưới nước", "Nguyên nhân không do con người trực tiếp gây ra", "Chỉ do xới đất", "Chỉ do trồng cây"]}, {"cauHoi": "Ô nhiễm đất kéo dài có thể gây tác hại nào đối với cây trồng?", "dang": "TN", "dapAn": 2, "giaiThich": "Đất ô nhiễm làm cây thiếu dinh dưỡng, chậm lớn.", "id": "KH5-B02-03", "mucDo": 1, "phuongAn": ["Cây không cần nước", "Đất trở nên tơi xốp hơn", "Cây chậm lớn, chất lượng sản phẩm giảm vì đất cằn cỗi, thiếu dinh dưỡng", "Cây lớn nhanh hơn"]}, {"cauHoi": "Xói mòn đất do nước thường xảy ra ở đâu?", "dang": "TN", "dapAn": 3, "giaiThich": "Nước mưa cuốn đất trên bề mặt đất dốc.", "id": "KH5-B02-04", "mucDo": 1, "phuongAn": ["Trong phòng thí nghiệm", "Dưới đáy biển sâu", "Vùng đất luôn bằng phẳng, không có mưa", "Vùng đất dốc, khi nước mưa cuốn đất đi"]}, {"cauHoi": "Biện pháp nào giúp chống ô nhiễm đất?", "dang": "TN", "dapAn": 3, "giaiThich": "Giảm chất thải và xử lí chất thải trước khi thải.", "id": "KH5-B02-05", "mucDo": 1, "phuongAn": ["Đổ rác trực tiếp ra vườn", "Dùng thật nhiều thuốc trừ sâu", "Tưới nước thải chưa xử lí ra ruộng", "Tái chế phế liệu, xử lí chất thải trước khi thải ra môi trường"]}, {"cauHoi": "Biện pháp nào giúp chống xói mòn đất?", "dang": "TN", "dapAn": 2, "giaiThich": "Cây và ruộng bậc thang giữ đất, hạn chế nước cuốn trôi.", "id": "KH5-B02-06", "mucDo": 1, "phuongAn": ["Đổ nước thải xuống đồi", "Phá hết cây trên sườn dốc", "Trồng cây, làm ruộng bậc thang, che phủ bề mặt đất", "Cày hết lớp đất mặt rồi để trống"]}, {"cauHoi": "Vì sao khí thải, nước thải nhà máy cũng có thể làm ô nhiễm đất?", "dang": "TN", "dapAn": 0, "giaiThich": "Khí thải theo mưa và nước thải có thể ngấm vào đất.", "id": "KH5-B02-07", "mucDo": 2, "phuongAn": ["Khi mưa, chất độc trong không khí và nước thải có thể ngấm vào đất", "Vì nước thải không bao giờ đụng tới đất", "Vì đất không thấm nước", "Vì khí thải chỉ bay lên trời mãi"]}, {"cauHoi": "Người thường xuyên tiếp xúc với đất bị ô nhiễm có thể gặp hậu quả nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Chất độc trong đất ô nhiễm ảnh hưởng sức khoẻ con người.", "id": "KH5-B02-08", "mucDo": 2, "phuongAn": ["Chỉ làm tóc dài hơn", "Ảnh hưởng đến sức khoẻ, có thể mắc bệnh do chất độc", "Không bị ảnh hưởng gì", "Khoẻ hơn bình thường"]}, {"cauHoi": "Việc làm nào giúp bảo vệ môi trường đất ở gia đình?", "dang": "TN", "dapAn": 2, "giaiThich": "Giảm rác và hoá chất thải ra đất.", "id": "KH5-B02-09", "mucDo": 2, "phuongAn": ["Đổ dầu nhớt cũ xuống đất", "Vứt rác sau vườn hằng ngày", "Phân loại rác, không đổ rác và hoá chất bừa bãi ra đất", "Tưới thuốc trừ sâu rất nhiều"]}, {"cauHoi": "Vì sao phá rừng trên sườn đồi dễ làm tăng xói mòn đất?", "dang": "TN", "dapAn": 3, "giaiThich": "Cây giữ đất; mất cây thì đất dễ bị nước, gió cuốn.", "id": "KH5-B02-10", "mucDo": 3, "phuongAn": ["Vì đất không còn nước", "Vì không còn gió", "Vì rừng làm đất nặng hơn", "Rễ cây và tán lá không còn để giữ đất, nước mưa dễ cuốn đất đi"]}, {"cauHoi": "Em sẽ vận động người thân làm việc nào để bảo vệ môi trường đất?", "dang": "TN", "dapAn": 1, "giaiThich": "Những việc làm giảm ô nhiễm và chống xói mòn đất.", "id": "KH5-B02-11", "mucDo": 3, "phuongAn": ["Lấy hết lớp đất mặt bán đi", "Không đổ rác, nước thải chưa xử lí ra đất; tham gia trồng cây", "Tưới thuốc trừ sâu càng nhiều càng tốt", "Đốt rác thải giữa vườn rau"]}, {"cauHoi": "Nêu hai việc em có thể làm để góp phần bảo vệ môi trường đất.", "dang": "TL", "giaiThich": "Ví dụ: không đổ rác ra đất, phân loại rác, không dùng thừa thuốc trừ sâu, tham gia trồng cây, nhắc người thân xử lí rác đúng nơi quy định.", "id": "KH5-B02-12", "mucDo": 3}], "chuDe": "1", "ten": "Ô nhiễm, xói mòn đất và bảo vệ môi trường đất", "tenChuDe": "Chủ đề 1. Chất", "tenGoc": "Bài 2. Ô nhiễm, xói mòn đất và bảo vệ môi trường đất", "tuan": "2–3", "yeuCauCanDat": ["Nêu được nguyên nhân, tác hại của ô nhiễm, xói mòn đất và biện pháp chống ô nhiễm, xói mòn đất.", "Đề xuất, thực hiện được việc làm giúp bảo vệ môi trường đất và vận động những người xung quanh cùng thực hiện."]}, "20": {"cauHoi": [{"cauHoi": "Bệnh nào dưới đây do vi khuẩn gây ra?", "dang": "TN", "dapAn": 3, "giaiThich": "Bài tập trung sâu răng, tả; SGV còn nêu lị, viêm họng, viêm phổi, lao.", "id": "KH5-B20-01", "mucDo": 1, "phuongAn": ["Gãy xương do ngã", "Cúm (do vi-rút)", "Cận thị do ngồi gần tivi", "Sâu răng, bệnh tả"]}, {"cauHoi": "Nguyên nhân chính gây sâu răng là gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo bài.", "id": "KH5-B20-02", "mucDo": 1, "phuongAn": ["Do chỉ uống nước lọc", "Vi khuẩn có sẵn trong miệng, phân huỷ thức ăn bám trên răng, tạo axit làm hỏng men răng", "Do đánh răng quá nhiều", "Do không khí sạch"]}, {"cauHoi": "Ăn nhiều đồ ngọt làm tăng nguy cơ sâu răng vì", "dang": "TN", "dapAn": 1, "giaiThich": "Theo bài luyện tập.", "id": "KH5-B20-03", "mucDo": 1, "phuongAn": ["Đường không liên quan răng", "Vi khuẩn gây sâu răng sử dụng đường, tăng nguy cơ làm hỏng răng", "Đường tự làm trắng răng", "Đường diệt vi khuẩn trong miệng"]}, {"cauHoi": "Vi khuẩn tả xâm nhập vào cơ thể chủ yếu qua đường nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo thông tin bài.", "id": "KH5-B20-04", "mucDo": 1, "phuongAn": ["Đường tiêu hoá", "Da đầu", "Chỉ qua tóc", "Chỉ qua móng tay khô sạch"]}, {"cauHoi": "Người bệnh tả cần được chăm sóc đặc biệt điều gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo thông tin bài.", "id": "KH5-B20-05", "mucDo": 1, "phuongAn": ["Chỉ ngậm kẹo", "Chạy bộ ngay", "Bù nước và điều trị theo hướng dẫn của bác sĩ", "Tự ý nhịn uống nước hoàn toàn"]}, {"cauHoi": "Khi nào người bị sâu răng thường cảm thấy đau nhiều?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo tiến triển mô tả trong bài.", "id": "KH5-B20-06", "mucDo": 2, "phuongAn": ["Ngay khi mới bám một ít thức ăn, chưa hỏng men", "Khi răng còn nguyên men, chưa có lỗ sâu", "Khi đã hết vi khuẩn", "Khi vi khuẩn phá huỷ đến tuỷ răng, đau liên tục, nhất là về đêm"]}, {"cauHoi": "Cách phòng tránh sâu răng gồm những việc nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Việc nên làm đã học.", "id": "KH5-B20-07", "mucDo": 2, "phuongAn": ["Uống nước đá thay vì vệ sinh răng", "Không bao giờ đánh răng", "Hạn chế đồ ngọt, đánh răng đúng cách, khám răng; không để thức ăn bám lâu trên răng", "Ăn thật nhiều kẹo suốt ngày"]}, {"cauHoi": "Để phòng tránh lây nhiễm vi khuẩn tả, nên làm gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo thông tin bài.", "id": "KH5-B20-08", "mucDo": 2, "phuongAn": ["Uống nước không sạch", "Vệ sinh nơi ở, giữ sạch nguồn nước và thức ăn, rửa tay, mở cửa sổ thông thoáng", "Ăn thức ăn để ôi", "Không rửa tay trước khi ăn"]}, {"cauHoi": "Vì sao thức ăn còn bám trên răng lại tạo điều kiện cho sâu răng?", "dang": "TN", "dapAn": 3, "giaiThich": "Chốt bài: thức ăn bám răng nuôi vi khuẩn.", "id": "KH5-B20-09", "mucDo": 3, "phuongAn": ["Răng không tiếp xúc với thức ăn", "Thức ăn diệt hết vi khuẩn", "Vi khuẩn chỉ sống ở chân", "Thức ăn là nơi ở và thức ăn cho vi khuẩn; vi khuẩn hoạt động làm hỏng men răng"]}, {"cauHoi": "Em sẽ khuyên bạn cùng lớp làm gì để phòng sâu răng và bệnh do vi khuẩn đường tiêu hoá?", "dang": "TN", "dapAn": 0, "giaiThich": "Vận dụng cách phòng tránh.", "id": "KH5-B20-10", "mucDo": 3, "phuongAn": ["Hạn chế đồ ngọt, đánh răng, không ăn quà bẩn, rửa tay, uống nước sạch", "Dùng chung bàn chải đã cũ với nhiều người khi bị ốm", "Uống nước ao, ăn thức ăn ôi", "Ăn kẹo quanh năm, không rửa tay"]}, {"cauHoi": "Ngoài sâu răng và bệnh tả, SGV còn nêu một số bệnh do vi khuẩn như", "dang": "TN", "dapAn": 2, "giaiThich": "Thông tin bài, không nhầm với bệnh do virus.", "id": "KH5-B20-11", "mucDo": 1, "phuongAn": ["Cảm lạnh do chỉ ngồi gần quạt", "Gãy xương", "Viêm họng, viêm phổi, lị, lao", "Cận thị"]}, {"cauHoi": "Dấu hiệu ban đầu khi nhiễm vi khuẩn tả có thể là", "dang": "TN", "dapAn": 3, "giaiThich": "Theo thông tin bài; cần đi khám, bù nước.", "id": "KH5-B20-12", "mucDo": 1, "phuongAn": ["Chỉ nổi mụn ở lưng", "Chỉ đau răng về đêm", "Chỉ ho nhẹ một tiếng", "Đầy bụng, sôi bụng, sau đó tiêu chảy, nôn, mất nước"]}, {"cauHoi": "Vệ sinh nơi ở, mở cửa sổ thường xuyên góp phần", "dang": "TN", "dapAn": 1, "giaiThich": "Theo bài phòng tránh.", "id": "KH5-B20-13", "mucDo": 2, "phuongAn": ["Làm sâu răng nặng hơn", "Phòng lây nhiễm một số vi khuẩn gây bệnh", "Không liên quan sức khoẻ", "Làm tăng vi khuẩn tả trong nước uống"]}, {"cauHoi": "Kể hai bệnh do vi khuẩn gây ra, nêu nguyên nhân và một cách phòng mỗi bệnh.", "dang": "TL", "giaiThich": "Sâu răng: vi khuẩn trong miệng phân huỷ thức ăn, làm hỏng răng; hạn chế đồ ngọt, đánh răng, khám răng. Tả: vi khuẩn vào qua đường tiêu hoá; vệ sinh ăn uống, rửa tay, nước sạch, đến cơ sở y tế khi có triệu chứng.", "id": "KH5-B20-14", "mucDo": 3}], "chuDe": "4", "ten": "Vi khuẩn gây bệnh ở người và cách phòng tránh", "tenChuDe": "Chủ đề 4. Vi khuẩn", "tenGoc": "Bài 20. Vi khuẩn gây bệnh ở người và cách phòng tránh", "tuan": "21", "yeuCauCanDat": ["Kể được tên một đến hai bệnh ở người do vi khuẩn gây ra; nêu được nguyên nhân gây bệnh và cách phòng tránh."]}, "21": {"cauHoi": [{"cauHoi": "Vi khuẩn nhìn bằng mắt thường thì", "dang": "TN", "dapAn": 0, "giaiThich": "Ôn tập.", "id": "KH5-B21-01", "mucDo": 1, "phuongAn": ["Không thấy được vì rất nhỏ", "To rõ như hạt gạo", "Lớn bằng con kiến", "Không tồn tại"]}, {"cauHoi": "Vi khuẩn sống", "dang": "TN", "dapAn": 1, "giaiThich": "Ôn tập.", "id": "KH5-B21-02", "mucDo": 1, "phuongAn": ["Chỉ trên đỉnh núi tuyết sạch", "Ở khắp nơi: đất, nước, sinh vật và nhiều chỗ xung quanh ta", "Chỉ trong sách", "Không ở trong đất, nước"]}, {"cauHoi": "Ví dụ vi khuẩn có ích trong chế biến thực phẩm là", "dang": "TN", "dapAn": 3, "giaiThich": "Ôn tập.", "id": "KH5-B21-03", "mucDo": 1, "phuongAn": ["Vi khuẩn gây sâu răng", "Vi khuẩn gây bệnh tả", "Mọi vi khuẩn trong thức ăn ôi", "Vi khuẩn lactic làm sữa chua, muối chua rau củ"]}, {"cauHoi": "Bệnh sâu răng và bệnh tả do", "dang": "TN", "dapAn": 0, "giaiThich": "Ôn tập.", "id": "KH5-B21-04", "mucDo": 1, "phuongAn": ["Vi khuẩn gây ra", "Thiếu gió", "Thiếu ánh sáng mặt trời", "Nắng nóng thôi"]}, {"cauHoi": "Để hạn chế nguy cơ nhiễm vi khuẩn gây bệnh, em nên làm gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Ôn tập đường lây và phòng tránh.", "id": "KH5-B21-05", "mucDo": 2, "phuongAn": ["Không rửa tay, ăn quà đường phố không đảm bảo", "Uống nước không sạch", "Rửa tay, ăn uống hợp vệ sinh, giữ sạch nhà cửa, hạn chế đồ ngọt, đánh răng", "Để thức ăn bám răng suốt ngày"]}, {"cauHoi": "Mở cửa sổ, rửa tay, làm sữa chua đúng cách cho thấy điều gì về vi khuẩn?", "dang": "TN", "dapAn": 1, "giaiThich": "Vận dụng cả chủ đề.", "id": "KH5-B21-06", "mucDo": 3, "phuongAn": ["Mọi vi khuẩn đều phải diệt hết, không dùng vào việc gì", "Vi khuẩn có loại có ích và loại gây bệnh; ta vừa dùng được loại có ích vừa phải phòng loại gây bệnh", "Vi khuẩn không liên quan đời sống", "Mọi vi khuẩn đều có ích, không cần rửa tay"]}, {"cauHoi": "Tóm tắt: nơi sống và kích thước của vi khuẩn; một ví dụ có ích; một bệnh và cách phòng.", "dang": "TL", "giaiThich": "Vi khuẩn rất nhỏ, sống khắp nơi. Có ích: lactic làm sữa chua, muối chua. Gây bệnh: sâu răng, tả,... Phòng: rửa tay, vệ sinh ăn uống, đánh răng, hạn chế đồ ngọt.", "id": "KH5-B21-07", "mucDo": 3}], "chuDe": "4", "ten": "Ôn tập chủ đề Vi khuẩn", "tenChuDe": "Chủ đề 4. Vi khuẩn", "tenGoc": "Bài 21. Ôn tập chủ đề Vi khuẩn", "tuan": "21", "yeuCauCanDat": ["Tóm tắt được những nội dung chính đã học dưới dạng sơ đồ.", "Vận dụng được kiến thức và kĩ năng của chủ đề vào giải quyết một số tình huống đơn giản trong đời sống."]}, "22": {"cauHoi": [{"cauHoi": "Ý nghĩa của sự sinh sản đối với gia đình, dòng họ là gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo SGK/SGV.", "id": "KH5-B22-01", "mucDo": 1, "phuongAn": ["Làm gia đình không còn ai", "Không có ý nghĩa gì", "Tạo ra thế hệ mới, tiếp nối các thế hệ trong gia đình, dòng họ", "Chỉ để đổi chỗ ở"]}, {"cauHoi": "Đối với xã hội, sự sinh sản còn có ý nghĩa", "dang": "TN", "dapAn": 3, "giaiThich": "Theo SGV/SGK.", "id": "KH5-B22-02", "mucDo": 1, "phuongAn": ["Chỉ liên quan đến cây trồng", "Không liên quan xã hội", "Làm giảm mọi công việc", "Tạo ra lực lượng lao động, góp phần xây dựng và phát triển xã hội"]}, {"cauHoi": "Cơ thể người được hình thành từ sự kết hợp giữa", "dang": "TN", "dapAn": 0, "giaiThich": "Chốt kiến thức bài.", "id": "KH5-B22-03", "mucDo": 1, "phuongAn": ["Trứng của mẹ và tinh trùng của bố", "Chỉ tinh trùng của bố", "Chỉ trứng của mẹ", "Không khí và nước"]}, {"cauHoi": "Sự kết hợp giữa trứng và tinh trùng được gọi là gì?", "dang": "TN", "dapAn": 0, "giaiThich": "Thuật ngữ đã học.", "id": "KH5-B22-04", "mucDo": 1, "phuongAn": ["Sự thụ tinh", "Sự bay hơi", "Sự quang hợp", "Sự nảy mầm"]}, {"cauHoi": "Trứng đã được thụ tinh gọi là gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo SGK.", "id": "KH5-B22-05", "mucDo": 1, "phuongAn": ["Noãn chưa thụ tinh", "Hợp tử", "Lá mầm", "Bao phấn"]}, {"cauHoi": "Hợp tử phát triển thành gì trong tử cung của mẹ?", "dang": "TN", "dapAn": 2, "giaiThich": "Hợp tử – phôi – thai nhi.", "id": "KH5-B22-06", "mucDo": 1, "phuongAn": ["Chỉ thành hoa", "Thành cây con", "Phôi, rồi thành thai nhi", "Chỉ thành hạt"]}, {"cauHoi": "Khoảng bao lâu sau thụ tinh thì em bé thường được sinh ra?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo SGK: khoảng 9 tháng sau thụ tinh.", "id": "KH5-B22-07", "mucDo": 1, "phuongAn": ["Khoảng 2 tháng", "Khoảng 9 tuần", "Khoảng 9 ngày", "Khoảng 9 tháng"]}, {"cauHoi": "Thứ tự đúng của quá trình hình thành cơ thể người là", "dang": "TN", "dapAn": 1, "giaiThich": "Sơ đồ đã học.", "id": "KH5-B22-08", "mucDo": 2, "phuongAn": ["Thai nhi – tinh trùng – hợp tử", "Trứng và tinh trùng – thụ tinh – hợp tử – phôi – thai nhi – em bé được sinh ra", "Phôi – trứng – thụ tinh", "Em bé – hợp tử – trứng"]}, {"cauHoi": "Vì sao sự sinh sản ở người có ý nghĩa với việc tiếp nối các thế hệ?", "dang": "TN", "dapAn": 3, "giaiThich": "Ý nghĩa đã học.", "id": "KH5-B22-09", "mucDo": 2, "phuongAn": ["Vì không có trẻ em nào được sinh ra", "Vì xã hội không cần người lao động", "Vì người không lớn lên", "Nhờ sinh sản, các thế hệ trong gia đình, dòng họ được duy trì kế tiếp nhau"]}, {"cauHoi": "Khi nói về sự hình thành cơ thể người, thuật ngữ nào không thể thiếu trên sơ đồ?", "dang": "TN", "dapAn": 0, "giaiThich": "YCCĐ: dùng đúng thuật ngữ.", "id": "KH5-B22-10", "mucDo": 3, "phuongAn": ["Trứng, tinh trùng, thụ tinh, hợp tử, phôi, thai nhi", "Chỉ có mạch điện", "Chỉ có rễ, thân, lá", "Chỉ có dung dịch"]}, {"cauHoi": "Phôi tiếp tục phát triển thành thai nhi ở đâu?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo sơ đồ bài học.", "id": "KH5-B22-11", "mucDo": 1, "phuongAn": ["Trên lá cây", "Trong hạt", "Trong tử cung của mẹ", "Trong không khí"]}, {"cauHoi": "Nếu thiếu sự thụ tinh thì không có", "dang": "TN", "dapAn": 1, "giaiThich": "Vai trò của thụ tinh.", "id": "KH5-B22-12", "mucDo": 2, "phuongAn": ["Chỉ thiếu đất", "Hợp tử, do đó không hình thành phôi, thai nhi theo cách đã học", "Chỉ thiếu ánh sáng", "Chỉ thiếu không khí"]}, {"cauHoi": "Trình bày ngắn gọn quá trình hình thành cơ thể người bằng các thuật ngữ đã học.", "dang": "TL", "giaiThich": "Tinh trùng của bố kết hợp với trứng của mẹ qua thụ tinh tạo hợp tử. Hợp tử phát triển thành phôi, rồi thành thai nhi trong tử cung mẹ. Khoảng 9 tháng sau, em bé được sinh ra.", "id": "KH5-B22-13", "mucDo": 3}], "chuDe": "5", "ten": "Sự hình thành cơ thể người", "tenChuDe": "Chủ đề 5. Con người và sức khoẻ", "tenGoc": "Bài 22. Sự hình thành cơ thể người", "tuan": "22–23", "yeuCauCanDat": ["Nêu được ý nghĩa của sự sinh sản ở người.", "Sử dụng được sơ đồ và một số thuật ngữ (trứng, tinh trùng, sự thụ tinh,...) để trình bày quá trình hình thành cơ thể người."]}, "23": {"cauHoi": [{"cauHoi": "Sự phát triển của con người được chia thành mấy giai đoạn chính theo bài học?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo SGK/SGV: bốn giai đoạn chính.", "id": "KH5-B23-01", "mucDo": 1, "phuongAn": ["Chỉ một giai đoạn", "Chỉ hai giai đoạn", "Không chia giai đoạn", "Bốn giai đoạn chính"]}, {"cauHoi": "Tuổi ấu thơ là giai đoạn từ lúc nào đến lúc nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo SGK/SGV.", "id": "KH5-B23-02", "mucDo": 1, "phuongAn": ["Sau 60 tuổi", "Từ 20 đến 60 tuổi", "Từ lúc mới sinh đến 9 tuổi", "Từ 10 đến 19 tuổi"]}, {"cauHoi": "Tuổi vị thành niên là giai đoạn", "dang": "TN", "dapAn": 0, "giaiThich": "Theo SGK/SGV.", "id": "KH5-B23-03", "mucDo": 1, "phuongAn": ["Từ 10 đến 19 tuổi", "Từ lúc mới sinh đến 9 tuổi", "Sau 80 tuổi", "Từ 20 đến 60 tuổi"]}, {"cauHoi": "Tuổi dậy thì nằm chủ yếu ở đâu trong các giai đoạn đã học?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo SGK/SGV.", "id": "KH5-B23-04", "mucDo": 1, "phuongAn": ["Ở giai đoạn đầu của tuổi vị thành niên", "Ở cuối tuổi già", "Trước khi sinh", "Sau 60 tuổi"]}, {"cauHoi": "Tuổi trưởng thành theo bài là giai đoạn", "dang": "TN", "dapAn": 2, "giaiThich": "Theo SGK/SGV.", "id": "KH5-B23-05", "mucDo": 1, "phuongAn": ["Từ 10 đến 12 tuổi", "Chỉ có ở nam", "Từ 20 đến 60 tuổi", "Từ lúc mới sinh đến 3 tuổi"]}, {"cauHoi": "Đặc điểm nào nổi bật ở đầu tuổi vị thành niên (tuổi dậy thì)?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo nội dung bài.", "id": "KH5-B23-06", "mucDo": 2, "phuongAn": ["Không còn học tập được", "Chỉ có tóc bạc", "Người hoàn toàn không thay đổi so với lúc mới sinh", "Cơ thể phát triển nhanh, cơ quan sinh dục phát triển"]}, {"cauHoi": "Người ở tuổi trưởng thành có vai trò nổi bật nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Vai trò người trưởng thành.", "id": "KH5-B23-07", "mucDo": 2, "phuongAn": ["Không tham gia đời sống xã hội", "Làm việc, chăm sóc gia đình, tham gia các hoạt động xã hội", "Chỉ biết chơi, chưa làm được việc gì", "Chưa biết đi"]}, {"cauHoi": "Vì sao tuổi vị thành niên cần rèn luyện, học tập tốt?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo SGV/SGK.", "id": "KH5-B23-08", "mucDo": 2, "phuongAn": ["Để khi trưởng thành có sức khoẻ, kiến thức, làm được việc phù hợp", "Vì không cần học nữa", "Vì chỉ cần chơi", "Vì đã hết thời gian lớn"]}, {"cauHoi": "Một học sinh lớp 5 khoảng 10–11 tuổi đang ở giai đoạn nào? Tuổi dậy thì quan hệ thế nào với giai đoạn đó?", "dang": "TN", "dapAn": 3, "giaiThich": "Vận dụng mốc đã học.", "id": "KH5-B23-09", "mucDo": 2, "phuongAn": ["Ở tuổi ấu thơ dưới 1 tuổi", "Ở tuổi trưởng thành đủ 60 tuổi", "Ở tuổi già", "Ở tuổi vị thành niên; tuổi dậy thì chủ yếu diễn ra ở giai đoạn đầu của tuổi này"]}, {"cauHoi": "Hãy sắp xếp đúng thứ tự các giai đoạn phát triển chính của con người.", "dang": "TN", "dapAn": 2, "giaiThich": "Phân biệt các giai đoạn.", "id": "KH5-B23-10", "mucDo": 3, "phuongAn": ["Tuổi trưởng thành – tuổi ấu thơ – vị thành niên", "Chỉ có tuổi dậy thì rồi dừng lại", "Tuổi ấu thơ – tuổi vị thành niên (có tuổi dậy thì ở giai đoạn đầu) – tuổi trưởng thành – tuổi già", "Tuổi già – tuổi ấu thơ – tuổi trưởng thành"]}, {"cauHoi": "Tuổi dậy thì ở nữ thường bắt đầu khoảng", "dang": "TN", "dapAn": 1, "giaiThich": "Thông tin bài/SGV, mốc tham khảo.", "id": "KH5-B23-11", "mucDo": 1, "phuongAn": ["Sau 70 tuổi", "8 đến 13 tuổi", "Lúc mới sinh", "20 đến 60 tuổi"]}, {"cauHoi": "Tuổi dậy thì ở nam thường bắt đầu khoảng", "dang": "TN", "dapAn": 3, "giaiThich": "Thông tin bài/SGV, mốc tham khảo.", "id": "KH5-B23-12", "mucDo": 1, "phuongAn": ["Sau 70 tuổi", "1 đến 3 tuổi", "Lúc mới sinh", "9 đến 14 tuổi"]}, {"cauHoi": "Người 35 tuổi đang ở giai đoạn nào theo bài học?", "dang": "TN", "dapAn": 0, "giaiThich": "Mốc 20–60 tuổi.", "id": "KH5-B23-13", "mucDo": 2, "phuongAn": ["Tuổi trưởng thành", "Mới sinh", "Tuổi ấu thơ", "Tuổi vị thành niên"]}, {"cauHoi": "Nêu tên và khoảng tuổi các giai đoạn phát triển chính của con người theo bài học.", "dang": "TL", "giaiThich": "Tuổi ấu thơ (mới sinh đến 9 tuổi); tuổi vị thành niên (10–19 tuổi), tuổi dậy thì ở giai đoạn đầu; tuổi trưởng thành (20–60 tuổi); sau đó là tuổi già.", "id": "KH5-B23-14", "mucDo": 3}], "chuDe": "5", "ten": "Các giai đoạn phát triển chính của con người", "tenChuDe": "Chủ đề 5. Con người và sức khoẻ", "tenGoc": "Bài 23. Các giai đoạn phát triển chính của con người", "tuan": "23–24", "yeuCauCanDat": ["Phân biệt được một số giai đoạn phát triển chính của con người (tuổi ấu thơ, tuổi dậy thì, tuổi trưởng thành,...)."]}, "24": {"cauHoi": [{"cauHoi": "Đặc điểm sinh học của nam và nữ khác nhau cơ bản ở đâu?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo bài.", "id": "KH5-B24-01", "mucDo": 1, "phuongAn": ["Màu áo đang mặc", "Cấu tạo và chức năng của cơ quan sinh dục", "Môn thể thao yêu thích", "Trường đang học"]}, {"cauHoi": "Đặc điểm nào là đặc điểm sinh học thường thấy ở nam khi đến một độ tuổi nhất định?", "dang": "TN", "dapAn": 2, "giaiThich": "Ví dụ đặc điểm sinh học.", "id": "KH5-B24-02", "mucDo": 1, "phuongAn": ["Luôn phải làm hết việc nhà", "Không được nói chuyện", "Có râu, cơ quan sinh dục nam tạo ra tinh trùng", "Không được học"]}, {"cauHoi": "Đặc điểm nào là đặc điểm sinh học của nữ?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo bài, phân biệt sinh học và xã hội.", "id": "KH5-B24-03", "mucDo": 1, "phuongAn": ["Không làm được việc xã hội", "Không được chơi thể thao", "Không được đi học", "Có kinh nguyệt, cơ quan sinh dục nữ tạo ra trứng; mang thai và cho con bú"]}, {"cauHoi": "Vai trò của nam và nữ trong gia đình, xã hội", "dang": "TN", "dapAn": 0, "giaiThich": "Theo SGK: vai trò xã hội có thể thay đổi.", "id": "KH5-B24-04", "mucDo": 1, "phuongAn": ["Có thể thay đổi, cả nam và nữ đều có thể chia sẻ việc nhà, học tập, làm việc xã hội", "Chỉ nữ mới được học", "Chỉ nam mới được nói", "Không bao giờ thay đổi"]}, {"cauHoi": "Việc nào dưới đây là đặc điểm sinh học chỉ nữ mới thực hiện được?", "dang": "TN", "dapAn": 1, "giaiThich": "Nấu ăn, học tập, chăm sóc là việc cả nam và nữ đều có thể làm.", "id": "KH5-B24-05", "mucDo": 2, "phuongAn": ["Nấu ăn", "Mang thai và cho con bú", "Học toán", "Chăm sóc em nhỏ"]}, {"cauHoi": "Vì sao không nên phân biệt đối xử giữa nam và nữ?", "dang": "TN", "dapAn": 2, "giaiThich": "YCCĐ: tôn trọng bạn cùng giới và khác giới.", "id": "KH5-B24-06", "mucDo": 2, "phuongAn": ["Vì nam và nữ không khác nhau về bất kì đặc điểm nào", "Vì chỉ nam mới có quyền", "Vì cả nam và nữ đều cần được tôn trọng, học tập, phát triển; nhiều việc xã hội cả hai đều làm được", "Vì chỉ nữ mới có quyền"]}, {"cauHoi": "Ở nhà, bố cùng nấu ăn, chăm con; mẹ đi làm và tham gia công việc xã hội. Điều này cho thấy gì?", "dang": "TN", "dapAn": 3, "giaiThich": "Vận dụng phân biệt đặc điểm xã hội và sinh học.", "id": "KH5-B24-07", "mucDo": 2, "phuongAn": ["Đó là việc làm sai", "Nam không được chăm con", "Chỉ nữ mới được nấu ăn", "Đặc điểm, vai trò xã hội có thể thay đổi, nam và nữ cùng chia sẻ việc gia đình và xã hội"]}, {"cauHoi": "Khi bạn khác giới trong lớp nêu ý kiến, em nên thái độ thế nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Thể hiện tôn trọng.", "id": "KH5-B24-08", "mucDo": 3, "phuongAn": ["Không cho bạn nói vì khác giới", "Lắng nghe, tôn trọng, không chê bai vì bạn là nam hay nữ", "Chỉ chơi với bạn cùng giới", "Cười chế giễu"]}, {"cauHoi": "Nấu ăn, học tập, tham gia công việc xã hội là", "dang": "TN", "dapAn": 2, "giaiThich": "Phân biệt đặc điểm xã hội và sinh học.", "id": "KH5-B24-09", "mucDo": 1, "phuongAn": ["Việc không ai làm được", "Đặc điểm sinh học chỉ nữ mới làm được", "Việc cả nam và nữ đều có thể làm, thuộc đặc điểm vai trò xã hội", "Đặc điểm sinh học chỉ nam mới làm được"]}, {"cauHoi": "Ngày nay, nhiều phụ nữ tham gia công tác xã hội, giữ vị trí lãnh đạo. Điều này cho thấy", "dang": "TN", "dapAn": 0, "giaiThich": "Theo SGK.", "id": "KH5-B24-10", "mucDo": 2, "phuongAn": ["Vai trò xã hội của nam và nữ có thể thay đổi", "Đặc điểm sinh học đã đảo ngược hoàn toàn", "Nữ không còn đặc điểm sinh học nào", "Nam không được làm việc xã hội"]}, {"cauHoi": "Nêu một đặc điểm sinh học và một đặc điểm xã hội; nói một việc em làm để tôn trọng bạn khác giới.", "dang": "TL", "giaiThich": "Sinh học: khác nhau về cơ quan sinh dục, kinh nguyệt, tinh trùng, mang thai, cho con bú. Xã hội: học tập, làm việc, việc nhà – cả nam và nữ đều có thể làm, vai trò có thể thay đổi. Tôn trọng: lắng nghe, không phân biệt, chia sẻ việc công bằng.", "id": "KH5-B24-11", "mucDo": 3}], "chuDe": "5", "ten": "Nam và nữ", "tenChuDe": "Chủ đề 5. Con người và sức khoẻ", "tenGoc": "Bài 24. Nam và nữ", "tuan": "25", "yeuCauCanDat": ["Phân biệt được đặc điểm sinh học và đặc điểm xã hội của nam và nữ; thể hiện được thái độ và thực hiện tôn trọng các bạn cùng giới và khác giới."]}, "25": {"cauHoi": [{"cauHoi": "Tuổi dậy thì cần chăm sóc sức khoẻ về những mặt nào?", "dang": "TN", "dapAn": 3, "giaiThich": "YCCĐ.", "id": "KH5-B25-01", "mucDo": 1, "phuongAn": ["Không cần chăm sóc", "Chỉ thể chất", "Chỉ tinh thần", "Thể chất và tinh thần"]}, {"cauHoi": "Việc làm nào giúp chăm sóc sức khoẻ thể chất ở tuổi dậy thì?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo hình và thông tin bài.", "id": "KH5-B25-02", "mucDo": 1, "phuongAn": ["Ăn uống đủ chất, vận động, tập thể dục, ngủ đủ, vệ sinh cơ thể", "Ăn ít, không uống nước", "Không vận động", "Thức khuya hằng đêm, bỏ bữa"]}, {"cauHoi": "Khi có những thay đổi ở tuổi dậy thì, em nên", "dang": "TN", "dapAn": 2, "giaiThich": "Bài nêu chia sẻ với người lớn về những thay đổi.", "id": "KH5-B25-03", "mucDo": 1, "phuongAn": ["Bỏ học", "Cười chê bạn cũng đang thay đổi", "Chia sẻ với người lớn tin cậy (bố mẹ, thầy cô)", "Giữ hoàn toàn một mình khi đang lo lắng, không hỏi ai"]}, {"cauHoi": "Vì sao ở tuổi dậy thì càng cần giữ vệ sinh cơ thể?", "dang": "TN", "dapAn": 1, "giaiThich": "YCCĐ và nội dung bài.", "id": "KH5-B25-04", "mucDo": 1, "phuongAn": ["Vì không cần tắm nữa", "Cơ thể có nhiều thay đổi, nếu không vệ sinh dễ ngứa, nổi mụn, mất sạch sẽ, ảnh hưởng sức khoẻ", "Vì vệ sinh làm hại da", "Vì cơ thể không thay đổi gì"]}, {"cauHoi": "Vệ sinh cơ thể ở tuổi dậy thì gồm", "dang": "TN", "dapAn": 1, "giaiThich": "Theo bài, phù hợp lứa tuổi.", "id": "KH5-B25-05", "mucDo": 1, "phuongAn": ["Không thay quần áo", "Tắm, gội bằng nước sạch, vệ sinh cơ quan sinh dục ngoài hằng ngày, thay quần áo, với nữ thì thay băng vệ sinh đúng cách khi có kinh nguyệt", "Không tắm trong nhiều ngày", "Dùng chung khăn ướt với người đang bị bệnh da"]}, {"cauHoi": "Vận động giữa giờ, ăn hết phần cơm đủ chất, ngủ đúng giờ là việc chăm sóc", "dang": "TN", "dapAn": 0, "giaiThich": "Việc làm đã học.", "id": "KH5-B25-06", "mucDo": 2, "phuongAn": ["Sức khoẻ thể chất, cũng hỗ trợ tinh thần", "Chỉ để được khen", "Không liên quan sức khoẻ", "Chỉ trang trí lớp học"]}, {"cauHoi": "Không thường xuyên vệ sinh cơ thể ở tuổi dậy thì có thể dẫn đến", "dang": "TN", "dapAn": 3, "giaiThich": "Tác hại nêu trong bài.", "id": "KH5-B25-07", "mucDo": 2, "phuongAn": ["Không có tác hại gì", "Da khoẻ hơn", "Chỉ làm tóc dài hơn", "Ngứa, nổi mụn, cơ thể không sạch, dễ ảnh hưởng sức khoẻ và sự tự tin"]}, {"cauHoi": "Vì sao cần vệ sinh cơ quan sinh dục ngoài hằng ngày ở tuổi dậy thì?", "dang": "TN", "dapAn": 2, "giaiThich": "YCCĐ, diễn đạt phù hợp, không đi vào chi tiết không có trong bài.", "id": "KH5-B25-08", "mucDo": 3, "phuongAn": ["Vì không cần thiết", "Vì chỉ rửa tay là đủ cho cả cơ thể", "Vì đây là giai đoạn cơ thể thay đổi, cần giữ sạch để khoẻ mạnh, phòng ngứa và viêm nhiễm", "Vì chỉ người lớn mới cần"]}, {"cauHoi": "Bạn cùng lớp đang lo lắng vì cơ thể thay đổi. Em nên làm gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Chăm sóc sức khoẻ tinh thần, tôn trọng.", "id": "KH5-B25-09", "mucDo": 3, "phuongAn": ["Bảo bạn không được nói với ai", "Khuyên bạn chia sẻ với bố mẹ hoặc thầy cô tin cậy, không chế giễu", "Cười nhạo", "Khoe chuyện của bạn cho cả lớp để trêu"]}, {"cauHoi": "Ngủ đủ, không thức quá khuya là việc chăm sóc", "dang": "TN", "dapAn": 3, "giaiThich": "Việc cần làm đã học.", "id": "KH5-B25-10", "mucDo": 1, "phuongAn": ["Chỉ dành cho người già", "Không liên quan tuổi dậy thì", "Chỉ trang điểm", "Sức khoẻ thể chất và cũng hỗ trợ tinh thần"]}, {"cauHoi": "Tắm, gội bằng nước sạch giúp", "dang": "TN", "dapAn": 2, "giaiThich": "Sự cần thiết của vệ sinh cơ thể.", "id": "KH5-B25-11", "mucDo": 2, "phuongAn": ["Thay cho việc ăn uống", "Không cần thiết ở tuổi dậy thì", "Cơ thể sạch, hạn chế ngứa, nổi mụn", "Làm tăng bẩn"]}, {"cauHoi": "Nêu ba việc chăm sóc sức khoẻ thể chất hoặc tinh thần ở tuổi dậy thì và giải thích vì sao phải giữ vệ sinh cơ thể.", "dang": "TL", "giaiThich": "Ăn đủ chất, vận động, ngủ đủ, tắm gội, vệ sinh cơ quan sinh dục ngoài, chia sẻ với người lớn khi lo lắng. Ở tuổi dậy thì cơ thể thay đổi, không vệ sinh dễ ngứa, nổi mụn, ảnh hưởng sức khoẻ.", "id": "KH5-B25-12", "mucDo": 3}], "chuDe": "5", "ten": "Chăm sóc sức khoẻ tuổi dậy thì", "tenChuDe": "Chủ đề 5. Con người và sức khoẻ", "tenGoc": "Bài 25. Chăm sóc sức khoẻ tuổi dậy thì", "tuan": "26–27", "yeuCauCanDat": ["Nêu và thực hiện được những việc cần làm để chăm sóc, bảo vệ sức khoẻ về thể chất và tinh thần ở tuổi dậy thì.", "Giải thích được sự cần thiết phải giữ vệ sinh cơ thể, đặc biệt là ở tuổi dậy thì.", "Có ý thức và kĩ năng thực hiện vệ sinh cơ thể, đặc biệt là vệ sinh cơ quan sinh dục ngoài."]}, "26": {"cauHoi": [{"cauHoi": "Mọi trẻ em đều có quyền nào dưới đây?", "dang": "TN", "dapAn": 0, "giaiThich": "YCCĐ.", "id": "KH5-B26-01", "mucDo": 1, "phuongAn": ["Quyền được an toàn, được bảo vệ sự toàn vẹn của cá nhân", "Không có quyền từ chối", "Quyền bị xâm hại", "Quyền im lặng khi đang bị làm hại mà không được kể với ai"]}, {"cauHoi": "Khi cảm thấy không an toàn, em nên", "dang": "TN", "dapAn": 0, "giaiThich": "Phản đối xâm hại, tìm sự giúp đỡ.", "id": "KH5-B26-02", "mucDo": 1, "phuongAn": ["Nói “Không”, rời khỏi tình huống và nhờ người tin cậy giúp đỡ", "Im lặng, đi theo người lạ", "Giữ bí mật với mọi người lớn", "Tự xử lí một mình mọi tình huống nguy hiểm"]}, {"cauHoi": "Người đáng tin cậy em có thể nhờ khi cần giúp đỡ thường là", "dang": "TN", "dapAn": 1, "giaiThich": "YCCĐ: lập danh sách người tin cậy.", "id": "KH5-B26-03", "mucDo": 1, "phuongAn": ["Ai cũng được, không cần biết rõ", "Bố mẹ, ông bà, thầy cô, người thân tin cậy, cơ quan chức năng", "Người ép em giữ bí mật việc làm sai", "Người lạ vừa gặp trên đường"]}, {"cauHoi": "Nguy cơ bị xâm hại có thể đến từ tình huống nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo các tình huống bài học (mức độ phù hợp).", "id": "KH5-B26-04", "mucDo": 1, "phuongAn": ["Chơi cùng bạn ở sân trường lúc ra chơi có nhiều người", "Nói chuyện với bố mẹ", "Học nhóm ở lớp có thầy cô", "Người lạ rủ đi một mình, ép xem tranh ảnh không phù hợp, đụng chạm chỗ riêng tư, bắt giữ bí mật"]}, {"cauHoi": "Khi có người rủ đi một mình, hứa quà, bảo “đừng nói với bố mẹ”, em nên làm gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Dấu hiệu nguy cơ và cách ứng phó.", "id": "KH5-B26-05", "mucDo": 2, "phuongAn": ["Không kể với ai", "Đi theo ngay để nhận quà", "Từ chối, không đi, kể lại với người lớn tin cậy", "Giữ bí mật như lời dặn"]}, {"cauHoi": "Nếu bạn trong lớp có nguy cơ bị xâm hại, em nên", "dang": "TN", "dapAn": 3, "giaiThich": "YCCĐ: đưa ra yêu cầu giúp đỡ khi bạn có nguy cơ.", "id": "KH5-B26-06", "mucDo": 2, "phuongAn": ["Bỏ mặc, không nói gì", "Bắt bạn im lặng", "Khoe chuyện của bạn cho cả lớp để đùa", "Báo người lớn tin cậy, cùng bạn tìm sự giúp đỡ"]}, {"cauHoi": "Cảm giác an toàn là khi", "dang": "TN", "dapAn": 0, "giaiThich": "Bài nêu dấu hiệu an toàn và không an toàn.", "id": "KH5-B26-07", "mucDo": 2, "phuongAn": ["Em được tôn trọng, không bị ép buộc, không sợ bị làm tổn thương", "Em bị bắt phải giữ bí mật việc sai", "Em bị đe doạ", "Em bị người lạ kéo đi"]}, {"cauHoi": "Hãy chọn cách ứng phó đúng khi có nguy cơ bị xâm hại.", "dang": "TN", "dapAn": 2, "giaiThich": "Các bước phòng tránh, ứng phó đã học.", "id": "KH5-B26-08", "mucDo": 3, "phuongAn": ["Im lặng vì sợ mất lòng", "Tự giải quyết mãi một mình khi đang rất sợ", "Nói không, rời đi, kể với người tin cậy, nhờ giúp đỡ; không giữ bí mật việc sai", "Đi theo người lạ vì tò mò"]}, {"cauHoi": "Vì sao cần lập trước danh sách người đáng tin cậy?", "dang": "TN", "dapAn": 1, "giaiThich": "YCCĐ lập danh sách người tin cậy.", "id": "KH5-B26-09", "mucDo": 3, "phuongAn": ["Vì không bao giờ cần nhờ ai", "Để khi gặp tình huống không an toàn, em biết ngay mình sẽ nói với ai, nhờ ai giúp", "Để không nói với bố mẹ nữa", "Để kể chuyện riêng tư cho tất cả mọi người"]}, {"cauHoi": "Em có được phản đối mọi sự xâm hại không?", "dang": "TN", "dapAn": 1, "giaiThich": "YCCĐ.", "id": "KH5-B26-10", "mucDo": 1, "phuongAn": ["Chỉ người lớn mới có quyền đó", "Có, em có quyền được an toàn và được nói không", "Không, phải im lặng", "Chỉ phản đối khi đã bị hại lâu"]}, {"cauHoi": "Người ép em giữ bí mật một việc làm sai, không cho kể với bố mẹ, là dấu hiệu", "dang": "TN", "dapAn": 2, "giaiThich": "Dấu hiệu nguy cơ đã học.", "id": "KH5-B26-11", "mucDo": 2, "phuongAn": ["An toàn, nên nghe lời", "Không liên quan", "Nguy cơ, em cần từ chối và kể với người tin cậy khác", "Chỉ là đùa bình thường"]}, {"cauHoi": "Nêu quyền được an toàn, hai việc nên làm khi có nguy cơ bị xâm hại, và hai người em có thể nhờ giúp.", "dang": "TL", "giaiThich": "Mọi trẻ đều có quyền được an toàn, được bảo vệ, được nói không. Nên từ chối, rời đi, kể với người lớn tin cậy, không giữ bí mật việc sai. Người nhờ: bố mẹ, thầy cô, ông bà, người thân tin cậy.", "id": "KH5-B26-12", "mucDo": 3}], "chuDe": "5", "ten": "Phòng tránh bị xâm hại", "tenChuDe": "Chủ đề 5. Con người và sức khoẻ", "tenGoc": "Bài 26. Phòng tránh bị xâm hại", "tuan": "27–28", "yeuCauCanDat": ["Nói được về cảm giác an toàn và quyền được an toàn, bảo vệ sự toàn vẹn của cá nhân và phản đối mọi sự xâm hại.", "Lập được danh sách những người đáng tin cậy để được giúp đỡ khi cần.", "Trình bày được những nguy cơ dẫn đến bị xâm hại tình dục và cách phòng tránh, ứng phó khi có nguy cơ bị xâm hại.", "Đưa ra được yêu cầu giúp đỡ khi bản thân hoặc bạn bè có nguy cơ bị xâm hại."]}, "27": {"cauHoi": [{"cauHoi": "Cơ thể người được hình thành từ", "dang": "TN", "dapAn": 3, "giaiThich": "Ôn tập bài 22.", "id": "KH5-B27-01", "mucDo": 1, "phuongAn": ["Chỉ từ thức ăn", "Chỉ từ đất", "Chỉ từ không khí", "Sự thụ tinh giữa trứng và tinh trùng, tạo hợp tử, rồi thành phôi, thai nhi"]}, {"cauHoi": "Tuổi ấu thơ theo bài là", "dang": "TN", "dapAn": 0, "giaiThich": "Ôn tập bài 23.", "id": "KH5-B27-02", "mucDo": 1, "phuongAn": ["Từ lúc mới sinh đến 9 tuổi", "Từ 10 đến 19 tuổi", "Sau 60 tuổi", "Từ 20 đến 60 tuổi"]}, {"cauHoi": "Mang thai và cho con bú là", "dang": "TN", "dapAn": 0, "giaiThich": "Ôn tập bài 24.", "id": "KH5-B27-03", "mucDo": 1, "phuongAn": ["Đặc điểm sinh học của nữ", "Không phải đặc điểm sinh học", "Việc xã hội chỉ nam mới làm được", "Việc cả nam và nữ đều làm được như nhau về mặt sinh học"]}, {"cauHoi": "Ở tuổi dậy thì, em cần", "dang": "TN", "dapAn": 1, "giaiThich": "Ôn tập bài 25.", "id": "KH5-B27-04", "mucDo": 2, "phuongAn": ["Bỏ vệ sinh cá nhân", "Chăm sóc sức khoẻ thể chất và tinh thần, giữ vệ sinh cơ thể", "Thức khuya, bỏ bữa", "Không chia sẻ khi lo lắng"]}, {"cauHoi": "Việc làm phù hợp khi em cảm thấy không an toàn là gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Ôn tập bài 26: nói không và nhờ người lớn tin cậy.", "id": "KH5-B27-05", "mucDo": 2, "phuongAn": ["Đi theo người lạ", "Im lặng mãi", "Nói không, nhờ người lớn tin cậy", "Giữ bí mật việc sai"]}, {"cauHoi": "Hãy chọn cách ứng xử đúng trong đời sống sau khi học chủ đề này.", "dang": "TN", "dapAn": 3, "giaiThich": "Vận dụng cả chủ đề.", "id": "KH5-B27-06", "mucDo": 3, "phuongAn": ["Giữ bí mật khi có nguy cơ bị làm hại", "Chê bai bạn khác giới, không rửa tay, đi với người lạ", "Không cần quyền được an toàn", "Tôn trọng bạn nam và nữ, giữ vệ sinh, chia sẻ với người lớn khi lo lắng, phản đối mọi sự xâm hại"]}, {"cauHoi": "Tóm tắt bốn nội dung: hình thành cơ thể người; các giai đoạn phát triển; nam và nữ; chăm sóc sức khoẻ và an toàn.", "dang": "TL", "giaiThich": "Thụ tinh tạo hợp tử, phôi, thai, em bé. Các giai đoạn: ấu thơ, vị thành niên (dậy thì), trưởng thành, già. Phân biệt đặc điểm sinh học và xã hội, tôn trọng nhau. Chăm sóc thể chất, tinh thần, vệ sinh; quyền được an toàn, nhờ người tin cậy.", "id": "KH5-B27-07", "mucDo": 3}], "chuDe": "5", "ten": "Ôn tập chủ đề Con người và sức khoẻ", "tenChuDe": "Chủ đề 5. Con người và sức khoẻ", "tenGoc": "Bài 27. Ôn tập chủ đề Con người và sức khoẻ", "tuan": "28", "yeuCauCanDat": ["Tóm tắt được những nội dung chính đã học dưới dạng sơ đồ.", "Vận dụng được kiến thức và kĩ năng của chủ đề vào giải quyết một số tình huống đơn giản trong đời sống."]}, "28": {"cauHoi": [{"cauHoi": "Môi trường là", "dang": "TN", "dapAn": 2, "giaiThich": "Theo bài.", "id": "KH5-B28-01", "mucDo": 1, "phuongAn": ["Chỉ có không khí", "Chỉ có sách vở", "Tất cả các yếu tố xung quanh sinh vật, có thể ảnh hưởng đến sinh vật", "Chỉ có nhà cửa"]}, {"cauHoi": "Chức năng nào dưới đây là chức năng cơ bản của môi trường?", "dang": "TN", "dapAn": 3, "giaiThich": "YCCĐ.", "id": "KH5-B28-02", "mucDo": 1, "phuongAn": ["Chỉ cung cấp điện thoại", "Không liên quan sinh vật", "Chỉ làm đẹp tranh vẽ", "Cung cấp chỗ ở, thức ăn và nhu cầu sống thiết yếu"]}, {"cauHoi": "Môi trường còn có chức năng", "dang": "TN", "dapAn": 0, "giaiThich": "YCCĐ.", "id": "KH5-B28-03", "mucDo": 1, "phuongAn": ["Chứa đựng các chất thải do con người và sinh vật tạo ra trong quá trình sống", "Chỉ chứa đồ chơi", "Tiêu diệt mọi sinh vật", "Không chứa chất thải nào"]}, {"cauHoi": "Chức năng bảo vệ của môi trường là", "dang": "TN", "dapAn": 1, "giaiThich": "YCCĐ, ví dụ rừng giữ nước, chắn gió,...", "id": "KH5-B28-04", "mucDo": 1, "phuongAn": ["Không có tác dụng che chắn", "Bảo vệ con người và sinh vật khỏi một số tác động từ bên ngoài", "Làm tăng mọi thiên tai", "Chỉ bảo vệ nhà cao tầng"]}, {"cauHoi": "Các yếu tố sinh vật cần để sống, lớn lên, sinh sản đều", "dang": "TN", "dapAn": 1, "giaiThich": "Theo bài.", "id": "KH5-B28-05", "mucDo": 1, "phuongAn": ["Chỉ lấy từ sách", "Có nguồn gốc từ môi trường", "Tự có mà không cần môi trường", "Không lấy từ môi trường"]}, {"cauHoi": "Rừng cây giữ được nước mưa, nước thấm xuống đất. Đây chủ yếu là chức năng nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Câu hỏi SGV: vì sao rừng giữ được nước mưa.", "id": "KH5-B28-06", "mucDo": 2, "phuongAn": ["Chứa rác thải nhựa", "Cung cấp điện thoại", "Bảo vệ, điều hoà; rừng giúp giữ nước, hạn chế lũ, hạn", "Làm mất hết nước"]}, {"cauHoi": "Phân, nước tiểu của động vật thải ra môi trường liên quan chức năng nào của môi trường?", "dang": "TN", "dapAn": 3, "giaiThich": "Chất thải của sinh vật.", "id": "KH5-B28-07", "mucDo": 2, "phuongAn": ["Tạo năng lượng điện", "Cung cấp ánh sáng mặt trời", "Làm sách giáo khoa", "Nơi chứa đựng chất thải"]}, {"cauHoi": "Cỏ, nước, không khí, chỗ ở giúp con bò lớn lên, sinh sản. Đây là chức năng", "dang": "TN", "dapAn": 0, "giaiThich": "Ví dụ trong bài tập SGV.", "id": "KH5-B28-08", "mucDo": 2, "phuongAn": ["Cung cấp chỗ ở, thức ăn và nhu cầu sống thiết yếu", "Không phải chức năng môi trường", "Chỉ gây ô nhiễm", "Chỉ chứa chất thải"]}, {"cauHoi": "Nếu không còn rừng trên đầu nguồn, chức năng nào của môi trường bị giảm rõ? Hệ quả có thể là gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Vận dụng chức năng bảo vệ của môi trường.", "id": "KH5-B28-09", "mucDo": 3, "phuongAn": ["Đất chắc hơn", "Chức năng bảo vệ, giữ nước giảm; dễ lũ, xói mòn, hạn", "Sông luôn đầy nước đều", "Không khí tự sạch hơn mãi"]}, {"cauHoi": "Hãy nêu đủ ba chức năng cơ bản của môi trường đối với sinh vật và con người.", "dang": "TN", "dapAn": 3, "giaiThich": "YCCĐ cần đủ ba chức năng.", "id": "KH5-B28-10", "mucDo": 3, "phuongAn": ["Chỉ cung cấp thức ăn", "Chỉ để đi chơi", "Chỉ chứa chất thải", "Cung cấp chỗ ở, thức ăn, nhu cầu thiết yếu; chứa chất thải; bảo vệ khỏi tác động bên ngoài"]}, {"cauHoi": "Không khí, nước, ánh sáng là những nhu cầu sống mà sinh vật lấy từ", "dang": "TN", "dapAn": 2, "giaiThich": "Chức năng cung cấp nhu cầu thiết yếu.", "id": "KH5-B28-11", "mucDo": 1, "phuongAn": ["Chỉ từ sách", "Không lấy từ đâu", "Môi trường", "Chỉ từ điện thoại"]}, {"cauHoi": "Môi trường sống của sinh vật có thể là", "dang": "TN", "dapAn": 0, "giaiThich": "Thông tin bài/SGV.", "id": "KH5-B28-12", "mucDo": 2, "phuongAn": ["Môi trường cạn, đất, nước hoặc môi trường sinh vật", "Không phân loại được", "Chỉ có môi trường lớp học", "Chỉ có môi trường sách"]}, {"cauHoi": "Trình bày ba chức năng cơ bản của môi trường và lấy mỗi chức năng một ví dụ.", "dang": "TL", "giaiThich": "Cung cấp chỗ ở, thức ăn, không khí, nước, ánh sáng. Chứa chất thải (phân, rác được xử lí, phân huỷ). Bảo vệ: rừng giữ nước, chắn gió, điều hoà khí hậu.", "id": "KH5-B28-13", "mucDo": 3}], "chuDe": "6", "ten": "Chức năng của môi trường đối với sinh vật", "tenChuDe": "Chủ đề 6. Sinh vật và môi trường", "tenGoc": "Bài 28. Chức năng của môi trường đối với sinh vật", "tuan": "29–30", "yeuCauCanDat": ["Trình bày được các chức năng cơ bản của môi trường đối với sinh vật nói chung và con người nói riêng: cung cấp chỗ ở, thức ăn và những nhu cầu sống thiết yếu khác; nơi chứa đựng các chất thải do con người và sinh vật tạo ra trong quá trình sống; bảo vệ con người và sinh vật khỏi những tác động từ bên ngoài."]}, "29": {"cauHoi": [{"cauHoi": "Tài nguyên thiên nhiên là", "dang": "TN", "dapAn": 3, "giaiThich": "Theo bài.", "id": "KH5-B29-01", "mucDo": 1, "phuongAn": ["Chỉ có điện thoại", "Chỉ có nhà máy", "Chỉ có tiền", "Những gì có sẵn trong tự nhiên mà con người sử dụng, như đất, nước, rừng, khoáng sản, không khí"]}, {"cauHoi": "Ví dụ tác động tiêu cực của con người đến môi trường là", "dang": "TN", "dapAn": 2, "giaiThich": "Theo bài.", "id": "KH5-B29-02", "mucDo": 1, "phuongAn": ["Tiết kiệm nước, điện", "Trồng cây, bảo vệ rừng", "Đốt rừng, gây ô nhiễm đất, nước, không khí, làm sinh vật bị chết", "Phân loại rác"]}, {"cauHoi": "Ví dụ tác động tích cực của con người đến môi trường là", "dang": "TN", "dapAn": 0, "giaiThich": "Theo bài.", "id": "KH5-B29-03", "mucDo": 1, "phuongAn": ["Trồng cây, bảo vệ rừng, sử dụng tiết kiệm, xử lí rác, dùng năng lượng sạch hơn", "Xả rác xuống sông", "Săn bắt bừa bãi", "Đốt rơm rạ gây khói dày"]}, {"cauHoi": "Việc làm nào giúp bảo vệ môi trường?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo bài tập SGV.", "id": "KH5-B29-04", "mucDo": 1, "phuongAn": ["Dùng thuốc trừ sâu quá mức", "Không làm hại loài có ích, không gây ô nhiễm, trồng cây, tiết kiệm tài nguyên", "Vứt rác bừa bãi", "Đốt rừng lấy đất"]}, {"cauHoi": "Đốt rừng gây hại gì cho môi trường không khí và sinh vật?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo gợi ý SGV.", "id": "KH5-B29-05", "mucDo": 2, "phuongAn": ["Không ảnh hưởng gì", "Gây khói, bụi, ô nhiễm không khí, làm chết động vật, thực vật, thay đổi nơi ở của sinh vật", "Làm không khí trong lành hơn", "Giúp rừng dày hơn"]}, {"cauHoi": "Em có thể làm gì để bảo vệ cây xanh ở trường, ở nhà?", "dang": "TN", "dapAn": 3, "giaiThich": "Việc làm thiết thực.", "id": "KH5-B29-06", "mucDo": 2, "phuongAn": ["Bẻ cành cây chơi", "Buộc chặt cây đến chết", "Đổ nước bẩn vào gốc cây", "Trồng và chăm sóc cây, không bẻ cành, không khắc vào thân cây, nhắc bạn cùng giữ cây"]}, {"cauHoi": "Cách trình bày nào phù hợp để vận động mọi người bảo vệ môi trường?", "dang": "TN", "dapAn": 2, "giaiThich": "YCCĐ: hình ảnh, sơ đồ để vận động.", "id": "KH5-B29-07", "mucDo": 2, "phuongAn": ["Viết bài rất dài không ai đọc rồi cất đi", "Không nói gì", "Tranh, sơ đồ, khẩu hiệu ngắn, dễ nhớ về việc không xả rác, trồng cây, tiết kiệm điện nước", "Khuyến khích đốt rác giữa phố"]}, {"cauHoi": "Khi được mời món ăn làm từ động vật hoang dã quý hiếm, em nên ứng xử thế nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Bài tập SGV: từ chối món ăn hại loài hoang dã.", "id": "KH5-B29-08", "mucDo": 3, "phuongAn": ["Từ chối và đề nghị mọi người không dùng món đó", "Im lặng ủng hộ", "Ăn cho biết", "Khoe với bạn"]}, {"cauHoi": "Hãy chọn nhóm việc làm vừa giảm tác động tiêu cực vừa thể hiện sống hoà hợp với thiên nhiên.", "dang": "TN", "dapAn": 0, "giaiThich": "Vận dụng YCCĐ.", "id": "KH5-B29-09", "mucDo": 3, "phuongAn": ["Tiết kiệm điện nước, phân loại rác, trồng cây, không đốt rác bừa bãi, bảo vệ loài có ích", "Bắt hết chim ở vườn trường", "Để vòi nước chảy suốt ngày", "Đốt rừng, xả rác xuống kênh, dùng quá nhiều thuốc trừ sâu"]}, {"cauHoi": "Sử dụng tiết kiệm điện, nước là", "dang": "TN", "dapAn": 3, "giaiThich": "Việc làm thiết thực.", "id": "KH5-B29-10", "mucDo": 1, "phuongAn": ["Việc làm hại rừng", "Tác động tiêu cực", "Không liên quan môi trường", "Việc làm bảo vệ tài nguyên thiên nhiên và môi trường"]}, {"cauHoi": "Săn bắt, khai thác bừa bãi là", "dang": "TN", "dapAn": 2, "giaiThich": "Thu thập bằng chứng tác động tiêu cực.", "id": "KH5-B29-11", "mucDo": 1, "phuongAn": ["Bảo vệ đa dạng sinh học", "Tác động tích cực", "Tác động tiêu cực đến môi trường và tài nguyên", "Không ảnh hưởng gì"]}, {"cauHoi": "Phân loại rác, không vứt rác ra đường là việc", "dang": "TN", "dapAn": 1, "giaiThich": "Việc làm vừa sức học sinh.", "id": "KH5-B29-12", "mucDo": 2, "phuongAn": ["Chỉ dành cho người lớn", "Góp phần bảo vệ môi trường, giảm ô nhiễm", "Làm tăng rác thải ra sông", "Không cần thiết"]}, {"cauHoi": "Nêu một tác động tiêu cực, một tác động tích cực của con người đến môi trường và hai việc em sẽ làm, kèm cách em vận động mọi người.", "dang": "TL", "giaiThich": "Tiêu cực: đốt rừng, xả rác, ô nhiễm. Tích cực: trồng cây, bảo vệ rừng, dùng năng lượng sạch. Việc làm: phân loại rác, tiết kiệm điện nước, trồng cây. Vận động: vẽ tranh, sơ đồ, nhắc người thân.", "id": "KH5-B29-13", "mucDo": 3}], "chuDe": "6", "ten": "Tác động của con người và một số biện pháp bảo vệ môi trường", "tenChuDe": "Chủ đề 6. Sinh vật và môi trường", "tenGoc": "Bài 29. Tác động của con người và một số biện pháp bảo vệ môi trường", "tuan": "31–32", "yeuCauCanDat": ["Thu thập được một số thông tin, bằng chứng cho thấy con người có những tác động tiêu cực và những tác động tích cực đến môi trường và tài nguyên thiên nhiên.", "Thực hiện được một số việc làm thiết thực, phù hợp để góp phần bảo vệ tài nguyên thiên nhiên và môi trường.", "Xây dựng được nội dung và sử dụng cách trình bày phù hợp như dùng hình ảnh, sơ đồ,... để vận động mọi người cùng sống hoà hợp với thiên nhiên, bảo vệ môi trường và đa dạng sinh học ở địa phương."]}, "3": {"cauHoi": [{"cauHoi": "Hỗn hợp là gì?", "dang": "TN", "dapAn": 0, "giaiThich": "Hỗn hợp được tạo thành từ hai hay nhiều chất.", "id": "KH5-B03-01", "mucDo": 1, "phuongAn": ["Được tạo thành từ hai hay nhiều chất", "Chỉ gồm một chất duy nhất", "Luôn ở thể khí", "Không tồn tại trong đời sống"]}, {"cauHoi": "Dung dịch là gì?", "dang": "TN", "dapAn": 1, "giaiThich": "Dung dịch là hỗn hợp đặc biệt, chất hoà tan, không nhìn thấy riêng từng chất.", "id": "KH5-B03-02", "mucDo": 1, "phuongAn": ["Chỉ gồm không khí", "Một trường hợp đặc biệt của hỗn hợp, các chất hoà tan vào nhau, thường trong suốt, không còn nhìn thấy riêng từng chất", "Hỗn hợp luôn nhìn thấy rõ từng hạt", "Chất rắn không tan"]}, {"cauHoi": "Trộn muối ăn với hạt tiêu, vẫn nhìn thấy từng hạt. Đó là", "dang": "TN", "dapAn": 2, "giaiThich": "Vẫn nhìn thấy muối và tiêu nên là hỗn hợp, không phải dung dịch.", "id": "KH5-B03-03", "mucDo": 1, "phuongAn": ["Chất khí", "Dung dịch trong suốt", "Hỗn hợp, không phải dung dịch", "Một chất duy nhất"]}, {"cauHoi": "Khuấy muối ăn vào nước đến khi không còn nhìn thấy muối. Đó là", "dang": "TN", "dapAn": 0, "giaiThich": "Muối hoà tan, tạo dung dịch.", "id": "KH5-B03-04", "mucDo": 1, "phuongAn": ["Dung dịch", "Hỗn hợp không tan", "Khí cháy", "Chất rắn nguyên chất"]}, {"cauHoi": "Có thể tách muối ra khỏi dung dịch nước muối bằng cách nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Đun cho nước bay hơi, muối còn lại.", "id": "KH5-B03-05", "mucDo": 1, "phuongAn": ["Thêm đường vào", "Để yên, muối tự bay đi", "Lọc qua giấy như lọc cát", "Đun dung dịch để nước bay hơi, muối còn lại"]}, {"cauHoi": "Trong các hỗn hợp: vữa bê tông, sữa hộp, cồn, nước muối; những hỗn hợp nào là dung dịch?", "dang": "TN", "dapAn": 2, "giaiThich": "Cồn, nước muối là dung dịch; vữa bê tông, sữa hộp không trong suốt như dung dịch đã học.", "id": "KH5-B03-06", "mucDo": 2, "phuongAn": ["Chỉ vữa bê tông", "Vữa bê tông và sữa hộp", "Cồn và nước muối", "Tất cả đều không phải dung dịch"]}, {"cauHoi": "Nước đường, nước giấm loãng là dung dịch vì", "dang": "TN", "dapAn": 3, "giaiThich": "Sau khi hoà tan không còn nhìn thấy riêng từng chất.", "id": "KH5-B03-07", "mucDo": 2, "phuongAn": ["Vẫn nhìn thấy rõ hạt đường lắng đáy", "Chúng không phải là hỗn hợp", "Chúng chỉ gồm không khí", "Các chất đã hoà tan, dung dịch trong suốt, không nhìn thấy riêng từng chất"]}, {"cauHoi": "Khi đun dung dịch muối, hiện tượng nào xảy ra?", "dang": "TN", "dapAn": 1, "giaiThich": "Nước bay hơi, muối còn lại.", "id": "KH5-B03-08", "mucDo": 2, "phuongAn": ["Nước biến thành muối", "Nước bay hơi, muối xuất hiện dần", "Muối biến thành khí và biến mất", "Muối tan thêm mãi"]}, {"cauHoi": "Pha nước chanh đường: đường tan hết, hỗn hợp trong; còn xác chanh nổi. Phần nào là dung dịch?", "dang": "TN", "dapAn": 0, "giaiThich": "Phần trong là dung dịch; xác chanh không tan nên không thuộc dung dịch.", "id": "KH5-B03-09", "mucDo": 3, "phuongAn": ["Phần nước trong đã hoà tan đường và nước cốt chanh", "Cả xác chanh và nước", "Hạt đường chưa tan nếu còn lắng", "Xác chanh nổi trên mặt"]}, {"cauHoi": "Vì sao có thể thu muối từ nước biển bằng cách phơi nắng?", "dang": "TN", "dapAn": 3, "giaiThich": "Giống thí nghiệm đun dung dịch muối: nước bay hơi, muối còn lại.", "id": "KH5-B03-10", "mucDo": 3, "phuongAn": ["Nắng tạo ra muối mới", "Gió thổi muối từ trời xuống", "Muối bay hơi trước", "Nước bay hơi, muối còn lại"]}, {"cauHoi": "Nước cơm, gói ngũ cốc, gia vị muối tiêu là ví dụ về", "dang": "TN", "dapAn": 0, "giaiThich": "Ví dụ hỗn hợp trong đời sống.", "id": "KH5-B03-11", "mucDo": 1, "phuongAn": ["Hỗn hợp", "Một chất duy nhất", "Chất khí tinh khiết", "Dung dịch luôn trong suốt"]}, {"cauHoi": "Dụng cụ đun dung dịch muối cần lưu ý điều gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Thực hành an toàn theo bài.", "id": "KH5-B03-12", "mucDo": 1, "phuongAn": ["Đậy kín rồi lắc mạnh trên lửa", "Đun bằng tay không, không cần dụng cụ", "Bảo đảm an toàn khi đun, dùng dụng cụ chịu nhiệt", "Đun gần giấy dễ cháy mà không ai trông"]}, {"cauHoi": "Rượu hoà tan vào nước tạo thành", "dang": "TN", "dapAn": 1, "giaiThich": "Ví dụ dung dịch trong đời sống.", "id": "KH5-B03-13", "mucDo": 2, "phuongAn": ["Chất không phải hỗn hợp", "Dung dịch", "Hỗn hợp nhìn thấy rõ từng hạt rượu", "Chất rắn"]}, {"cauHoi": "Nêu cách tách muối ra khỏi dung dịch nước muối và hiện tượng quan sát được.", "dang": "TL", "giaiThich": "Đun dung dịch muối (an toàn); nước bay hơi, muối còn lại trên dụng cụ đun.", "id": "KH5-B03-14", "mucDo": 3}], "chuDe": "1", "ten": "Hỗn hợp và dung dịch", "tenChuDe": "Chủ đề 1. Chất", "tenGoc": "Bài 3. Hỗn hợp và dung dịch", "tuan": "3–4", "yeuCauCanDat": ["Phân biệt được hỗn hợp và dung dịch từ các ví dụ đã cho.", "Thực hành tách muối hoặc đường ra khỏi dung dịch muối hoặc đường."]}, "30": {"cauHoi": [{"cauHoi": "Ba chức năng cơ bản của môi trường là", "dang": "TN", "dapAn": 1, "giaiThich": "Ôn tập bài 28.", "id": "KH5-B30-01", "mucDo": 1, "phuongAn": ["Không có chức năng nào", "Cung cấp chỗ ở, thức ăn, nhu cầu thiết yếu; chứa chất thải; bảo vệ sinh vật và con người", "Chỉ chứa nhà máy", "Chỉ cung cấp đồ chơi"]}, {"cauHoi": "Đốt rừng, xả rác, gây ô nhiễm là", "dang": "TN", "dapAn": 2, "giaiThich": "Ôn tập bài 29.", "id": "KH5-B30-02", "mucDo": 1, "phuongAn": ["Tác động tích cực", "Việc bảo vệ đa dạng sinh học", "Tác động tiêu cực của con người đến môi trường", "Không phải tác động"]}, {"cauHoi": "Trồng cây, tiết kiệm tài nguyên, xử lí rác là", "dang": "TN", "dapAn": 0, "giaiThich": "Ôn tập.", "id": "KH5-B30-03", "mucDo": 1, "phuongAn": ["Tác động tích cực, việc làm bảo vệ môi trường", "Không liên quan", "Việc làm hại rừng", "Tác động tiêu cực"]}, {"cauHoi": "Đốt rơm rạ sau thu hoạch ảnh hưởng môi trường không khí như thế nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Tình huống ôn tập SGV.", "id": "KH5-B30-04", "mucDo": 2, "phuongAn": ["Chỉ làm đất tốt mà không ảnh hưởng không khí", "Không sinh khói", "Làm không khí trong lành hơn", "Gây khói, bụi, hạn chế tầm nhìn, ô nhiễm không khí"]}, {"cauHoi": "Phương án xử lí rơm rạ hợp lí hơn đốt là", "dang": "TN", "dapAn": 3, "giaiThich": "Gợi ý ôn tập: đề xuất phương án xử lí rơm rạ.", "id": "KH5-B30-05", "mucDo": 2, "phuongAn": ["Đốt trong phòng kín", "Đốt hết giữa trưa gần nhà", "Đổ xuống sông", "Ủ phân hữu cơ, trả lại dinh dưỡng cho đất, hạn chế đốt"]}, {"cauHoi": "Hãy nêu một việc hằng ngày em làm để chăm sóc cây hoặc bảo vệ môi trường và giải thích vì sao việc đó có lợi.", "dang": "TN", "dapAn": 0, "giaiThich": "Vận dụng kiến thức vào đời sống.", "id": "KH5-B30-06", "mucDo": 3, "phuongAn": ["Tưới cây, không bẻ cành, tắt vòi nước, bỏ rác đúng nơi, tiết kiệm điện; giúp cây sống, giảm ô nhiễm, giữ tài nguyên", "Xả rác ra vườn", "Để nước chảy suốt", "Đốt rác sau nhà"]}, {"cauHoi": "Xả rác xuống sông là", "dang": "TN", "dapAn": 1, "giaiThich": "Ôn tập.", "id": "KH5-B30-07", "mucDo": 1, "phuongAn": ["Chức năng bảo vệ của môi trường", "Tác động tiêu cực", "Tác động tích cực", "Việc làm bảo vệ nguồn nước"]}, {"cauHoi": "Em có thể chăm sóc cây hằng ngày bằng cách", "dang": "TN", "dapAn": 2, "giaiThich": "Vận dụng vào đời sống.", "id": "KH5-B30-08", "mucDo": 2, "phuongAn": ["Bẻ cành chơi", "Buộc chặt cây đến héo", "Tưới nước, không bẻ cành, không khắc lên thân cây", "Đổ nước bẩn vào gốc"]}, {"cauHoi": "Tóm tắt chủ đề bằng ba ý: chức năng môi trường; tác động của con người; việc làm bảo vệ môi trường.", "dang": "TL", "giaiThich": "Môi trường cung cấp nhu cầu sống, chứa chất thải, bảo vệ sinh vật. Con người có tác động tiêu cực và tích cực. Cần trồng cây, không gây ô nhiễm, tiết kiệm tài nguyên, vận động mọi người cùng làm.", "id": "KH5-B30-09", "mucDo": 3}], "chuDe": "6", "ten": "Ôn tập chủ đề Sinh vật và môi trường", "tenChuDe": "Chủ đề 6. Sinh vật và môi trường", "tenGoc": "Bài 30. Ôn tập chủ đề Sinh vật và môi trường", "tuan": "32", "yeuCauCanDat": ["Tóm tắt được những nội dung chính đã học dưới dạng sơ đồ.", "Vận dụng được kiến thức và kĩ năng của chủ đề vào giải quyết một số tình huống đơn giản trong đời sống."]}, "4": {"cauHoi": [{"cauHoi": "Chất có thể tồn tại ở những trạng thái cơ bản nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Ba trạng thái cơ bản: rắn, lỏng, khí.", "id": "KH5-B04-01", "mucDo": 1, "phuongAn": ["Chỉ khí", "Chỉ rắn", "Rắn, lỏng, khí", "Chỉ rắn và lỏng"]}, {"cauHoi": "Chất ở trạng thái rắn có đặc điểm nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Chất rắn có hình dạng và khoảng không gian xác định.", "id": "KH5-B04-02", "mucDo": 1, "phuongAn": ["Có hình dạng xác định và chiếm khoảng không gian xác định", "Luôn chiếm đầy toàn bộ vật chứa", "Không có hình dạng xác định", "Chảy được như nước"]}, {"cauHoi": "Chất ở trạng thái lỏng có đặc điểm nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Chất lỏng có hình dạng vật chứa, thể tích (khoảng không gian) xác định.", "id": "KH5-B04-03", "mucDo": 1, "phuongAn": ["Không chiếm khoảng không gian xác định", "Không có hình dạng xác định (có hình dạng vật chứa), chiếm khoảng không gian xác định", "Có hình dạng cố định như viên sỏi", "Không chảy được"]}, {"cauHoi": "Chất ở trạng thái khí có đặc điểm nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Khí có hình dạng vật chứa, khoảng không gian không xác định (có thể bị nén, dãn).", "id": "KH5-B04-04", "mucDo": 1, "phuongAn": ["Chỉ đứng yên một chỗ", "Có hình dạng cố định", "Không bị nén được", "Không có hình dạng xác định và không chiếm khoảng không gian xác định"]}, {"cauHoi": "Nến bị đốt nóng chảy là sự biến đổi trạng thái nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Nến nóng chảy: rắn thành lỏng.", "id": "KH5-B04-05", "mucDo": 1, "phuongAn": ["Từ rắn sang lỏng", "Từ lỏng sang khí", "Từ rắn sang khí ngay lập tức", "Từ khí sang rắn"]}, {"cauHoi": "Cát, tinh bột đổ vào cốc có hình dạng cốc. Vì sao chúng vẫn được xếp vào chất rắn?", "dang": "TN", "dapAn": 1, "giaiThich": "SGV lưu ý: mỗi hạt cát/tinh bột là chất rắn.", "id": "KH5-B04-06", "mucDo": 2, "phuongAn": ["Vì cát là chất khí", "Mỗi hạt nhỏ có hình dạng xác định, bị nén không chảy như chất lỏng", "Vì cát không chiếm khoảng không gian", "Vì cát là dung dịch"]}, {"cauHoi": "Bơm tiêm bịt kín, ấn ruột bơm vào được rồi thả tay ra ruột bơm trở lại. Điều đó cho thấy chất khí", "dang": "TN", "dapAn": 3, "giaiThich": "Thí nghiệm bơm tiêm với không khí.", "id": "KH5-B04-07", "mucDo": 2, "phuongAn": ["Không thể bị nén", "Chiếm khoảng không gian luôn không đổi", "Có hình dạng cố định", "Có thể bị nén và dãn, khoảng không gian không xác định"]}, {"cauHoi": "Nước đóng băng trong ngăn đá là sự biến đổi trạng thái nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Nước đông đặc thành đá.", "id": "KH5-B04-08", "mucDo": 2, "phuongAn": ["Từ rắn sang lỏng", "Từ khí sang lỏng", "Từ lỏng sang rắn", "Từ lỏng sang khí"]}, {"cauHoi": "Hơi nước gặp nắp ấm lạnh thành giọt nước là sự biến đổi trạng thái nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Hơi nước ngưng tụ thành nước.", "id": "KH5-B04-09", "mucDo": 2, "phuongAn": ["Từ khí sang lỏng", "Từ rắn sang khí", "Từ rắn sang lỏng", "Từ lỏng sang rắn"]}, {"cauHoi": "Đun chảy sô-cô-la rồi đổ vào khuôn, để nguội thành thỏi. Những biến đổi trạng thái nào đã xảy ra?", "dang": "TN", "dapAn": 1, "giaiThich": "Nóng chảy rồi đông đặc, chất vẫn là sô-cô-la.", "id": "KH5-B04-10", "mucDo": 2, "phuongAn": ["Chỉ có biến đổi hoá học tạo chất mới", "Rắn thành lỏng rồi lại thành rắn", "Khí thành rắn rồi thành khí", "Lỏng thành khí rồi thành khí khác"]}, {"cauHoi": "Con quạ thả sỏi vào bình nước để mực nước dâng lên, uống được nước. Hiện tượng này vận dụng đặc điểm nào của chất rắn?", "dang": "TN", "dapAn": 3, "giaiThich": "Sỏi chiếm chỗ, nước dâng lên.", "id": "KH5-B04-11", "mucDo": 3, "phuongAn": ["Chất rắn không chiếm khoảng không gian", "Chất rắn hoá khí ngay", "Chất rắn chảy như nước", "Chất rắn chiếm khoảng không gian xác định nên đẩy nước dâng lên"]}, {"cauHoi": "Nêu một ví dụ về biến đổi trạng thái của chất và gọi tên sự biến đổi đó.", "dang": "TL", "giaiThich": "Ví dụ: nước đóng thành đá (đông đặc); đá tan (nóng chảy); phơi áo ướt (bay hơi); hơi nước thành giọt sương (ngưng tụ); nến chảy (nóng chảy).", "id": "KH5-B04-12", "mucDo": 3}], "chuDe": "1", "ten": "Đặc điểm của chất ở trạng thái rắn, lỏng, khí. Sự biến đổi trạng thái của chất", "tenChuDe": "Chủ đề 1. Chất", "tenGoc": "Bài 4. Đặc điểm của chất ở trạng thái rắn, lỏng, khí. Sự biến đổi trạng thái của chất", "tuan": "4–5", "yeuCauCanDat": ["Nêu được ở mức độ đơn giản một số đặc điểm của chất ở trạng thái rắn, lỏng, khí.", "Trình bày được ví dụ về biến đổi trạng thái của chất."]}, "5": {"cauHoi": [{"cauHoi": "Sự biến đổi từ chất này thành chất khác được gọi là gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Khi tạo thành chất mới là biến đổi hoá học.", "id": "KH5-B05-01", "mucDo": 1, "phuongAn": ["Sự pha trộn hỗn hợp", "Sự biến đổi trạng thái", "Sự biến đổi hoá học", "Sự bay hơi"]}, {"cauHoi": "Ví dụ nào là biến đổi hoá học?", "dang": "TN", "dapAn": 2, "giaiThich": "Đinh gỉ tạo thành chất mới (gỉ sắt).", "id": "KH5-B05-02", "mucDo": 1, "phuongAn": ["Nước đóng thành đá", "Pha muối với tiêu", "Đinh sắt bị gỉ", "Nến chảy thành chất lỏng"]}, {"cauHoi": "Khi đốt tờ giấy, giấy chuyền từ màu trắng, hình chữ nhật thành chất màu đen, không còn hình dạng ban đầu. Đó là", "dang": "TN", "dapAn": 3, "giaiThich": "Giấy cháy tạo chất mới.", "id": "KH5-B05-03", "mucDo": 1, "phuongAn": ["Chỉ là biến đổi trạng thái", "Không có gì thay đổi", "Pha thành dung dịch", "Biến đổi hoá học"]}, {"cauHoi": "Đốt than, củi thường sinh ra khí. Đây là", "dang": "TN", "dapAn": 1, "giaiThich": "Than, củi cháy tạo chất mới (khi, tro,...).", "id": "KH5-B05-04", "mucDo": 1, "phuongAn": ["Không phải sự biến đổi của chất", "Biến đổi hoá học vì xuất hiện chất mới", "Chỉ là hỗn hợp bị chia nhỏ", "Chỉ là nước bay hơi"]}, {"cauHoi": "Trộn xi măng với cát, vẫn chỉ gồm xi măng và cát. Đó có phải biến đổi hoá học không?", "dang": "TN", "dapAn": 0, "giaiThich": "SGK: trộn xi măng và cát không phải biến đổi hoá học.", "id": "KH5-B05-05", "mucDo": 2, "phuongAn": ["Không, vì chưa xuất hiện chất mới", "Không, vì đó là chất khí", "Có, vì đã trộn đều", "Có, vì đổi màu nhẹ"]}, {"cauHoi": "Đun chảy nến rồi để đông đặc lại có phải biến đổi hoá học không?", "dang": "TN", "dapAn": 3, "giaiThich": "Đổi trạng thái, bản chất chất không đổi.", "id": "KH5-B05-06", "mucDo": 2, "phuongAn": ["Có, vì nến biến thành nước", "Không, vì nến hoá thành khí vĩnh viễn", "Có, vì đã tạo chất hoàn toàn mới", "Không, vì nến vẫn là nến, chỉ đổi trạng thái"]}, {"cauHoi": "Đường được đun, màu chuyển từ trắng sang vàng nâu rồi đen, vị cũng thay đổi. Đó là", "dang": "TN", "dapAn": 1, "giaiThich": "Dưới tác dụng của nhiệt, đường biến thành chất khác.", "id": "KH5-B05-07", "mucDo": 2, "phuongAn": ["Không có biến đổi", "Biến đổi hoá học, đã tạo chất mới", "Chỉ là đường tan vào không khí", "Chỉ là đường bị chia nhỏ"]}, {"cauHoi": "Pha loãng cồn với nước có phải biến đổi hoá học không?", "dang": "TN", "dapAn": 0, "giaiThich": "Pha loãng là hỗn hợp/dung dịch, không phải biến đổi hoá học.", "id": "KH5-B05-08", "mucDo": 2, "phuongAn": ["Không, đây là tạo dung dịch, không tạo chất mới", "Có, vì có lửa", "Có, vì cồn đã biến thành nước", "Không, vì cồn hoá thành khí ngay"]}, {"cauHoi": "Vì sao không nên đốt bếp than trong phòng kín để sưởi ấm?", "dang": "TN", "dapAn": 2, "giaiThich": "Đốt than sinh khí độc; phòng kín thiếu không khí rất nguy hiểm.", "id": "KH5-B05-09", "mucDo": 3, "phuongAn": ["Vì than không cháy được trong phòng", "Vì phòng kín làm than tự tắt ngay mà không sinh khí", "Vì đốt than là biến đổi hoá học, sinh ra khí độc, trong phòng kín rất nguy hiểm", "Vì than chỉ tạo hơi nước có lợi"]}, {"cauHoi": "Hàng rào sắt để lâu ngoài trời bị đổi màu, ăn mòn. Giải thích hiện tượng này.", "dang": "TN", "dapAn": 2, "giaiThich": "Sắt gỉ là ví dụ điển hình về biến đổi hoá học trong SGK.", "id": "KH5-B05-10", "mucDo": 2, "phuongAn": ["Đó là biến đổi trạng thái từ rắn sang lỏng", "Sắt hoá thành khí rồi biến mất", "Đinh, sắt bị gỉ: biến đổi hoá học, sắt tạo thành chất mới màu nâu đỏ, giòn, xốp", "Sắt chỉ bị ướt, không đổi chất"]}, {"cauHoi": "Xé nhỏ tờ giấy có phải biến đổi hoá học không?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo bài tập: xé giấy không phải biến đổi hoá học.", "id": "KH5-B05-11", "mucDo": 1, "phuongAn": ["Không, giấy vẫn là giấy, chỉ bị chia nhỏ", "Không, vì giấy hoá thành sắt", "Có, vì giấy hoá khí ngay", "Có, vì đã tạo chất mới"]}, {"cauHoi": "Bơ chảy lỏng trên chảo nóng là", "dang": "TN", "dapAn": 3, "giaiThich": "Bơ chảy là nóng chảy.", "id": "KH5-B05-12", "mucDo": 1, "phuongAn": ["Sự ô nhiễm đất", "Sự tạo dung dịch muối", "Biến đổi hoá học tạo chất mới", "Biến đổi trạng thái, không phải biến đổi hoá học"]}, {"cauHoi": "Cồn được đốt cháy trên bếp là hiện tượng nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Bài tập chủ đề: cồn cháy là biến đổi hoá học.", "id": "KH5-B05-13", "mucDo": 2, "phuongAn": ["Không có sự biến đổi", "Biến đổi hoá học", "Chỉ là biến đổi trạng thái của nước", "Chỉ là pha loãng cồn với nước"]}, {"cauHoi": "Nêu hai ví dụ biến đổi hoá học thường gặp trong đời sống.", "dang": "TL", "giaiThich": "Ví dụ: đinh bị gỉ, giấy cháy, than cháy, gỗ cháy, đường đun thành chất khác, tàu thép bị rỉ sét.", "id": "KH5-B05-14", "mucDo": 3}], "chuDe": "1", "ten": "Sự biến đổi hoá học của chất", "tenChuDe": "Chủ đề 1. Chất", "tenGoc": "Bài 5. Sự biến đổi hoá học của chất", "tuan": "5–6", "yeuCauCanDat": ["Trình bày được một số ví dụ đơn giản gần gũi với cuộc sống về biến đổi hoá học (ví dụ: đinh bị gỉ, giấy cháy, than cháy,...)."]}, "6": {"cauHoi": [{"cauHoi": "Thành phần chính của đất gồm", "dang": "TN", "dapAn": 0, "giaiThich": "Ôn tập thành phần đất.", "id": "KH5-B06-01", "mucDo": 1, "phuongAn": ["Chất khoáng, mùn, nước, không khí", "Chỉ có không khí", "Chỉ có ánh sáng", "Chỉ có nước biển"]}, {"cauHoi": "Dung dịch khác hỗn hợp thông thường ở điểm nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Dung dịch là hỗn hợp đặc biệt.", "id": "KH5-B06-02", "mucDo": 1, "phuongAn": ["Không phải là hỗn hợp", "Luôn nhìn thấy rõ từng hạt", "Các chất hoà tan vào nhau, thường trong suốt, không nhìn thấy riêng từng chất", "Chỉ gồm chất khí"]}, {"cauHoi": "Hình đường đun chuyển màu, vị khác hẳn là hiện tượng nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Đường biến thành chất khác.", "id": "KH5-B06-03", "mucDo": 2, "phuongAn": ["Chỉ là hỗn hợp bị chia nhỏ", "Biến đổi hoá học", "Biến đổi trạng thái", "Không có gì xảy ra"]}, {"cauHoi": "Đun chảy sô-cô-la rồi đổ khuôn để nguội là hiện tượng nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Nóng chảy rồi đông đặc.", "id": "KH5-B06-04", "mucDo": 2, "phuongAn": ["Biến đổi hoá học tạo chất mới", "Ô nhiễm đất", "Tạo khí độc", "Biến đổi trạng thái"]}, {"cauHoi": "Muốn chống xói mòn đất ở sườn dốc, nên làm gì?", "dang": "TN", "dapAn": 3, "giaiThich": "Biện pháp chống xói mòn đã học.", "id": "KH5-B06-05", "mucDo": 2, "phuongAn": ["Đổ rác xuống dốc", "Cày sạch rồi để đất trống", "Phá hết cây", "Trồng cây, làm ruộng bậc thang, che phủ đất"]}, {"cauHoi": "Vì sao không nên đổ nước thải chưa xử lí ra vườn?", "dang": "TN", "dapAn": 2, "giaiThich": "Nước thải chưa xử lí là nguyên nhân ô nhiễm đất.", "id": "KH5-B06-06", "mucDo": 3, "phuongAn": ["Vì nước thải giúp đất tốt hơn", "Vì đất không thấm nước thải", "Vì làm ô nhiễm đất, ảnh hưởng cây trồng, động vật và sức khoẻ con người", "Vì nước thải tự biến thành phân hữu cơ ngay"]}, {"cauHoi": "Em cần làm gì để vừa bảo vệ đất vừa dùng đúng hỗn hợp, dung dịch trong đời sống?", "dang": "TN", "dapAn": 1, "giaiThich": "Vận dụng kiến thức cả chủ đề Chất.", "id": "KH5-B06-07", "mucDo": 2, "phuongAn": ["Đốt than trong phòng kín mỗi tối", "Không đổ hoá chất, rác ra đất; biết dung dịch khác hỗn hợp chưa tan; không đốt rác, than trong phòng kín", "Đổ hết hoá chất xuống đất cho nhanh", "Dùng thật nhiều thuốc trừ sâu"]}, {"cauHoi": "Nêu một việc làm bảo vệ đất và một ví dụ phân biệt biến đổi trạng thái với biến đổi hoá học.", "dang": "TL", "giaiThich": "Bảo vệ đất: không đổ rác, trồng cây, xử lí chất thải. Ví dụ: nước đóng băng là đổi trạng thái; đinh gỉ, giấy cháy là biến đổi hoá học.", "id": "KH5-B06-08", "mucDo": 3}], "chuDe": "1", "ten": "Ôn tập chủ đề Chất", "tenChuDe": "Chủ đề 1. Chất", "tenGoc": "Bài 6. Ôn tập chủ đề Chất", "tuan": "6", "yeuCauCanDat": ["Tóm tắt được những nội dung chính đã học dưới dạng sơ đồ.", "Vận dụng được kiến thức và kĩ năng của chủ đề vào giải quyết một số tình huống đơn giản trong đời sống."]}, "7": {"cauHoi": [{"cauHoi": "Con người sử dụng năng lượng để làm gì?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo SGK: sống, phát triển và vận động.", "id": "KH5-B07-01", "mucDo": 1, "phuongAn": ["Để sống, phát triển và vận động", "Chỉ để đốt lửa cho vui", "Không cần năng lượng", "Chỉ để chơi trò chơi"]}, {"cauHoi": "Năng lượng mà con người dùng để sống, phát triển chủ yếu lấy từ đâu?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo SGK/SGV.", "id": "KH5-B07-02", "mucDo": 1, "phuongAn": ["Xăng dầu", "Gió", "Than đá", "Thức ăn và nước uống"]}, {"cauHoi": "Nguồn năng lượng thông dụng được giới thiệu trong chủ đề gồm", "dang": "TN", "dapAn": 1, "giaiThich": "Năm nguồn thông dụng trong SGK lớp 5.", "id": "KH5-B07-03", "mucDo": 1, "phuongAn": ["Chỉ có sức người", "Năng lượng mặt trời, gió, nước chảy, chất đốt và điện", "Chỉ có than đá", "Chỉ có năng lượng điện"]}, {"cauHoi": "Mặt Trời cung cấp năng lượng cho đối tượng nào dưới đây?", "dang": "TN", "dapAn": 2, "giaiThich": "Mặt Trời cung cấp năng lượng cho thực vật.", "id": "KH5-B07-04", "mucDo": 1, "phuongAn": ["Chỉ có dầu mỏ", "Chỉ có than đá dưới đất", "Cây cối, rau trong vườn", "Chỉ có tụ điện"]}, {"cauHoi": "Chong chóng và tua-bin gió hoạt động nhờ nguồn năng lượng nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Gió làm chong chóng, tua-bin quay.", "id": "KH5-B07-05", "mucDo": 1, "phuongAn": ["Năng lượng gió", "Năng lượng hoá học của đường", "Năng lượng chất đốt", "Năng lượng điện trong pin"]}, {"cauHoi": "Phơi quần áo chủ yếu sử dụng nguồn năng lượng nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Phơi quần áo dùng năng lượng mặt trời.", "id": "KH5-B07-06", "mucDo": 2, "phuongAn": ["Năng lượng gió là nguồn duy nhất", "Năng lượng điện", "Năng lượng mặt trời", "Năng lượng chất đốt"]}, {"cauHoi": "Nướng khoai trên bếp than chủ yếu dùng nguồn năng lượng nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Than là chất đốt.", "id": "KH5-B07-07", "mucDo": 2, "phuongAn": ["Năng lượng chất đốt", "Năng lượng gió", "Năng lượng nước chảy", "Năng lượng mặt trời trực tiếp"]}, {"cauHoi": "Thả diều sử dụng nguồn năng lượng nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Diều bay nhờ gió.", "id": "KH5-B07-08", "mucDo": 2, "phuongAn": ["Năng lượng điện", "Năng lượng nước chảy", "Năng lượng chất đốt", "Năng lượng gió"]}, {"cauHoi": "Khi đạp xe, em là nguồn cung cấp năng lượng cho xe. Năng lượng của em lấy từ đâu?", "dang": "TN", "dapAn": 1, "giaiThich": "Theo bài luyện tập SGK.", "id": "KH5-B07-09", "mucDo": 2, "phuongAn": ["Chỉ từ pin điện thoại", "Thức ăn và nước uống hằng ngày", "Chỉ từ gió thổi", "Chỉ từ xăng trong xe"]}, {"cauHoi": "Đun 1 lít nước từ 25 độ C đến 65 độ C so với đun đến khi sôi, trường hợp nào tiêu thụ nhiều năng lượng điện hơn? Vì sao?", "dang": "TN", "dapAn": 2, "giaiThich": "Theo bài tập SGV/SGK: thay đổi nhiệt độ nhiều hơn thì cần nhiều năng lượng hơn.", "id": "KH5-B07-10", "mucDo": 3, "phuongAn": ["Đun đến sôi dùng ít hơn vì nước tự sôi", "Hai trường hợp dùng đúng bằng nhau", "Đun đến khi sôi, vì cần làm thay đổi nhiệt độ của nước nhiều hơn", "Đun đến 65 độ C, vì nước lạnh hơn"]}, {"cauHoi": "Nước chảy cung cấp năng lượng cho hoạt động nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Nguồn nước chảy trong bài 7, hình minh hoạ.", "id": "KH5-B07-11", "mucDo": 1, "phuongAn": ["Làm quay tua-bin, máy phát điện hoặc máy cơ đơn giản", "Thắp đèn pin", "Đốt bếp than", "Phơi muối"]}, {"cauHoi": "Dầu đi-ê-den dùng ở động cơ đốt trong làm tàu hoả chạy là sử dụng nguồn nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Ví dụ sử dụng chất đốt trong SGV/SGK.", "id": "KH5-B07-12", "mucDo": 1, "phuongAn": ["Năng lượng mặt trời trực tiếp", "Năng lượng nước chảy", "Năng lượng gió", "Năng lượng chất đốt"]}, {"cauHoi": "Rau trong vườn lớn lên chủ yếu nhờ nguồn năng lượng nào?", "dang": "TN", "dapAn": 1, "giaiThich": "Mặt Trời cung cấp năng lượng cho thực vật.", "id": "KH5-B07-13", "mucDo": 2, "phuongAn": ["Năng lượng trong pin", "Năng lượng mặt trời", "Năng lượng than đá", "Năng lượng xăng"]}, {"cauHoi": "Kể ba nguồn năng lượng thông dụng và một việc sử dụng mỗi nguồn đó trong đời sống.", "dang": "TL", "giaiThich": "Ví dụ: mặt trời (phơi quần áo, phơi thóc); gió (thả diều, tua-bin gió); nước chảy (thuỷ điện, cối nước); chất đốt (đun nấu); điện (thắp sáng, quạt).", "id": "KH5-B07-14", "mucDo": 3}], "chuDe": "2", "ten": "Vai trò của năng lượng", "tenChuDe": "Chủ đề 2. Năng lượng", "tenGoc": "Bài 7. Vai trò của năng lượng", "tuan": "7", "yeuCauCanDat": ["Trình bày được một số nguồn năng lượng thông dụng và việc sử dụng chúng trong cuộc sống hằng ngày."]}, "8": {"cauHoi": [{"cauHoi": "Khi rút phích cắm, nên làm thế nào cho an toàn?", "dang": "TN", "dapAn": 0, "giaiThich": "Không nắm dây để rút phích cắm.", "id": "KH5-B08-01", "mucDo": 1, "phuongAn": ["Cầm phích cắm, không nắm dây điện để kéo", "Cắm tay vào lỗ ổ điện", "Rút khi tay ướt", "Nắm dây điện giật mạnh"]}, {"cauHoi": "Việc nào là không an toàn khi sử dụng điện?", "dang": "TN", "dapAn": 3, "giaiThich": "Không sửa điện khi ẩm ướt, chưa cắt nguồn.", "id": "KH5-B08-02", "mucDo": 1, "phuongAn": ["Nhờ người lớn sửa khi dây bị hở", "Dùng dụng cụ cách điện", "Rút phích cắm trước khi sửa", "Sửa chữa thiết bị điện khi trời mưa, tay ướt, không cắt nguồn điện"]}, {"cauHoi": "Việc làm nào giúp tiết kiệm điện ở nhà và ở trường?", "dang": "TN", "dapAn": 1, "giaiThich": "Tắt thiết bị khi không sử dụng.", "id": "KH5-B08-03", "mucDo": 1, "phuongAn": ["Để đèn sáng cả ngày khi không có người", "Tắt đèn, quạt, thiết bị khi không dùng", "Dùng nhiều bóng đèn khi không cần", "Mở tủ lạnh lâu, đứng quạt cửa"]}, {"cauHoi": "Khi thay bóng đèn bàn học, cần làm gì trước?", "dang": "TN", "dapAn": 2, "giaiThich": "Rút phích cắm trước khi thay bóng.", "id": "KH5-B08-04", "mucDo": 1, "phuongAn": ["Dùng tay ướt vặn bóng", "Đứng chân trần trên nền ướt", "Rút phích cắm ra khỏi ổ điện", "Thay khi đèn vẫn còn cắm điện"]}, {"cauHoi": "Không nên dùng điện thoại khi nào?", "dang": "TN", "dapAn": 2, "giaiThich": "Đang sạc có nguy cơ giật hoặc sự cố.", "id": "KH5-B08-05", "mucDo": 1, "phuongAn": ["Khi pin còn đầy và đã rút sạc", "Khi máy đã tắt nguồn và không sạc", "Khi đang cắm sạc điện", "Khi để máy trên bàn khô"]}, {"cauHoi": "Vì sao không nên sấy tóc khi đang đứng trên sàn nhà tắm ướt?", "dang": "TN", "dapAn": 1, "giaiThich": "Nền ướt làm tăng nguy cơ điện giật.", "id": "KH5-B08-06", "mucDo": 2, "phuongAn": ["Vì máy sấy không hoạt động được", "Vì dễ bị điện giật", "Vì tốn nước", "Vì tóc khô chậm hơn"]}, {"cauHoi": "Thấy dây điện bị hở, em nên làm gì?", "dang": "TN", "dapAn": 0, "giaiThich": "Không chạm, báo người lớn.", "id": "KH5-B08-07", "mucDo": 2, "phuongAn": ["Không chạm vào, báo người lớn để sửa chỗ hở", "Cắm thêm ổ vào chỗ hở", "Sờ thử xem có giật không", "Tự quấn băng keo khi tay ướt"]}, {"cauHoi": "Việc làm nào vừa an toàn vừa tiết kiệm điện?", "dang": "TN", "dapAn": 3, "giaiThich": "Rút phích, tắt đèn khi không dùng.", "id": "KH5-B08-08", "mucDo": 2, "phuongAn": ["Dùng nhiều thiết bị cùng lúc không cần thiết", "Để tivi bật cả đêm", "Sạc điện thoại suốt ngày trên giường", "Rút phích cắm thiết bị khi không dùng, tắt đèn khi ra khỏi phòng"]}, {"cauHoi": "Hãy chọn cách trình bày đơn giản để vận động gia đình dùng điện an toàn, tiết kiệm.", "dang": "TN", "dapAn": 3, "giaiThich": "YCCĐ: dùng hình ảnh, sơ đồ dễ nhớ để vận động mọi người.", "id": "KH5-B08-09", "mucDo": 3, "phuongAn": ["Khuyến khích để đèn sáng suốt đêm", "Viết bài văn rất dài không ai đọc", "Không nói gì với người thân", "Làm sơ đồ hoặc tranh: tắt đèn khi ra khỏi phòng, không sửa điện khi tay ướt, rút phích khi không dùng"]}, {"cauHoi": "Đi chân trần, cắm phích quạt vào ổ khi dây điện bị hở có thể dẫn đến điều gì? Nên làm gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Tình huống ôn tập an toàn điện.", "id": "KH5-B08-10", "mucDo": 3, "phuongAn": ["Làm quạt quay nhanh hơn", "Không sao cả; cứ cắm tiếp", "Có thể bị điện giật; không cắm, báo người lớn sửa chỗ hở", "Chỉ tốn điện; không liên quan an toàn"]}, {"cauHoi": "Mở tủ lạnh lâu, đứng quạt cửa tủ lạnh là việc", "dang": "TN", "dapAn": 0, "giaiThich": "Việc cần tránh để tiết kiệm điện.", "id": "KH5-B08-11", "mucDo": 1, "phuongAn": ["Gây lãng phí điện", "Tiết kiệm điện", "Không liên quan đến điện", "Làm tăng an toàn điện"]}, {"cauHoi": "Khi sửa thiết bị điện, nên", "dang": "TN", "dapAn": 1, "giaiThich": "Quy tắc an toàn điện.", "id": "KH5-B08-12", "mucDo": 1, "phuongAn": ["Sửa khi tay ướt và nguồn vẫn bật", "Ngắt nguồn, dùng dụng cụ cách điện, nhờ người lớn nếu chưa chắc", "Sửa ngoài mưa", "Sờ dây trần để thử"]}, {"cauHoi": "Vì sao tắt đèn, quạt khi ra khỏi phòng vừa tiết kiệm vừa dễ thực hiện?", "dang": "TN", "dapAn": 1, "giaiThich": "Vận dụng tiết kiệm điện ở nhà, ở trường.", "id": "KH5-B08-13", "mucDo": 2, "phuongAn": ["Vì quạt cần chạy khi không có người", "Thiết bị không dùng vẫn tốn điện nếu còn bật; tắt khi ra khỏi phòng là việc làm ngay được", "Vì đèn tự tắt thì tốn hơn", "Vì điện không bao giờ hết"]}, {"cauHoi": "Nêu hai quy tắc an toàn điện và hai việc tiết kiệm điện em thực hiện ở nhà hoặc ở trường.", "dang": "TL", "giaiThich": "An toàn: không sửa điện khi tay ướt, rút phích trước khi thay bóng, không nắm dây để rút phích, không dùng điện thoại khi đang sạc. Tiết kiệm: tắt đèn, quạt khi ra khỏi phòng, rút phích khi không dùng, không mở tủ lạnh lâu.", "id": "KH5-B08-14", "mucDo": 3}], "chuDe": "2", "ten": "Sử dụng năng lượng điện", "tenChuDe": "Chủ đề 2. Năng lượng", "tenGoc": "Bài 8. Sử dụng năng lượng điện", "tuan": "8", "yeuCauCanDat": ["Nêu được một số quy tắc cơ bản về an toàn điện và tuân thủ các quy tắc an toàn điện trong tình huống thường gặp.", "Nêu và thực hiện được việc làm thiết thực để tiết kiệm năng lượng điện ở trường và ở nhà.", "Đề xuất và trình bày được những việc cần làm để sử dụng an toàn, tiết kiệm năng lượng điện một cách đơn giản, dễ nhớ để vận động gia đình và cộng đồng cùng thực hiện."]}, "9": {"cauHoi": [{"cauHoi": "Mạch điện thắp sáng đơn giản gồm những bộ phận nào?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo YCCĐ và SGK.", "id": "KH5-B09-01", "mucDo": 1, "phuongAn": ["Nguồn điện (pin), công tắc, bóng đèn và dây dẫn điện", "Chỉ có công tắc", "Chỉ có pin, không cần dây", "Chỉ có bóng đèn"]}, {"cauHoi": "Đèn pin có những bộ phận chính nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Theo SGK.", "id": "KH5-B09-02", "mucDo": 1, "phuongAn": ["Chỉ có công tắc", "Chỉ có kính", "Chỉ có vỏ nhựa", "Pin, bóng đèn, công tắc và dây dẫn điện"]}, {"cauHoi": "Nguồn năng lượng làm đèn pin sáng là gì?", "dang": "TN", "dapAn": 2, "giaiThich": "Pin là nguồn điện.", "id": "KH5-B09-03", "mucDo": 1, "phuongAn": ["Gió", "Nước chảy", "Pin", "Ánh sáng mặt trời chiếu vào bóng"]}, {"cauHoi": "Khi khoá K (công tắc) đóng, mạch kín, đèn sáng vì", "dang": "TN", "dapAn": 0, "giaiThich": "Mạch kín thì đèn sáng.", "id": "KH5-B09-04", "mucDo": 1, "phuongAn": ["Dòng điện chạy được trong mạch", "Không có nguồn điện", "Mạch bị đứt", "Đèn không cần điện"]}, {"cauHoi": "Khi công tắc mở, mạch hở, đèn không sáng vì", "dang": "TN", "dapAn": 2, "giaiThich": "Mạch hở có khoảng trống, dòng điện không chạy.", "id": "KH5-B09-05", "mucDo": 1, "phuongAn": ["Pin mạnh hơn", "Bóng đèn tự tắt cho vui", "Dòng điện không chạy được qua mạch hở", "Dây dẫn quá tốt"]}, {"cauHoi": "Quy ước chiều dòng điện trong mạch đèn pin là", "dang": "TN", "dapAn": 1, "giaiThich": "Theo SGK/SGV.", "id": "KH5-B09-06", "mucDo": 2, "phuongAn": ["Không có chiều", "Từ cực dương của pin qua bóng đèn, dây dẫn, công tắc về cực âm", "Chỉ chạy trong bóng, không về pin", "Từ cực âm sang cực dương theo chiều ngược lại với quy ước"]}, {"cauHoi": "Làm thế nào để biết một vật dẫn điện hay cách điện?", "dang": "TN", "dapAn": 3, "giaiThich": "Cách thí nghiệm đã học.", "id": "KH5-B09-07", "mucDo": 2, "phuongAn": ["Cân xem vật nặng hay nhẹ", "Nhìn màu sắc của vật", "Nếm vật đó", "Nối vật đó vào mạch có pin và bóng đèn: đèn sáng thì vật dẫn điện, đèn không sáng thì vật cách điện"]}, {"cauHoi": "Vật dẫn điện là vật", "dang": "TN", "dapAn": 3, "giaiThich": "Định nghĩa theo bài.", "id": "KH5-B09-08", "mucDo": 2, "phuongAn": ["Chỉ dẫn nhiệt", "Không cho dòng điện chạy qua", "Chỉ dẫn ánh sáng", "Cho dòng điện chạy qua"]}, {"cauHoi": "Vật cách điện là vật", "dang": "TN", "dapAn": 2, "giaiThich": "Định nghĩa theo bài.", "id": "KH5-B09-09", "mucDo": 2, "phuongAn": ["Luôn làm đèn sáng", "Cho dòng điện chạy qua rất mạnh", "Không cho dòng điện chạy qua", "Luôn là kim loại"]}, {"cauHoi": "Vì sao dây dẫn điện có lõi và vỏ?", "dang": "TN", "dapAn": 1, "giaiThich": "Lõi dẫn điện, vỏ cách điện.", "id": "KH5-B09-10", "mucDo": 2, "phuongAn": ["Cả lõi và vỏ đều cách điện", "Lõi cho dòng điện chạy qua, vỏ cách điện để dùng an toàn", "Cả lõi và vỏ đều dẫn điện", "Vỏ dùng để dẫn điện, lõi để trang trí"]}, {"cauHoi": "Nếu phần lõi dây điện bị đứt, điều gì xảy ra? Nếu chỉ vỏ bị hỏng thì sao?", "dang": "TN", "dapAn": 0, "giaiThich": "Theo bài tập SGV.", "id": "KH5-B09-11", "mucDo": 3, "phuongAn": ["Lõi đứt thì dây không dẫn điện được; vỏ hỏng thì không an toàn, không nên dùng", "Lõi đứt thì càng an toàn", "Vỏ hỏng thì dây dẫn tốt hơn", "Cả hai trường hợp đèn vẫn sáng bình thường"]}, {"cauHoi": "Muốn đèn sáng khi lắp vật vào hai kẹp của mạch thử, cần chọn loại vật nào?", "dang": "TN", "dapAn": 3, "giaiThich": "Chỉ vật dẫn điện mới khép kín mạch, đèn sáng.", "id": "KH5-B09-12", "mucDo": 3, "phuongAn": ["Tờ giấy khô", "Mảnh vải", "Vật cách điện như nhựa, cao su, gỗ khô", "Vật dẫn điện, ví dụ kim loại như đồng, nhôm"]}, {"cauHoi": "Mô tả hoạt động của mạch điện thắp sáng đơn giản khi công tắc đóng và khi công tắc mở.", "dang": "TL", "giaiThich": "Công tắc đóng: mạch kín, dòng điện chạy từ nguồn qua đèn, đèn sáng. Công tắc mở: mạch hở, dòng điện không chạy, đèn tắt.", "id": "KH5-B09-13", "mucDo": 3}], "chuDe": "2", "ten": "Mạch điện đơn giản. Vật dẫn điện và vật cách điện", "tenChuDe": "Chủ đề 2. Năng lượng", "tenGoc": "Bài 9. Mạch điện đơn giản. Vật dẫn điện và vật cách điện", "tuan": "9", "yeuCauCanDat": ["Mô tả được cấu tạo và hoạt động của mạch điện thắp sáng gồm: nguồn điện, công tắc và bóng đèn.", "Đề xuất được cách làm thí nghiệm để xác định vật dẫn điện, vật cách điện.", "Giải thích được lí do sử dụng vật dẫn điện, vật cách điện trong một số đồ vật, tình huống thường gặp."]}}, "lop": 5, "mon": "Khoa học", "phienBan": "nen-004-v1"}};
